                    </div>
                </div>

                {/* CTA */}
                <div className={styles.ctaWrapper}>
                    <Link href="/browse-jobs" className={styles.browseBtn}>
                        Browse all jobs
                        <svg width="18" height="18" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                            <path strokeLinecap="round" strokeLinejoin="round" d="M17 8l4 4m0 0l-4 4m4-4H3" />
                        </svg>
                    </Link>
                </div>
            </div>
        </section>
    );
};

export default JobListings;

/* ─── Section ─────────────────────────────────────────────── */
.section {
    padding: 7rem 2rem;
    background: #f8fafc;
    color: #111111;
    overflow-x: hidden;
}

.container {
    max-width: 1180px;
    margin: 0 auto;
    width: 100%;
}

/* ─── Headline ────────────────────────────────────────────── */
.headlineGroup {
    text-align: center;
    margin-bottom: 3rem;
}

.title {
    font-size: 2.85rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.03em;
    line-height: 1.15;
    margin: 0 0 0.75rem;
}

.highlight {
    color: #3b82f6;
}

.subtitle {
    font-size: 1.05rem;
    color: #94a3b8;
    margin: 0;
    font-weight: 400;
}

/* ─── Mock App Window ─────────────────────────────────────── */
.appWindow {
    background: #ffffff;
    border-radius: 1.5rem;
    box-shadow:
        0 25px 60px -12px rgba(0, 0, 0, 0.12),
        0 8px 20px -8px rgba(0, 0, 0, 0.06);
    border: 1px solid rgba(226, 232, 240, 0.8);
    overflow: hidden;
}

.windowBar {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 1rem 1.5rem;
    background: #f8fafc;
    border-bottom: 1px solid #e2e8f0;
}

.dot {
    width: 12px;
    height: 12px;
    border-radius: 50%;
    display: inline-block;
    opacity: 0.85;
}

/* ─── Layout ──────────────────────────────────────────────── */
.layout {
    display: grid;
    grid-template-columns: 240px 1fr;
    min-height: 460px;
}

/* ─── Sidebar ─────────────────────────────────────────────── */
.sidebar {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    padding: 1.5rem 1rem;
    border-right: 1px solid #f1f5f9;
    background: #fafafa;
}

.sidebarLabel {
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: #94a3b8;
    padding: 0 0.75rem;
    margin: 0 0 0.5rem;
}

.categoryItem {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.7rem 0.85rem;
    border-radius: 0.65rem;
    background: transparent;
    border: none;
    cursor: pointer;
    text-align: left;
    transition: all 0.18s cubic-bezier(0.4, 0, 0.2, 1);
    color: #475569;
    font-size: 0.875rem;
    font-family: inherit;
    width: 100%;
    font-weight: 500;
}

.categoryItem:hover {
    background: #f1f5f9;
    color: #1e293b;
}

.categoryActive {
    background: #eff6ff !important;
    color: #2563eb !important;
    font-weight: 600;
}

.categoryActive .categoryIcon {
    color: #2563eb !important;
}

.categoryIcon {
    width: 20px;
    height: 20px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #94a3b8;
    transition: color 0.18s;
}

.categoryLabel {
    line-height: 1.3;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* ─── Jobs Panel ──────────────────────────────────────────── */
.jobsPanel {
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
    gap: 0;
}

.jobList {
    display: flex;
    flex-direction: column;
    gap: 0.875rem;
}

/* ─── Job Card ────────────────────────────────────────────── */
.jobCard {
    display: flex;
    align-items: center;
    justify-content: space-between;
    background: white;
    border: 1px solid #e8edf2;
    border-radius: 1rem;
    padding: 1.25rem 1.5rem;
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
    gap: 1rem;
    cursor: pointer;
}

.jobCard:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 25px -5px rgba(59, 130, 246, 0.12), 0 4px 10px -5px rgba(59, 130, 246, 0.08);
    border-color: #bfdbfe;
}

.jobInfo {
    display: flex;
    align-items: center;
    gap: 1.125rem;
    flex: 1;
    min-width: 0;
}

.jobLogo {
    width: 3rem;
    height: 3rem;
    border-radius: 0.75rem;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.8rem;
    font-weight: 700;
    flex-shrink: 0;
    letter-spacing: 0.03em;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1);
}

.jobDetails {
    min-width: 0;
    flex: 1;
}

.jobTitle {
    font-size: 1rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0 0 0.35rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* ─── Metadata row ────────────────────────────────────────── */
.jobMeta {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.metaItem {
    font-size: 0.8rem;
    color: #64748b;
    display: flex;
    align-items: center;
    gap: 0.25rem;
    white-space: nowrap;
}

.metaDot {
    width: 3px;
    height: 3px;
    border-radius: 50%;
    background: #cbd5e1;
    flex-shrink: 0;
}

/* ─── Right side: badge + button ─────────────────────────── */
.jobActions {
    display: flex;
    align-items: center;
    gap: 0.875rem;
    flex-shrink: 0;
}

/* Pill badges */
.badge {
    font-size: 0.75rem;
    font-weight: 600;
    padding: 0.3rem 0.85rem;
    border-radius: 9999px;
    white-space: nowrap;
}

.badgeBlue {
    background: #dbeafe;
    color: #1d4ed8;
}

.badgeGray {
    background: #f1f5f9;
    color: #475569;
}

.badgeGreen {
    background: #dcfce7;
    color: #15803d;
}

.badgeOrange {
    background: #ffedd5;
    color: #c2410c;
}

.badgePurple {
    background: #f3e8ff;
    color: #7e22ce;
}

/* Ghost "View Job" button */
.viewBtn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0.5rem 1.25rem;
    border: 1.5px solid #e2e8f0;
    border-radius: 0.625rem;
    color: #334155;
    font-size: 0.85rem;
    font-weight: 600;
    text-decoration: none;
    transition: all 0.2s ease;
    white-space: nowrap;
    background: white;
}

.viewBtn:hover {
    border-color: #3b82f6;
    color: #ffffff;
    background: #3b82f6;
    box-shadow: 0 4px 12px rgba(59, 130, 246, 0.25);
}

/* Empty state */
.emptyState {
    text-align: center;
    color: #94a3b8;
    padding: 3rem 2rem;
    font-size: 0.95rem;
}

/* ─── CTA ─────────────────────────────────────────────────── */
.ctaWrapper {
    display: flex;
    justify-content: center;
    padding-top: 2.5rem;
}

.browseBtn {
    display: inline-flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.9rem 2.25rem;
    background: #3b82f6;
    color: #ffffff;
    border-radius: 9999px;
    font-size: 1rem;
    font-weight: 700;
    text-decoration: none;
    transition: all 0.2s ease;
    box-shadow: 0 6px 20px rgba(59, 130, 246, 0.35);
    letter-spacing: -0.01em;
}

.browseBtn:hover {
    background: #2563eb;
    transform: translateY(-2px);
    box-shadow: 0 12px 28px rgba(59, 130, 246, 0.4);
}

/* ─── Responsive ──────────────────────────────────────────── */
@media (max-width: 900px) {
    .layout {
        grid-template-columns: 1fr;
    }

    /* Horizontal scrollable chip strip */
    .sidebar {
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        overflow-x: auto;
        gap: 0.5rem;
        padding: 1rem 1rem 0.75rem;
        border-right: none;
        border-bottom: 1px solid #e2e8f0;
        background: #fafafa;
        /* hide scrollbar visually but keep scroll */
        scrollbar-width: none;
        -ms-overflow-style: none;
    }

    .sidebar::-webkit-scrollbar {
        display: none;
    }

    .sidebarLabel {
        display: none;
    }

    .categoryItem {
        flex-shrink: 0;
        width: auto;
        padding: 0.5rem 1rem;
        border-radius: 9999px;
        border: 1.5px solid #e2e8f0;
        background: white;
        font-size: 0.82rem;
        gap: 0.5rem;
        white-space: nowrap;
    }

    .categoryItem:hover {
        border-color: #93c5fd;
        background: #eff6ff;
        transform: none;
    }

    .categoryActive {
        border-color: #3b82f6 !important;
        background: #eff6ff !important;
    }

    .categoryIcon {
        width: 16px;
        height: 16px;
    }

    .categoryLabel {
        overflow: visible;
        text-overflow: unset;
        white-space: nowrap;
    }
}

@media (max-width: 640px) {
    .section {
        padding: 4rem 1rem;
    }

    .title {
        font-size: 1.85rem;
    }

    .subtitle {
        font-size: 0.9rem;
    }

    .appWindow {
        border-radius: 1rem;
    }

    .jobsPanel {
        padding: 1rem;
    }

    .jobCard {
        flex-direction: column;
        align-items: flex-start;
        gap: 0.875rem;
        padding: 1rem;
    }

    .jobInfo {
        gap: 0.875rem;
    }

    .jobTitle {
        font-size: 0.95rem;
    }

    .jobActions {
        width: 100%;
        justify-content: space-between;
        border-top: 1px solid #f1f5f9;
        padding-top: 0.75rem;
    }

    .jobMeta {
        gap: 0.3rem;
        flex-wrap: wrap;
    }

    .metaDot {
        display: none;
    }

    .metaItem {
        font-size: 0.75rem;
    }

    .browseBtn {
        font-size: 0.9rem;
        padding: 0.8rem 1.75rem;
    }
}

.section {
    padding: 6rem 2rem;
    background: #f8fafc;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
}

/* Search Bar */
.searchWrapper {
    margin-bottom: 4rem;
}

.searchBox {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 50px;
    padding: 0.5rem 0.5rem 0.5rem 1.5rem;
    display: flex;
    align-items: center;
    box-shadow: var(--shadow-lg);
    max-width: 800px;
    margin: 0 auto;
}

.searchIcon {
    color: var(--medium-grey);
    margin-right: 1rem;
}

.searchInput {
    flex: 1;
    border: none;
    outline: none;
    font-size: 1.125rem;
    color: var(--deep-navy);
}

.searchBtn {
    background: var(--primary-blue);
    color: #ffffff;
    border: none;
    padding: 0.85rem 2rem;
    border-radius: 50px;
    font-weight: 700;
    cursor: pointer;
    transition: var(--transition-smooth);
}

.searchBtn:hover {
    background: var(--deep-navy);
    transform: scale(1.02);
}

/* Sectors Grid */
.sectorsGrid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.5rem;
    margin-bottom: 4rem;
}

.sectorCard {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    padding: 1.5rem;
    border-radius: var(--radius-lg);
    display: flex;
    align-items: center;
    gap: 1.25rem;
    cursor: pointer;
    transition: var(--transition-smooth);
    text-align: left;
    outline: none;
}

.sectorIcon {
    width: 48px;
    height: 48px;
    background: #f1f5f9;
    color: var(--medium-grey);
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: var(--transition-smooth);
}

.sectorLabel {
    font-size: 1rem;
    font-weight: 800;
    color: var(--deep-navy);
    margin: 0;
}

.sectorCount {
    font-size: 0.85rem;
    color: var(--medium-grey);
}

.sectorCard:hover {
    border-color: var(--accent);
    transform: translateY(-4px);
    box-shadow: var(--shadow-md);
}

.sectorCard:hover .sectorIcon {
    background: var(--accent);
    color: #ffffff;
}

.sectorActive {
    border-color: var(--accent);
    background: #ffffff;
    box-shadow: var(--shadow-md);
}

.sectorActive .sectorIcon {
    background: var(--accent);
    color: #ffffff;
}

/* Filter Row */
.filterRow {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 2rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid #e2e8f0;
}

.resultCount {
    font-size: 1.125rem;
    color: var(--medium-grey);
}

.filters {
    display: flex;
    gap: 1rem;
}

.filterBtn,
.sortSelect {
    padding: 0.6rem 1.2rem;
    border-radius: 8px;
    border: 1px solid #e2e8f0;
    background: #ffffff;
    font-weight: 600;
    color: var(--deep-navy);
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    outline: none;
}

/* Jobs Grid */
.jobsGrid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
}

.jobCard {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: var(--radius-lg);
    padding: 2rem;
    display: flex;
    flex-direction: column;
    transition: var(--transition-smooth);
}

.jobCard:hover {
    transform: translateY(-8px);
    box-shadow: var(--shadow-xl);
    border-color: var(--primary-blue);
}

.jobHeader {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 1.5rem;
}

.companyLogo {
    width: 48px;
    height: 48px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #ffffff;
    font-weight: 900;
    font-size: 1.5rem;
}

.jobTime {
    font-size: 0.85rem;
    color: var(--medium-grey);
    display: flex;
    align-items: center;
    gap: 0.4rem;
}

.jobBody {
    margin-bottom: 1.5rem;
    flex: 1;
}

.jobTitle {
    font-size: 1.25rem;
    font-weight: 800;
    color: var(--deep-navy);
    margin-bottom: 0.5rem;
}

.companyName {
    font-size: 1rem;
    color: var(--medium-grey);
    margin-bottom: 1rem;
}

.specialityBadge {
    display: inline-block;
    padding: 0.4rem 0.8rem;
    background: var(--light-ice-blue);
    color: var(--primary-blue);
    border-radius: 6px;
    font-size: 0.85rem;
    font-weight: 700;
}

.jobMeta {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    margin-bottom: 1.5rem;
    padding: 1rem 0;
    border-top: 1px solid #f1f5f9;
}

.metaItem {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-size: 0.95rem;
    color: var(--medium-grey);
}

.jobFooter {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 1.5rem;
    border-top: 1px solid #f1f5f9;
}

.jobType {
    font-size: 0.9rem;
    font-weight: 600;
    color: var(--deep-navy);
}

.applyBtn {
    color: var(--primary-blue);
    font-weight: 700;
    text-decoration: none;
    transition: var(--transition-smooth);
}

.applyBtn:hover {
    color: var(--deep-navy);
    text-decoration: underline;
}

.emptyState {
    grid-column: span 3;
    text-align: center;
    padding: 4rem;
    color: var(--medium-grey);
}

@media (max-width: 1024px) {
    .jobsGrid {
        grid-template-columns: repeat(2, 1fr);
    }

    .sectorsGrid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 640px) {
    .jobsGrid {
        grid-template-columns: 1fr;
    }

    .sectorsGrid {
        grid-template-columns: 1fr;
    }

    .filterRow {
        flex-direction: column;
        align-items: flex-start;
        gap: 1rem;
    }
}

"use client";
import AccountBalanceOutlinedIcon from '@mui/icons-material/AccountBalanceOutlined';
