    padding: 0.6rem 1.2rem;
    background: #ffffff;
    color: var(--primary-blue);
    border: 1px solid rgba(0, 123, 255, 0.2);
    border-radius: 50px;
    font-weight: 700;
    font-size: 0.85rem;
    margin-bottom: 2.5rem;
    box-shadow: 0 4px 20px rgba(0, 123, 255, 0.08);
}

.title {
