}

.faqQuestion {
    font-size: 1.25rem;
    font-weight: 800;
    color: var(--deep-navy);
    margin-bottom: 1rem;
}

/* Marquee Styles */
.marqueeContainer {
    padding: 4rem 0;
    border-top: 1px solid #f1f5f9;
    border-bottom: 1px solid #f1f5f9;
    overflow: hidden;
    background: #fff;
}

.marqueeTrack {
    display: flex;
    gap: 5rem;
    animation: pricingScroll 40s linear infinite;
    white-space: nowrap;
    width: max-content;
}

.partnerName {
    font-size: 1.25rem;
    font-weight: 900;
    color: #CBD5E1;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}

@keyframes pricingScroll {
    0% {
        transform: translateX(0);
    }

    100% {
        transform: translateX(-50%);
    }
}

@media (max-width: 1024px) {
    .pricingGrid {
        grid-template-columns: 1fr;
        max-width: 500px;
        margin-left: auto;
        margin-right: auto;
    }

    .infraGrid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 768px) {
    .title {
        font-size: 3rem;
    }

    .pricingCard {
        padding: 3rem 2rem;
    }
}

/* ── Podcast Page ── */
.page {
    background: var(--light-ice-blue, #F0F7FF);
}

/* Hero */
.hero {
    background: var(--deep-navy);
    padding: 10rem 0 8rem;
    position: relative;
    overflow: hidden;
}

.hero::before {
    content: '';
    position: absolute;
    inset: 0;
    background:
        radial-gradient(ellipse 60% 60% at 20% 80%, rgba(0, 123, 255, 0.15) 0%, transparent 60%),
        radial-gradient(ellipse 60% 50% at 80% 10%, rgba(13, 71, 161, 0.2) 0%, transparent 60%);
}

.heroContent {
    position: relative;
    max-width: 760px;
}

.badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: rgba(0, 123, 255, 0.15);
    border: 1px solid rgba(0, 123, 255, 0.3);
    color: var(--sky-blue, #90CAF9);
    padding: 8px 18px;
    border-radius: 50px;
    font-size: 0.82rem;
    font-weight: 700;
    letter-spacing: 0.02em;
    margin-bottom: 2.5rem;
}

.heroTitle {
    font-size: clamp(3rem, 6vw, 5.5rem);
    font-weight: 900;
    color: #fff;
    letter-spacing: -0.04em;
    line-height: 1.05;
    margin-bottom: 1.75rem;
}

.heroHighlight {
    background: linear-gradient(135deg, var(--sky-blue, #90CAF9), var(--primary-blue, #007BFF));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.heroDesc {
    font-size: 1.2rem;
    color: rgba(255, 255, 255, 0.6);
    line-height: 1.75;
    max-width: 560px;
    margin-bottom: 3.5rem;
}

/* Platform Pills */
.platforms {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
}

.platformPill {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.15);
    color: rgba(255, 255, 255, 0.85);
    padding: 0.6rem 1.25rem;
    border-radius: 50px;
    font-size: 0.85rem;
    font-weight: 700;
    text-decoration: none;
    transition: background 0.2s, border-color 0.2s;
}

.platformPill:hover {
    background: rgba(255, 255, 255, 0.15);
    border-color: rgba(255, 255, 255, 0.3);
}

/* Section Tag */
.sectionTagLight {
    display: inline-block;
    color: var(--primary-blue, #007BFF);
    font-size: 0.8rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 1.5rem;
}

/* Featured Episode */
.featuredSection {
    padding: 7rem 0 0;
    background: white;
}

.featuredCard {
    display: grid;
    grid-template-columns: 5fr 7fr;
    border-radius: var(--radius-lg);
    overflow: hidden;
    border: 1px solid var(--sky-blue, #90CAF9);
}

.featuredVisual {
    min-height: 380px;
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 3rem;
    gap: 2rem;
    background: #0f172a;
    overflow: hidden;
}

.podcastImg {
    object-fit: cover;
    opacity: 0.5;
    transition: transform 0.6s ease;
}

.featuredCard:hover .podcastImg {
    transform: scale(1.05);
}

.featuredEmoji {
    font-size: 4rem;
}

.featuredWave {
    display: flex;
    align-items: center;
    gap: 4px;
}

.waveBar {
    width: 5px;
    background: linear-gradient(to top, rgba(0, 123, 255, 0.7), rgba(255, 255, 255, 0.6));
    border-radius: 3px;
    animation: wavePulse 1.4s ease-in-out infinite alternate;
    box-shadow: 0 0 6px rgba(0, 123, 255, 0.3);
}

@keyframes wavePulse {
    from {
        transform: scaleY(0.4);
    }

    to {
        transform: scaleY(1);
    }
}

.featuredBody {
    padding: 3.5rem;
    display: flex;
    flex-direction: column;
    justify-content: center;
    background: var(--light-ice-blue, #F0F7FF);
    gap: 0;
}

.epNum {
    display: inline-block;
    background: rgba(0, 123, 255, 0.1);
    color: var(--primary-blue, #007BFF);
    font-size: 0.75rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    padding: 4px 12px;
    border-radius: 50px;
    margin-bottom: 1rem;
    width: fit-content;
}

.epMeta {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.82rem;
    color: var(--medium-grey);
    margin-bottom: 1.25rem;
}

.dot {
    opacity: 0.4;
}

.featuredTitle {
    font-size: 1.75rem;
    font-weight: 900;
    color: var(--deep-navy);
    letter-spacing: -0.03em;
    line-height: 1.25;
    margin-bottom: 1rem;
}

.featuredDesc {
    font-size: 0.97rem;
    color: var(--medium-grey);
    line-height: 1.7;
    margin-bottom: 2.5rem;
}

.featuredActions {
    display: flex;
    align-items: center;
    gap: 2rem;
    flex-wrap: wrap;
}

.playBtnLarge {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background: var(--deep-navy);
    color: #fff;
    border: none;
    padding: 0.9rem 2rem;
    border-radius: 14px;
    font-weight: 800;
    font-size: 0.95rem;
    cursor: pointer;
    transition: transform 0.2s, box-shadow 0.2s;
}

.playBtnLarge:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.18);
}

.showNotesLink {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: var(--primary-blue);
    font-weight: 800;
    font-size: 0.9rem;
    text-decoration: none;
    transition: gap 0.2s;
}

.showNotesLink:hover {
    gap: 10px;
}

/* Episodes Section */
.episodesSection {
    padding: 6rem 0;
    background: white;
}

.episodesHeader {
    margin-bottom: 3rem;
}

.episodesTitle {
    font-size: clamp(2rem, 3vw, 2.75rem);
    font-weight: 900;
    color: var(--deep-navy);
    letter-spacing: -0.03em;
    margin-bottom: 2rem;
}

/* Category chips */
.categoryRow {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
}

.chip {
    padding: 0.5rem 1.25rem;
    border-radius: 50px;
    border: 1px solid var(--sky-blue, #90CAF9);
    background: var(--alice-blue, #E3F2FD);
    color: var(--cobalt-blue, #0D47A1);
    font-weight: 700;
    font-size: 0.85rem;
    cursor: pointer;
    transition: all 0.2s;
}

.chip:hover {
    border-color: var(--primary-blue, #007BFF);
    color: var(--primary-blue, #007BFF);
}

.chipActive {
    background: var(--primary-blue, #007BFF);
    color: #fff;
    border-color: var(--primary-blue, #007BFF);
}

/* Episodes Grid */
.episodesGrid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
}

.episodeCard {
    border: 1px solid var(--sky-blue, #90CAF9);
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    position: relative;
    background: white;
}

.episodeCard::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 4px;
    height: 100%;
    background: linear-gradient(to bottom, var(--primary-blue, #007BFF), var(--dodger-blue, #2196F3));
    opacity: 0;
    transition: opacity 0.3s ease;
    z-index: 1;
}

.episodeCard:hover {
    transform: translateY(-8px);
    box-shadow: 0 24px 60px rgba(0, 0, 0, 0.1);
    border-color: rgba(0, 123, 255, 0.25);
}

.episodeCard:hover::before {
    opacity: 1;
}

.epCardVisual {
    height: 160px;
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #0f172a;
    overflow: hidden;
}

.epCardEmoji {
    font-size: 3rem;
    opacity: 0.6;
}

.playBtn {
    position: absolute;
    bottom: 1rem;
    right: 1rem;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.2);
    backdrop-filter: blur(8px);
    border: 1px solid rgba(255, 255, 255, 0.35);
    color: #fff;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background 0.2s, transform 0.2s;
}

.playBtn:hover {
    background: rgba(255, 255, 255, 0.35);
    transform: scale(1.08);
}

.playing {
    background: var(--primary-blue, #007BFF);
    border-color: var(--primary-blue, #007BFF);
    animation: playPulse 2s ease-in-out infinite;
}

@keyframes playPulse {

    0%,
    100% {
        box-shadow: 0 0 0 0 rgba(0, 123, 255, 0.4);
    }

    50% {
        box-shadow: 0 0 0 8px rgba(0, 123, 255, 0);
    }
}

.epCardBody {
    padding: 1.75rem;
}

.epCardMeta {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 0.75rem;
}

.epNumSmall {
    font-size: 0.72rem;
    font-weight: 800;
    color: var(--primary-blue, #007BFF);
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

.epDuration {
    font-size: 0.78rem;
    color: var(--medium-grey);
}

.epCardTitle {
    font-size: 1.05rem;
    font-weight: 800;
    color: var(--deep-navy);
    line-height: 1.35;
    margin-bottom: 0.75rem;
}

.epCardDesc {
    font-size: 0.85rem;
    color: var(--medium-grey);
    line-height: 1.65;
    margin-bottom: 1.25rem;
}

.guestBadge {
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--cobalt-blue, #0D47A1);
    background: var(--alice-blue, #E3F2FD);
    padding: 6px 14px 6px 12px;
    border-radius: 50px;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    border: 1px solid rgba(0, 123, 255, 0.15);
}

/* CTA */
.ctaSection {
    padding: 4rem 0 8rem;
}

.ctaCard {
    background: var(--deep-navy);
    border-radius: 40px;
    padding: 8rem 4rem;
    text-align: center;
    position: relative;
    overflow: hidden;
}

.ctaCard::before {
    content: '';
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse 60% 60% at 50% 0%, rgba(0, 123, 255, 0.25) 0%, transparent 70%);
}

.ctaIcon {
    font-size: 3.5rem;
    margin-bottom: 2rem;
    position: relative;
}

.ctaTitle {
    font-size: clamp(2rem, 3.5vw, 3rem);
    font-weight: 900;
    color: #fff;
    letter-spacing: -0.04em;
    margin-bottom: 1.25rem;
    position: relative;
}

.ctaDesc {
    font-size: 1.1rem;
    color: rgba(255, 255, 255, 0.6);
    max-width: 500px;
    margin: 0 auto 3.5rem;
    line-height: 1.7;
    position: relative;
}

.ctaPlatforms {
    display: flex;
    gap: 1rem;
    justify-content: center;
    flex-wrap: wrap;
    position: relative;
}

.ctaPlatformBtn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: #fff;
    padding: 0.85rem 1.75rem;
    border-radius: 14px;
    font-weight: 800;
    font-size: 0.9rem;
    text-decoration: none;
    transition: transform 0.2s, opacity 0.2s;
}

.ctaPlatformBtn:hover {
    transform: translateY(-3px);
    opacity: 0.9;
}

/* Responsive */
@media (max-width: 1024px) {
    .episodesGrid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 768px) {
    .hero {
        padding: 7rem 0 5rem;
    }

    .featuredCard {
        grid-template-columns: 1fr;
    }

    .featuredVisual {
        min-height: 240px;
    }

    .episodesGrid {
        grid-template-columns: 1fr;
    }

    .ctaCard {
        padding: 5rem 2rem;
        border-radius: 24px;
    }

    .ctaPlatforms {
        gap: 0.75rem;
    }
}

/* ============================
   ONBOARDING — Shared Styles
   ============================ */

.page {
    width: 100vw;
    height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f8fafc;
    position: relative;
    overflow: hidden;
    font-family: var(--font-inter), -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.bgGlow1 {
    position: absolute;
    top: -12%;
    right: -8%;
    width: 480px;
    height: 480px;
    background: radial-gradient(circle, rgba(0, 123, 255, 0.07) 0%, transparent 65%);
    border-radius: 50%;
    pointer-events: none;
    animation: glowPulse 20s ease-in-out infinite alternate;
}

.bgGlow2 {
    position: absolute;
    bottom: -12%;
    left: -8%;
    width: 420px;
    height: 420px;
    background: radial-gradient(circle, rgba(0, 123, 255, 0.05) 0%, transparent 65%);
    border-radius: 50%;
    pointer-events: none;
    animation: glowPulse 16s ease-in-out infinite alternate-reverse;
}

@keyframes glowPulse {
    0% {
        transform: scale(1);
        opacity: 0.7;
    }

    100% {
        transform: scale(1.15);
        opacity: 1;
    }
}

.gridOverlay {
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(rgba(0, 0, 0, 0.02) 1px, transparent 1px),
        linear-gradient(90deg, rgba(0, 0, 0, 0.02) 1px, transparent 1px);
    background-size: 40px 40px;
    pointer-events: none;
}

/* Card */
.card {
    position: relative;
    z-index: 1;
    width: 100%;
    max-width: 520px;
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 20px;
    padding: 2rem 2.25rem;
    box-shadow:
        0 4px 6px -1px rgba(0, 0, 0, 0.03),
        0 10px 30px -5px rgba(0, 0, 0, 0.06);
    display: flex;
    flex-direction: column;
    gap: 1.25rem;
    animation: cardEnter 0.5s ease-out;
}

@keyframes cardEnter {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.98);
    }

    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

/* Stepper */
.stepper {
    display: flex;
    align-items: center;
    gap: 0;
}

.stepDot {
    width: 28px;
    height: 28px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.7rem;
    font-weight: 700;
    border: 2px solid #e2e8f0;
    background: #f1f5f9;
    color: #94a3b8;
    transition: all 0.3s ease;
    flex-shrink: 0;
}

.stepDotActive {
    border-color: var(--primary-blue);
    background: var(--primary-blue);
    color: white;
    box-shadow: 0 2px 8px rgba(0, 123, 255, 0.3);
}

.stepDotDone {
    border-color: #10b981;
    background: #10b981;
    color: white;
}

.stepLine {
    flex: 1;
    height: 2px;
    background: #e2e8f0;
    margin: 0 0.35rem;
    transition: background 0.3s ease;
}

.stepLineActive {
    background: var(--primary-blue);
}

.stepLineDone {
    background: #10b981;
}

/* Header */
.header {
    text-align: center;
}

.title {
    font-size: 1.4rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.02em;
    margin-bottom: 0.25rem;
}

.subtitle {
    font-size: 0.82rem;
    color: #94a3b8;
}

/* Category / Chip Grid */
.chipGrid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 0.5rem;
}

.chip {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.6rem 0.5rem;
    background: #ffffff;
    border: 1.5px solid #e5e7eb;
    border-radius: 10px;
    font-size: 0.78rem;
    font-weight: 600;
    color: #374151;
    cursor: pointer;
    transition: all 0.2s ease;
    font-family: inherit;
    text-align: center;
}

.chip:hover {
    border-color: #66b3ff;
    background: #f0f7ff;
}

.chipSelected {
    border-color: var(--primary-blue);
    background: #e6f2ff;
    color: var(--primary-blue);
    box-shadow: 0 0 0 2px rgba(0, 123, 255, 0.1);
}

.chipIcon {
    font-size: 1rem;
}

/* Skill Tags */
.tagWrap {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
}

.tag {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.4rem 0.75rem;
    background: #ffffff;
    border: 1.5px solid #e5e7eb;
    border-radius: 20px;
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
    cursor: pointer;
    transition: all 0.2s ease;
    font-family: inherit;
}

.tag:hover {
    border-color: #66b3ff;
    color: #374151;
}

.tagSelected {
    border-color: var(--primary-blue);
    background: var(--primary-blue);
    color: white;
}

/* Upload Area */
.uploadArea {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 0.6rem;
    padding: 2rem;
    border: 2px dashed #d1d5db;
    border-radius: 14px;
    background: #fafafa;
    cursor: pointer;
    transition: all 0.25s ease;
    text-align: center;
}

.uploadArea:hover {
    border-color: var(--primary-blue);
    background: #f0f7ff;
}

.uploadAreaActive {
    border-color: #10b981;
    background: #f0fdf4;
}

.uploadIcon {
    color: #94a3b8;
    transition: color 0.2s;
}

.uploadArea:hover .uploadIcon {
    color: var(--primary-blue);
}

.uploadAreaActive .uploadIcon {
    color: #10b981;
}

.uploadText {
    font-size: 0.82rem;
    color: #64748b;
    font-weight: 500;
}

.uploadHint {
    font-size: 0.7rem;
    color: #94a3b8;
}

.uploadedFile {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.55rem 0.85rem;
    background: #f0fdf4;
    border: 1px solid #bbf7d0;
    border-radius: 8px;
    font-size: 0.78rem;
    font-weight: 600;
    color: #166534;
}

/* Optional field */
.optionalField {
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
}

.optionalLabel {
    font-size: 0.75rem;
    font-weight: 600;
    color: #374151;
}

.optionalInput {
    width: 100%;
    padding: 0.6rem 0.85rem;
    background: #f9fafb;
    border: 1.5px solid #e5e7eb;
    border-radius: 9px;
    color: #0f172a;
    font-size: 0.84rem;
    font-family: inherit;
    outline: none;
    transition: all 0.2s ease;
}

.optionalInput::placeholder {
    color: #b0b8c4;
}

.optionalInput:focus {
    background: #ffffff;
    border-color: var(--primary-blue);
    box-shadow: 0 0 0 3px rgba(0, 123, 255, 0.08);
}

/* Actions */
.actions {
    display: flex;
    gap: 0.55rem;
    align-items: center;
}

.backBtn {
    display: flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.65rem 0.95rem;
    background: #ffffff;
    border: 1.5px solid #e5e7eb;
    border-radius: 9px;
    color: #64748b;
    font-size: 0.82rem;
    font-weight: 600;
    font-family: inherit;
    cursor: pointer;
    transition: all 0.2s ease;
    white-space: nowrap;
    flex-shrink: 0;
}

.backBtn:hover {
    background: #f9fafb;
    border-color: #d1d5db;
    color: #374151;
}

.nextBtn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.45rem;
    flex: 1;
    padding: 0.7rem 1rem;
    background: var(--primary-blue);
    color: white;
    border: none;
    border-radius: 9px;
    font-size: 0.88rem;
    font-weight: 700;
    font-family: inherit;
    cursor: pointer;
    transition: all 0.25s ease;
    box-shadow: 0 2px 8px rgba(0, 123, 255, 0.3);
}

.nextBtn:hover:not(:disabled) {
    background: #0056d6;
    transform: translateY(-1px);
    box-shadow: 0 4px 16px rgba(0, 123, 255, 0.4);
}

.nextBtn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
    box-shadow: none;
}

/* Skip link */
.skipLink {
    text-align: center;
    font-size: 0.72rem;
    color: #94a3b8;
}

.skipBtn {
    background: none;
    border: none;
    color: #94a3b8;
    font-size: 0.72rem;
    font-weight: 600;
    cursor: pointer;
    text-decoration: underline;
    text-underline-offset: 2px;
    font-family: inherit;
    transition: color 0.2s;
}

.skipBtn:hover {
    color: var(--primary-blue);
}

/* Selection counter */
.counter {
    font-size: 0.72rem;
    color: #94a3b8;
    text-align: right;
    font-weight: 500;
}

/* Responsive */
@media (max-width: 560px) {
    .card {
        max-width: 100%;
        margin: 0 0.75rem;
        padding: 1.5rem 1.25rem;
        border-radius: 16px;
    }

    .chipGrid {
        grid-template-columns: repeat(2, 1fr);
    }

    .title {
        font-size: 1.25rem;
    }
}

@media (max-height: 750px) {
    .card {
        gap: 1rem;
        padding: 1.5rem 1.75rem;
    }

    .chipGrid {
        gap: 0.4rem;
    }

    .chip {
        padding: 0.5rem 0.4rem;
        font-size: 0.74rem;
    }

    .uploadArea {
        padding: 1.25rem;
    }
}

"use client";
import React from 'react';
import styles from './onboarding.module.css';

export default function OnboardingLayout({ children }: { children: React.ReactNode }) {
    return (
        <div className={styles.page}>
            <div className={styles.bgGlow1} />
            <div className={styles.bgGlow2} />
            <div className={styles.gridOverlay} />
            {children}
        </div>
    );
}

/* ── Job Seekers Page ── */
.page {
    background: #fff;
}

/* Hero */
.hero {
    background: var(--deep-navy);
    padding: 10rem 0 8rem;
    position: relative;
    overflow: hidden;
}

.hero::before {
    content: '';
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse 80% 60% at 60% 0%, rgba(0, 123, 255, 0.18) 0%, transparent 70%);
}

.heroContent {
    position: relative;
    max-width: 760px;
}

.badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: rgba(0, 123, 255, 0.15);
    border: 1px solid rgba(0, 123, 255, 0.3);
    color: #60a5fa;
    padding: 8px 18px;
    border-radius: 50px;
    font-size: 0.82rem;
    font-weight: 700;
    letter-spacing: 0.02em;
    margin-bottom: 2.5rem;
}

.heroTitle {
    font-size: clamp(3rem, 6vw, 5.5rem);
    font-weight: 900;
    color: #fff;
    letter-spacing: -0.04em;
    line-height: 1.05;
    margin-bottom: 2rem;
}

.heroHighlight {
    background: linear-gradient(135deg, #007BFF, #60a5fa);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.heroDesc {
    font-size: 1.2rem;
    color: rgba(255, 255, 255, 0.65);
    line-height: 1.75;
    max-width: 580px;
    margin-bottom: 3.5rem;
}

.heroCtas {
    display: flex;
    gap: 1.25rem;
    flex-wrap: wrap;
}

.primaryCta {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: #007BFF;
    color: #fff;
    padding: 1rem 2.5rem;
    border-radius: 14px;
    font-weight: 800;
    font-size: 1rem;
    text-decoration: none;
    transition: transform 0.2s, box-shadow 0.2s;
}

.primaryCta:hover {
    transform: translateY(-2px);
    box-shadow: 0 12px 30px rgba(0, 123, 255, 0.4);
}

.secondaryCta {
    display: inline-flex;
    align-items: center;
    background: rgba(255, 255, 255, 0.08);
    color: #fff;
    border: 1px solid rgba(255, 255, 255, 0.2);
    padding: 1rem 2.5rem;
    border-radius: 14px;
    font-weight: 700;
    font-size: 1rem;
    text-decoration: none;
    transition: background 0.2s;
}

.secondaryCta:hover {
    background: rgba(255, 255, 255, 0.14);
}

/* Stats Strip */
.statsStrip {
    background: #f8fafc;
    border-bottom: 1px solid #e2e8f0;
}

.statsGrid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    padding: 4rem 0;
    gap: 2rem;
}

.statItem {
    text-align: center;
}

.statVal {
    display: block;
    font-size: 2.75rem;
    font-weight: 900;
    color: var(--primary-blue);
    letter-spacing: -0.04em;
}

.statLabel {
    display: block;
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--medium-grey);
    margin-top: 0.5rem;
}

/* Section shared */
.sectionHeader {
    margin-bottom: 5rem;
}

.sectionTag {
    display: inline-block;
    color: var(--primary-blue);
    font-size: 0.8rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 1rem;
}

.sectionTitle {
    font-size: clamp(2rem, 3.5vw, 3rem);
    font-weight: 900;
    color: var(--deep-navy);
    letter-spacing: -0.03em;
    line-height: 1.15;
    margin-bottom: 1rem;
}

.sectionDesc {
    font-size: 1.125rem;
    color: var(--medium-grey);
    line-height: 1.7;
    max-width: 560px;
}

/* How It Works */
.howSection {
    padding: 8rem 0;
}

.stepsGrid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 3rem;
}

.stepCard {
    background: #f8fafc;
    border-radius: var(--radius-lg);
    padding: 3rem 2.5rem;
    border: 1px solid #e2e8f0;
    position: relative;
    overflow: hidden;
    transition: transform 0.25s, box-shadow 0.25s;
}

.stepCard:hover {
    transform: translateY(-6px);
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.08);
}

.stepNum {
    font-size: 3.5rem;
    font-weight: 900;
    letter-spacing: -0.05em;
    line-height: 1;
    margin-bottom: 1.5rem;
}

.stepTitle {
    font-size: 1.25rem;
    font-weight: 800;
    color: var(--deep-navy);
    margin-bottom: 1rem;
}

.stepDesc {
    font-size: 0.95rem;
    color: var(--medium-grey);
    line-height: 1.7;
}

.stepLine {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 4px;
}

/* Benefits */
.benefitsSection {
    padding: 8rem 0;
    background: var(--light-ice-blue);
}

.benefitsGrid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
}

.benefitCard {
    background: #fff;
    border-radius: var(--radius-lg);
    padding: 2.5rem;
    border: 1px solid rgba(0, 123, 255, 0.1);
    transition: transform 0.25s, box-shadow 0.25s;
}

.benefitCard:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 40px rgba(0, 123, 255, 0.1);
}

.benefitIcon {
    font-size: 2.5rem;
    margin-bottom: 1.25rem;
}

.benefitTitle {
    font-size: 1.1rem;
    font-weight: 800;
    color: var(--deep-navy);
    margin-bottom: 0.75rem;
}

.benefitDesc {
    font-size: 0.9rem;
    color: var(--medium-grey);
    line-height: 1.7;
}

/* Testimonials */
.testimonialsSection {
    padding: 8rem 0;
    background: var(--deep-navy);
}

.testimonialsSection .sectionTag {
    color: rgba(0, 123, 255, 0.8);
}

.testimonialsGrid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
    margin-top: 1rem;
}

.testimonialCard {
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: var(--radius-lg);
    padding: 2.5rem;
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.outcomeBadge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: #fff;
    font-size: 0.8rem;
    font-weight: 800;
    padding: 6px 14px;
    border-radius: 50px;
    width: fit-content;
}

.testimonialQuote {
    font-size: 1rem;
    color: rgba(255, 255, 255, 0.85);
    line-height: 1.7;
    font-style: italic;
    flex: 1;
}

.testimonialMeta {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.avatar {
    width: 42px;
    height: 42px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 800;
    font-size: 0.9rem;
    color: #fff;
    flex-shrink: 0;
}

.testimonialName {
    font-weight: 800;
    color: #fff;
    font-size: 0.95rem;
}

.testimonialRole {
    font-size: 0.8rem;
    color: rgba(255, 255, 255, 0.5);
}

/* CTA */
.ctaSection {
    padding: 8rem 0;
}

.ctaCard {
    background: var(--gradient-premium);
    border-radius: 40px;
    padding: 8rem 4rem;
    text-align: center;
    color: #fff;
}

.ctaTitle {
    font-size: clamp(2.5rem, 4vw, 3.5rem);
    font-weight: 900;
    margin-bottom: 1.5rem;
    letter-spacing: -0.04em;
}

.ctaDesc {
    font-size: 1.2rem;
    opacity: 0.8;
    margin-bottom: 3.5rem;
    max-width: 500px;
    margin-left: auto;
    margin-right: auto;
}

.ctaBtns {
    display: flex;
    gap: 1.25rem;
    justify-content: center;
    flex-wrap: wrap;
}

.ctaPrimary {
    background: #fff;
    color: var(--primary-blue);
    padding: 1.1rem 3rem;
    border-radius: 14px;
    font-weight: 900;
    font-size: 1rem;
    text-decoration: none;
    transition: transform 0.2s;
}

.ctaPrimary:hover {
    transform: translateY(-2px);
}

.ctaSecondary {
    background: rgba(255, 255, 255, 0.1);
    color: #fff;
    border: 1px solid rgba(255, 255, 255, 0.25);
    padding: 1.1rem 3rem;
    border-radius: 14px;
    font-weight: 700;
    font-size: 1rem;
    text-decoration: none;
    backdrop-filter: blur(10px);
    transition: background 0.2s;
}

.ctaSecondary:hover {
    background: rgba(255, 255, 255, 0.18);
}

/* Responsive */
@media (max-width: 1024px) {
    .benefitsGrid {
        grid-template-columns: repeat(2, 1fr);
    }

    .testimonialsGrid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 768px) {
    .hero {
        padding: 7rem 0 5rem;
    }

    .statsGrid {
        grid-template-columns: repeat(2, 1fr);
    }

    .stepsGrid {
        grid-template-columns: 1fr;
        gap: 2rem;
    }

    .benefitsGrid {
        grid-template-columns: 1fr;
    }

    .testimonialsGrid {
        grid-template-columns: 1fr;
    }

    .ctaCard {
        padding: 5rem 2rem;
        border-radius: 24px;
    }
}

.hero {
    position: relative;
    padding: 12rem 0 10rem;
    background: var(--deep-navy);
    color: white;
    overflow: hidden;
}

.hero::after {
    content: '';
    position: absolute;
    inset: 0;
    background-image:
        radial-gradient(circle at 20% 30%, rgba(0, 123, 255, 0.15) 0%, transparent 50%),
        radial-gradient(circle at 80% 70%, rgba(0, 123, 255, 0.1) 0%, transparent 50%);
    pointer-events: none;
}

.heroContent {
    max-width: 1000px;
    margin: 0 auto;
    text-align: center;
    position: relative;
    z-index: 5;
}

.enterpriseBadge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    padding: 10px 20px;
    border-radius: 100px;
    font-size: 0.8rem;
    font-weight: 800;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--primary-blue);
    margin-bottom: 3rem;
}

.heroTitle {
    font-size: clamp(3.5rem, 8vw, 5.5rem);
    font-weight: 900;
    line-height: 1;
    margin-bottom: 2.5rem;
    letter-spacing: -0.04em;
}

.titleGlow {
    color: var(--primary-blue);
    text-shadow: 0 0 30px rgba(0, 123, 255, 0.3);
}

.heroDesc {
    font-size: 1.35rem;
    color: rgba(255, 255, 255, 0.6);
    max-width: 800px;
    margin: 0 auto 5rem;
    line-height: 1.6;
}

.dashboardMockup {
    position: relative;
    background: rgba(255, 255, 255, 0.03);
    backdrop-filter: blur(40px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 32px;
    padding: 4rem;
    box-shadow: 0 50px 100px -20px rgba(0, 0, 0, 0.5);
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 2.5rem;
}

.statItem {
    text-align: left;
}

.statValue {
    font-size: 3rem;
    font-weight: 900;
    margin-bottom: 0.5rem;
    color: var(--primary-blue);
}

.statLabel {
    font-size: 0.85rem;
    font-weight: 800;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.4);
}

/* Command Center Section */
.commandSection {
    background: #ffffff;
    padding: 10rem 0;
}

.commandGrid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8rem;
    align-items: center;
}

.commandContent {
    position: relative;
}

.featureTag {
    color: var(--primary-blue);
    font-weight: 900;
    font-size: 0.9rem;
    text-transform: uppercase;
    margin-bottom: 1.5rem;
    display: block;
}

.commandTitle {
    font-size: 3.5rem;
    font-weight: 900;
    color: var(--deep-navy);
    margin-bottom: 2rem;
    line-height: 1.1;
}

.commandText {
    font-size: 1.15rem;
    color: var(--medium-grey);
    line-height: 1.8;
    margin-bottom: 3rem;
}

.featureList {
    display: grid;
    gap: 1.5rem;
}

.featureItem {
    display: flex;
    gap: 1.5rem;
    align-items: flex-start;
}

.featureIcon {
    width: 48px;
    height: 48px;
    background: var(--soft-blue);
    border-radius: 14px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--primary-blue);
    flex-shrink: 0;
}

.featureBox h4 {
    font-size: 1.2rem;
    font-weight: 800;
    color: var(--deep-navy);
    margin-bottom: 0.5rem;
}

.featureBox p {
    font-size: 0.95rem;
    color: var(--medium-grey);
}

/* Visual Panel */
.visualPanel {
    position: relative;
    height: 600px;
    background: var(--deep-navy);
    border-radius: 40px;
    overflow: hidden;
    box-shadow: var(--shadow-2xl);
}

.scanLine {
    position: absolute;
    width: 100%;
    height: 2px;
    background: var(--primary-blue);
    box-shadow: 0 0 20px var(--primary-blue);
    top: 50%;
    animation: scan 4s infinite linear;
    z-index: 10;
}

@keyframes scan {
    0% {
        top: 0;
    }

    100% {
        top: 100%;
    }
}

/* Solutions Section */
.solutionsSection {
    background: #fafafa;
    padding: 10rem 0;
}

.sectionHeader {
    text-align: center;
    max-width: 800px;
    margin: 0 auto 6rem;
}

.solutionGrid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2.5rem;
}

.solutionCard {
    background: white;
    padding: 3.5rem;
    border-radius: 32px;
    border: 1px solid #f1f5f9;
    transition: var(--transition-smooth);
}

.solutionCard:hover {
    transform: translateY(-10px);
    box-shadow: var(--shadow-xl);
    border-color: var(--primary-blue);
}

.solutionTitle {
    font-size: 1.75rem;
    font-weight: 900;
    color: var(--deep-navy);
    margin-bottom: 1.5rem;
}

.solutionDesc {
    color: var(--medium-grey);
    line-height: 1.7;
    margin-bottom: 3rem;
}

.actionLink {
    display: flex;
    align-items: center;
    gap: 10px;
    color: var(--primary-blue);
    font-weight: 800;
    text-decoration: none;
    font-size: 0.95rem;
}

/* CTA */
.ctaSection {
    padding: 10rem 0;
}

.ctaBox {
    background: linear-gradient(135deg, var(--deep-navy) 0%, #001f3f 100%);
    border-radius: 48px;
    padding: 10rem 4rem;
    text-align: center;
    color: white;
    position: relative;
    overflow: hidden;
}

.ctaBox::before {
    content: '';
    position: absolute;
    inset: 0;
    background-image: radial-gradient(circle at center, rgba(0, 123, 255, 0.2) 0%, transparent 70%);
}

.ctaTitle {
    font-size: 4rem;
    font-weight: 900;
    margin-bottom: 2rem;
    position: relative;
    z-index: 2;
}

.ctaBtn {
    background: var(--primary-blue);
    color: white;
    padding: 1.5rem 4rem;
    border-radius: 18px;
    font-weight: 900;
    text-decoration: none;
    display: inline-block;
    transition: var(--transition-smooth);
    box-shadow: 0 20px 40px rgba(0, 123, 255, 0.3);
}

@media (max-width: 1100px) {
    .commandGrid {
        grid-template-columns: 1fr;
        gap: 5rem;
    }

    .solutionGrid {
        grid-template-columns: repeat(2, 1fr);
    }

    .dashboardMockup {
        grid-template-columns: 1fr;
        gap: 2rem;
    }
}

@media (max-width: 768px) {
    .heroTitle {
        font-size: 3rem;
    }

    .solutionGrid {
        grid-template-columns: 1fr;
    }

    .ctaTitle {
        font-size: 2.5rem;
    }

    .commandTitle {
        font-size: 2.5rem;
    }
}

"use client";
import { useEffect } from 'react';
import { useRouter } from 'next/navigation';

export default function DashboardRedirect() {
    const router = useRouter();
    useEffect(() => {
        // Default redirect to candidate dashboard
        router.replace('/dashboard/candidate');
    }, [router]);
    return null;
}

