                        ))}
                    </div>
                </div>

                {/* Stats bar */}
                <div className={styles.statsBar}>
                    <div className="premium-container">
                        <div className={styles.statsInner}>
                            {STATS.map((s, i) => (
                                <React.Fragment key={s.val}>
                                    {i > 0 && <div className={styles.statDiv} />}
                                    <div className={styles.statItem}>
                                        <div className={styles.statVal}>{s.val}</div>
                                        <div className={styles.statLabel}>{s.label}</div>
                                    </div>
                                </React.Fragment>
                            ))}
                        </div>
                    </div>
                </div>
            </section>

            {/* ── CASE STUDY CARDS ── */}
            <section className={styles.cardsSection}>
                <div className="premium-container">
                    {shown.length > 0 ? (
                        <div className={styles.cardsGrid}>
                            {shown.map(c => (
                                <div key={c.id} className={`${styles.card} glass-card`}>
                                    {/* Card head */}
                                    <div className={styles.cardHead}>
                                        <div className={styles.cardLogo} style={{ background: c.color }}>{c.logo}</div>
                                        <div>
                                            <div className={styles.cardCompany}>{c.company}</div>
                                            <div className={styles.cardSize}>{c.industry} · {c.size}</div>
                                        </div>
                                    </div>

                                    {/* Challenge */}
                                    <div className={styles.section}>
                                        <div className={styles.sectionLbl}>Challenge</div>
                                        <p className={styles.sectionTxt}>{c.challenge}</p>
                                    </div>

                                    {/* Approach */}
                                    <div className={styles.section}>
                                        <div className={styles.sectionLbl}>Approach</div>
                                        <p className={styles.sectionTxt}>{c.approach}</p>
                                    </div>

                                    {/* Result metric */}
                                    <div className={styles.metricBox}>
                                        <div className={styles.metricVal}>{c.metric}</div>
                                        <div className={styles.metricLabel}>{c.metricLabel}</div>
                                    </div>

                                    {/* Quote */}
                                    <div className={styles.quoteBlock}>
                                        <p className={styles.quoteText}>“{c.quote}”</p>
                                        <div className={styles.quotePerson}>— {c.person}, <em>{c.personRole}</em></div>
                                    </div>

                                    <Link href="#" className={styles.readMore}>Read Full Story <ArrowIco /></Link>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className={styles.emptyState}>No case studies found for this category yet.</div>
                    )}
                </div>
            </section>

            {/* ── CTA STRIP ── */}
            <section className={styles.ctaStrip}>
                <div className="premium-container">
                    <h2 className={styles.ctaTitle}>Ready to Write Your Own Success Story?</h2>
                    <div className={styles.ctaBtns}>
                        <Link href="/employers/post-job" className={styles.ctaPrimary}>Post a Job Free</Link>
                        <Link href="/employers/sourcing" className={styles.ctaSecondary}>Talk to Our Team</Link>
                    </div>
                </div>
            </section>
        </main>
    );
}

.page {
    padding-top: 68px;
    min-height: 100vh;
    background: var(--light-ice-blue, #F0F7FF);
}

/* ─── Hero ── */
.hero {
    background: linear-gradient(180deg, var(--cobalt-blue, #0D47A1) 0%, var(--ocean-deep, #1565C0) 100%);
    overflow: hidden;
}


.heroTitle {
    font-size: clamp(2rem, 5vw, 3rem);
    font-weight: 800;
    color: white;
    text-align: center;
    margin: 64px 0 12px;
    letter-spacing: -0.02em;
}

.heroSub {
    font-size: 1.05rem;
    color: #BBDEFB;
    text-align: center;
    margin: 0 auto 36px;
    max-width: 520px;
}

/* Filter tabs */
.filterRow {
    display: flex;
    gap: 8px;
    justify-content: center;
    flex-wrap: wrap;
    margin-bottom: 48px;
}

.filterTab {
    padding: 8px 20px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.2);
    color: white;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    font-family: inherit;
    transition: all 0.2s ease;
}

.filterTab:hover {
    background: rgba(255, 255, 255, 0.2);
}

.filterTabActive {
    background: white !important;
    color: var(--cobalt-blue) !important;
    border-color: white !important;
}

/* Stats bar */
.statsBar {
    background: var(--ocean-deep, #1565C0);
    border-top: 1px solid rgba(144, 202, 249, 0.2);
}

.statsInner {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 28px 0;
    gap: 0;
}

.statDiv {
    width: 1px;
    height: 40px;
    background: rgba(144, 202, 249, 0.3);
    margin: 0 40px;
}

.statItem {
    text-align: center;
}

.statVal {
    font-size: 1.7rem;
    font-weight: 800;
    color: white;
    line-height: 1;
}

.statLabel {
    font-size: 0.75rem;
    color: var(--sky-blue, #90CAF9);
    margin-top: 2px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

/* ─── Cards Section ── */
.cardsSection {
    padding: 52px 0 72px;
}

.cardsGrid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(360px, 1fr));
    gap: 24px;
}

.card {
    background: white;
    border-radius: 18px;
    padding: 28px;
    border: 1px solid var(--sky-blue, #90CAF9);
    display: flex;
    flex-direction: column;
    gap: 18px;
    transition: transform 0.22s ease, box-shadow 0.22s ease;
}

.card:hover {
    transform: translateY(-5px);
    box-shadow: 0 18px 48px rgba(0, 0, 0, 0.10);
}

.cardHead {
    display: flex;
    align-items: center;
    gap: 14px;
}

.cardLogo {
    width: 50px;
    height: 50px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-weight: 700;
    font-size: 0.88rem;
    flex-shrink: 0;
}

.cardCompany {
    font-size: 1.05rem;
    font-weight: 700;
    color: var(--cobalt-blue);
}

.cardSize {
    font-size: 0.8rem;
    color: var(--medium-grey);
    margin-top: 2px;
}

.section {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.sectionLbl {
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: var(--medium-grey, #475569);
}

.sectionTxt {
    font-size: 0.88rem;
    color: var(--medium-grey);
    line-height: 1.6;
    margin: 0;
}

/* Metric */
.metricBox {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    background: var(--alice-blue, #E3F2FD);
    border-radius: 10px;
    padding: 14px 18px;
    border-left: 4px solid var(--primary-blue, #007BFF);
}

.metricVal {
    font-size: 2rem;
    font-weight: 800;
    color: var(--cobalt-blue);
    line-height: 1;
}

.metricLabel {
    font-size: 0.8rem;
    color: var(--medium-grey);
    font-weight: 500;
    margin-top: 2px;
}

/* Quote */
.quoteBlock {
    background: var(--light-ice-blue);
    border-radius: 10px;
    padding: 14px 16px;
}

.quoteText {
    font-size: 0.88rem;
    font-style: italic;
    color: var(--medium-grey);
    margin: 0 0 6px;
    line-height: 1.6;
}

.quotePerson {
    font-size: 0.8rem;
    color: var(--ocean-deep);
    font-weight: 600;
}

.quotePerson em {
    font-style: normal;
    color: var(--medium-grey);
    font-weight: 400;
}

.readMore {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 0.85rem;
    font-weight: 700;
    color: var(--primary-blue);
    text-decoration: none;
    transition: color 0.15s;
    margin-top: auto;
}

.readMore:hover {
    color: var(--cobalt-blue);
}

.emptyState {
    text-align: center;
    padding: 60px 24px;
    font-size: 1.05rem;
    color: var(--medium-grey);
}

/* ─── CTA Strip ── */
.ctaStrip {
    background: linear-gradient(135deg, var(--primary-blue, #007BFF) 0%, var(--dodger-blue, #2196F3) 100%);
    padding: 56px 0;
    text-align: center;
}

.ctaTitle {
    font-size: clamp(1.5rem, 3vw, 2rem);
    font-weight: 700;
    color: white;
    margin: 0 0 32px;
}

.ctaBtns {
    display: flex;
    gap: 16px;
    justify-content: center;
    flex-wrap: wrap;
}

.ctaPrimary {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: white;
    color: var(--primary-blue);
    padding: 14px 28px;
    border-radius: 12px;
    font-size: 0.95rem;
    font-weight: 700;
    text-decoration: none;
    transition: all 0.2s ease;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.2);
}

.ctaPrimary:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.25);
}

.ctaSecondary {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: rgba(255, 255, 255, 0.15);
    border: 1px solid rgba(255, 255, 255, 0.4);
    color: white;
    padding: 14px 28px;
    border-radius: 12px;
    font-size: 0.95rem;
    font-weight: 700;
    text-decoration: none;
    transition: all 0.2s ease;
}

.ctaSecondary:hover {
    background: rgba(255, 255, 255, 0.25);
}

/* ─── Responsive ── */
@media (max-width: 768px) {
    .cardsGrid {
        grid-template-columns: 1fr;
    }

    .statsInner {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 20px;
        padding: 28px 16px;
    }

    .statDiv {
        display: none;
    }
}

@media (max-width: 480px) {
    .statsInner {
        grid-template-columns: 1fr 1fr;
    }
}

"use client";
import { PageHeader } from '@/components/ui';
import Image from 'next/image';
import { JobListings, CTA, Stats } from '@/components/sections';
import FavoriteOutlinedIcon from '@mui/icons-material/FavoriteOutlined';
import PublicOutlinedIcon from '@mui/icons-material/PublicOutlined';
import VerifiedUserOutlinedIcon from '@mui/icons-material/VerifiedUserOutlined';
import BoltOutlinedIcon from '@mui/icons-material/BoltOutlined';
import LocalCafeOutlinedIcon from '@mui/icons-material/LocalCafeOutlined';
import LaptopOutlinedIcon from '@mui/icons-material/LaptopOutlined';
import AnimateOnScroll from '@/components/AnimateOnScroll';
import styles from './careers.module.css';

export default function CareersPage() {
    return (
        <main className={styles.page}>
            <PageHeader
                title="Build the future"
                highlight="with us"
                description="We're a team of engineers, designers, and dreamers building the next generation of talent infrastructure."
                breadcrumb="Life at TalentMesh"
            />

            <AnimateOnScroll animation="scaleUp">
                <Stats />
            </AnimateOnScroll>

            {/* ── Our Culture ── */}
            <AnimateOnScroll animation="fadeUp">
                <section className={styles.cultureSection}>
                    <div className={styles.cultureGrid}>
                        <div className={styles.cultureImageWrapper}>
                            <Image
                                src="/images/careers-team.jpg"
                                alt="TalentMesh Team Collaboration"
                                fill
                                className={styles.cultureImg}
                                priority
                            />
                        </div>
                        <div className={styles.cultureContent}>
                            <span className={styles.cultureSectionTag}>Workplace Evolution</span>
                            <h2 className={styles.cultureTitle}>As remote as you are.</h2>
                            <p className={styles.cultureDesc}>
                                We believe that the best talent shouldn't be restricted by geography. TalentMesh is a remote-first organization with hubs in Ahmedabad, San Francisco, and London.
                            </p>
                            <ul className={styles.perksList}>
                                {[
                                    { icon: <LaptopOutlinedIcon sx={{ fontSize: 18 }} />, text: "Remote-first culture with flex-hours" },
                                    { icon: <PublicOutlinedIcon sx={{ fontSize: 18 }} />, text: "Coworking stipends in 50+ countries" },
                                    { icon: <FavoriteOutlinedIcon sx={{ fontSize: 18 }} />, text: "Comprehensive family leave & wellness" }
                                ].map((li, idx) => (
                                    <li key={idx} className={styles.perksItem}>
                                        <span className={styles.perksIcon}>{li.icon}</span>
                                        {li.text}
                                    </li>
                                ))}
                            </ul>
                        </div>
                    </div>
                </section>
            </AnimateOnScroll>

            {/* ── Open Positions ── */}
            <AnimateOnScroll animation="fadeUp" delay={100}>
                <section className={styles.positionsSection}>
                    <div className="premium-container">
                        <div className={styles.positionsHeader}>
                            <h2 className={styles.positionsTitle}>Open Positions</h2>
                            <p className={styles.positionsSubtitle}>Find your next challenge and grow with us.</p>
                        </div>
                        <JobListings />
                    </div>
                </section>
            </AnimateOnScroll>

            {/* ── Benefits Matrix ── */}
            <AnimateOnScroll animation="fadeUp" delay={150}>
                <section className={styles.benefitsSection}>
                    <div className={styles.benefitsGrid}>
                        {[
                            { icon: <BoltOutlinedIcon />, title: "Learning", text: "$2.5k annual learning budget." },
                            { icon: <LocalCafeOutlinedIcon />, title: "Perks", text: "Healthy snacks & coffee stipends." },
                            { icon: <VerifiedUserOutlinedIcon />, title: "Health", text: "Premium global medical coverage." },
                            { icon: <LaptopOutlinedIcon />, title: "Stock", text: "Equity options for all employees." }
                        ].map((item, i) => (
                            <div key={i} className={styles.benefitCard}>
                                <div className={styles.benefitIcon}>{item.icon}</div>
                                <h4 className={styles.benefitTitle}>{item.title}</h4>
                                <p className={styles.benefitText}>{item.text}</p>
                            </div>
                        ))}
                    </div>
                </section>
            </AnimateOnScroll>

            <AnimateOnScroll animation="scaleUp">
                <CTA />
            </AnimateOnScroll>
        </main>
    );
}

/* ============================
   CAREERS PAGE — TalentMesh
   Premium Edition
   ============================ */

.page {
    min-height: 100vh;
    background: #ffffff;
}

/* ── Culture Section ── */
.cultureSection {
    padding: 8rem 2rem;
}

.cultureGrid {
    max-width: 1200px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 6rem;
    align-items: center;
}

/* Culture value cards grid */
.cultureCards {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 1.25rem;
}

.cultureCard {
    aspect-ratio: 1/1;
    border-radius: 20px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 0.75rem;
    font-weight: 800;
    color: var(--deep-navy);
    font-size: 1rem;
    position: relative;
    overflow: hidden;
    border: 1px solid transparent;
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.cultureCard::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: 20px;
    padding: 2px;
    background: linear-gradient(135deg, transparent, transparent);
    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    transition: all 0.4s ease;
}

.cultureCard:hover {
    transform: translateY(-6px);
    box-shadow: 0 16px 40px rgba(0, 0, 0, 0.08);
}

.cultureCardBlue {
    background: linear-gradient(145deg, #eff6ff, #dbeafe);
}

.cultureCardBlue:hover::before {
    background: linear-gradient(135deg, #3b82f6, #60a5fa);
}

.cultureCardGreen {
    background: linear-gradient(145deg, #f0fdf4, #dcfce7);
}

.cultureCardGreen:hover::before {
    background: linear-gradient(135deg, #10b981, #34d399);
}

.cultureCardRed {
    background: linear-gradient(145deg, #fef2f2, #fee2e2);
}

.cultureCardRed:hover::before {
    background: linear-gradient(135deg, #ef4444, #f87171);
}

.cultureCardPurple {
    background: linear-gradient(145deg, #faf5ff, #f3e8ff);
}

.cultureCardPurple:hover::before {
    background: linear-gradient(135deg, #8b5cf6, #a78bfa);
}

.cultureCardIcon {
    color: var(--primary-blue);
    width: 28px;
    height: 28px;
}

.cultureImageWrapper {
    position: relative;
    width: 100%;
    aspect-ratio: 1/1;
    border-radius: 30px;
    overflow: hidden;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.1);
}

.cultureImg {
    object-fit: cover;
    transition: transform 0.8s cubic-bezier(0.4, 0, 0.2, 1);
}

.cultureImageWrapper:hover .cultureImg {
    transform: scale(1.05);
}

/* ── Culture Content ── */
.cultureContent {
    display: flex;
    flex-direction: column;
}

.cultureSectionTag {
    color: var(--primary-blue);
    font-weight: 800;
    text-transform: uppercase;
    font-size: 0.82rem;
    letter-spacing: 0.12em;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 0.4rem 1rem;
    background: rgba(59, 130, 246, 0.08);
    border-radius: 50px;
    border: 1px solid rgba(59, 130, 246, 0.15);
    width: fit-content;
}

.cultureTitle {
    font-size: 3rem;
    font-weight: 900;
    color: var(--deep-navy);
    margin: 1.5rem 0;
    letter-spacing: -0.03em;
    line-height: 1.1;
}

.cultureDesc {
    color: var(--medium-grey);
    font-size: 1.1rem;
    line-height: 1.8;
    margin-bottom: 2.5rem;
}

/* Perks list */
.perksList {
    list-style: none;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0;
}

.perksItem {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 0.85rem 0;
    font-weight: 600;
    color: var(--deep-navy);
    border-bottom: 1px solid rgba(0, 0, 0, 0.04);
    transition: all 0.3s ease;
}

.perksItem:last-child {
    border-bottom: none;
}

.perksItem:hover {
    transform: translateX(6px);
}

.perksIcon {
    color: var(--primary-blue);
    flex-shrink: 0;
    width: 36px;
    height: 36px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(59, 130, 246, 0.08);
    border-radius: 10px;
}

/* ── Open Positions Section ── */
.positionsSection {
    padding: 8rem 2rem;
    background: linear-gradient(180deg, #f8fafc 0%, #f1f5f9 100%);
    position: relative;
    overflow: hidden;
}

.positionsSection::before {
    content: '';
    position: absolute;
    top: -200px;
    right: -200px;
    width: 500px;
    height: 500px;
    background: radial-gradient(circle, rgba(59, 130, 246, 0.05) 0%, transparent 70%);
    border-radius: 50%;
}

.positionsHeader {
    text-align: center;
    margin-bottom: 4rem;
    position: relative;
}

.positionsTitle {
    font-size: 3rem;
    font-weight: 900;
    letter-spacing: -0.04em;
    color: var(--deep-navy);
}

.positionsSubtitle {
    color: var(--medium-grey);
    margin-top: 1rem;
    font-size: 1.1rem;
}

/* ── Benefits Section ── */
.benefitsSection {
    padding: 8rem 2rem;
}

.benefitsGrid {
    max-width: 1200px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 2rem;
}

.benefitCard {
    text-align: center;
    padding: 2.5rem 1.5rem;
    border-radius: 24px;
    background: #ffffff;
    border: 1px solid #f1f5f9;
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    position: relative;
}

.benefitCard:hover {
    transform: translateY(-8px);
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.06);
    border-color: rgba(59, 130, 246, 0.15);
}

.benefitIcon {
    width: 56px;
    height: 56px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #eff6ff, #dbeafe);
    border-radius: 16px;
    color: var(--primary-blue);
    margin: 0 auto 1.5rem;
    transition: all 0.3s ease;
}

.benefitCard:hover .benefitIcon {
    background: linear-gradient(135deg, #3b82f6, #2563eb);
    color: #fff;
    box-shadow: 0 8px 20px rgba(59, 130, 246, 0.3);
}

.benefitTitle {
    font-weight: 800;
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
    color: var(--deep-navy);
}

.benefitText {
    font-size: 0.9rem;
    color: var(--medium-grey);
    line-height: 1.6;
}

/* ── Responsive ── */
@media (max-width: 1024px) {
    .cultureGrid {
        grid-template-columns: 1fr;
        gap: 4rem;
    }

    .benefitsGrid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 640px) {
    .cultureCards {
        grid-template-columns: 1fr;
    }

    .cultureTitle {
        font-size: 2.25rem;
    }

    .benefitsGrid {
        grid-template-columns: 1fr;
    }

    .positionsTitle {
        font-size: 2.25rem;
    }

    .cultureCard {
        aspect-ratio: auto;
        padding: 2rem;
    }
}

/* ─── Page ───────────────────────────────────────────────────────────────────── */
.page {
    padding-top: 68px;
    min-height: 100vh;
    background: var(--light-ice-blue, #F0F7FF);
}

/* ─── Hero ───────────────────────────────────────────────────────────────────── */
.hero {
    background: linear-gradient(135deg, var(--alice-blue, #E3F2FD) 0%, var(--light-ice-blue, #F0F7FF) 100%);
    padding: 60px 0 52px;
    text-align: center;
    border-bottom: 1px solid var(--sky-blue, #90CAF9);
}

.heroInner {
    max-width: 680px;
    margin: 0 auto;
}

.heroTitle {
    font-size: clamp(1.9rem, 4.5vw, 3rem);
    font-weight: 800;
    color: var(--cobalt-blue, #0D47A1);
    margin: 0 0 16px;
    line-height: 1.15;
    letter-spacing: -0.02em;
}

.heroSub {
    font-size: 1.08rem;
    color: var(--medium-grey, #475569);
    margin: 0 auto 24px;
    line-height: 1.65;
}

.trustNote {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: var(--alice-blue);
    border-left: 4px solid var(--primary-blue, #007BFF);
    color: var(--ocean-deep, #1565C0);
    font-size: 0.9rem;
    padding: 10px 18px;
    border-radius: 0 8px 8px 0;
}

/* ─── Form Section ───────────────────────────────────────────────────────────── */
.formSection {
    padding: 48px 0;
}

.formLayout {
    display: grid;
    grid-template-columns: 1fr 320px;
    gap: 32px;
    align-items: flex-start;
}

/* Form card */
.formCard {
    background: white;
    border-radius: 24px;
    box-shadow: 0 8px 40px rgba(0, 0, 0, 0.10);
    padding: 40px;
}

.formTitle {
    font-size: 1.35rem;
    font-weight: 700;
    color: var(--cobalt-blue);
    margin: 0 0 4px;
}

.formNote {
    font-size: 0.82rem;
    color: var(--medium-grey);
    margin: 0 0 28px;
}

.form {
    display: flex;
    flex-direction: column;
    gap: 20px;
}

.fieldRow {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
}

.field {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.label {
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--cobalt-blue, #0D47A1);
}

.optional {
    font-style: italic;
    font-weight: 400;
    color: var(--medium-grey);
    font-size: 0.8rem;
}

.selectAll {
    font-weight: 400;
    color: var(--medium-grey);
    font-size: 0.8rem;
}

.input,
.select,
.textarea {
    border: 1px solid var(--sky-blue, #90CAF9);
    border-radius: 8px;
    padding: 11px 14px;
    font-size: 0.9rem;
    font-family: inherit;
    background: white;
    color: var(--deep-navy, #0d2137);
    transition: border-color 0.2s, box-shadow 0.2s;
    outline: none;
    appearance: none;
}

.input::placeholder,
.textarea::placeholder {
    color: rgba(71, 85, 105, 0.55);
}

.input:focus,
.select:focus,
.textarea:focus {
    border-color: var(--primary-blue, #007BFF);
    box-shadow: 0 0 0 3px rgba(0, 123, 255, 0.12);
}

.select {
    cursor: pointer;
}

.textarea {
    resize: vertical;
    min-height: 100px;
}

/* Multi-select chips */
.chipGroup {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 4px;
}

.helpChip {
    padding: 7px 14px;
    border-radius: 999px;
    border: 1px solid var(--sky-blue, #90CAF9);
    background: white;
    color: var(--ocean-deep, #1565C0);
    font-size: 0.83rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.18s ease;
    font-family: inherit;
}

.helpChip:hover {
    border-color: var(--dodger-blue);
    color: var(--dodger-blue);
}

.helpChipActive {
    background: var(--dodger-blue, #2196F3) !important;
    color: white !important;
    border-color: var(--dodger-blue) !important;
}

/* Radio group */
.radioGroup {
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
    margin-top: 4px;
}

.radioLabel {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 0.88rem;
    color: var(--medium-grey);
    cursor: pointer;
}

.radioLabel input {
    accent-color: var(--primary-blue);
    cursor: pointer;
}

/* Submit */
.submitBtn {
    width: 100%;
    height: 52px;
    background: linear-gradient(135deg, var(--primary-blue, #007BFF) 0%, var(--dodger-blue, #2196F3) 100%);
    color: white;
    border: none;
    border-radius: 12px;
    font-size: 1rem;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.2s ease;
    margin-top: 4px;
    font-family: inherit;
}

.submitBtn:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(0, 123, 255, 0.45);
}

/* Success state */
.successState {
    text-align: center;
    padding: 48px 24px;
}

.successIco {
    width: 56px;
    height: 56px;
    border-radius: 50%;
    background: #DCFCE7;
    color: #16A34A;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 16px;
}

.successTitle {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--cobalt-blue);
    margin: 0 0 10px;
}

.successDesc {
    font-size: 1rem;
    color: var(--medium-grey);
    margin: 0 0 20px;
    line-height: 1.6;
}

.successBadge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: var(--alice-blue);
    color: var(--ocean-deep);
    font-weight: 600;
    font-size: 0.88rem;
    padding: 8px 18px;
    border-radius: 999px;
    border: 1px solid var(--sky-blue);
}

/* ─── Aside ──────────────────────────────────────────────────────────────────── */
.aside {
    position: sticky;
    top: 88px;
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.asideCard {
    background: white;
    border-radius: 16px;
    padding: 24px;
    border: 1px solid var(--sky-blue);
}

.asideTitle {
    font-size: 1rem;
    font-weight: 700;
    color: var(--cobalt-blue);
    margin: 0 0 16px;
}

.asideItem {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    font-size: 0.88rem;
    color: var(--medium-grey);
    margin-bottom: 10px;
}

.asideCheck {
    color: var(--primary-blue);
    flex-shrink: 0;
    margin-top: 1px;
}

.asideStat {
    background: white;
    border-radius: 16px;
    padding: 20px;
    border: 1px solid var(--sky-blue);
    display: flex;
    justify-content: space-between;
    gap: 8px;
}

.asideStatItem {
    text-align: center;
}

.asideStatVal {
    font-size: 1.5rem;
    font-weight: 800;
    color: var(--cobalt-blue);
}

.asideStatLabel {
    font-size: 0.72rem;
    color: var(--medium-grey);
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

/* ─── How It Works ───────────────────────────────────────────────────────────── */
.howSection {
    background: var(--light-ice-blue, #F0F7FF);
    padding: 64px 0;
}

.sectionTitle {
    font-size: clamp(1.5rem, 3vw, 2rem);
    font-weight: 700;
    color: var(--cobalt-blue);
    text-align: center;
    margin: 0 0 40px;
}

.stepsRow {
    display: flex;
    align-items: center;
    gap: 0;
    justify-content: center;
}

.stepCard {
    text-align: center;
    max-width: 200px;
    padding: 0 8px;
}

.stepCircle {
    width: 52px;
    height: 52px;
    border-radius: 50%;
    background: var(--dodger-blue, #2196F3);
    color: white;
    font-size: 1.15rem;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 14px;
    box-shadow: 0 4px 16px rgba(33, 150, 243, 0.35);
}

.stepConnector {
    flex: 1;
    height: 2px;
    border-top: 2px dashed var(--sky-blue, #90CAF9);
    max-width: 60px;
    flex-shrink: 0;
}

.stepTitle {
    font-size: 0.93rem;
    font-weight: 700;
    color: var(--cobalt-blue);
    margin: 0 0 6px;
}

.stepDesc {
    font-size: 0.8rem;
    color: var(--medium-grey);
    line-height: 1.5;
    margin: 0;
}

/* ─── Trust Section ──────────────────────────────────────────────────────────── */
.trustSection {
    background: white;
    padding: 64px 0 0;
}

.testiGrid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 20px;
    margin-bottom: 48px;
}

.testiCard {
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(12px);
    border-radius: 16px;
    border: 1px solid rgba(144, 202, 249, 0.5);
    padding: 28px;
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.stars {
    display: flex;
    gap: 3px;
    color: #F59E0B;
}

.quote {
    font-size: 0.93rem;
    color: var(--medium-grey);
    line-height: 1.65;
    margin: 0;
    font-style: italic;
}

.author {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-top: auto;
}

.authorAvatar {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--primary-blue), var(--dodger-blue));
    color: white;
    font-weight: 700;
    font-size: 0.85rem;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.authorName {
    font-size: 0.88rem;
    font-weight: 700;
    color: var(--cobalt-blue);
}

.authorRole {
    font-size: 0.78rem;
    color: var(--medium-grey);
}

/* Stats bar */
.statsBar {
    background: var(--ocean-deep, #1565C0);
    padding: 40px 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0;
}

.statsDivider {
    width: 1px;
    height: 48px;
    background: rgba(144, 202, 249, 0.35);
    margin: 0 48px;
}

.statItem {
    text-align: center;
}

.statVal {
    font-size: 2.25rem;
    font-weight: 800;
    color: white;
    line-height: 1;
}

.statLabel {
    font-size: 0.85rem;
    color: var(--sky-blue, #90CAF9);
    margin-top: 4px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-weight: 500;
}

/* ─── Responsive ─────────────────────────────────────────────────────────────── */
@media (max-width: 1024px) {
    .formLayout {
        grid-template-columns: 1fr;
    }

    .aside {
        position: static;
        flex-direction: row;
    }

    .asideCard {
        flex: 1;
    }

    .asideStat {
        flex: 0 0 auto;
    }
}

@media (max-width: 768px) {
    .stepsRow {
        flex-direction: column;
        gap: 24px;
    }

    .stepConnector {
        transform: rotate(90deg);
        max-width: 32px;
    }

    .testiGrid {
        grid-template-columns: 1fr;
    }

    .aside {
        flex-direction: column;
    }

    .statsBar {
        flex-direction: column;
        gap: 28px;
    }

    .statsDivider {
        width: 100%;
        height: 1px;
        margin: 0;
    }
}

@media (max-width: 640px) {
    .formCard {
        padding: 24px 20px;
    }

    .fieldRow {
        grid-template-columns: 1fr;
    }
}

'use client';
import React, { useState, useMemo, useCallback, useEffect } from 'react';
import Link from 'next/link';
import styles from './jobs.module.css';
import { insforge } from '@/lib/insforge';
import { BlogFeed } from '@/components/sections';

// ─── Icons ───────────────────────────────────────────────────────────────────
const Ico = {
    Search: () => <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="11" cy="11" r="8" /><path d="m21 21-4.3-4.3" /></svg>,
    Location: () => <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z" /><circle cx="12" cy="10" r="3" /></svg>,
    Briefcase: () => <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="2" y="7" width="20" height="14" rx="2" /><path d="M16 7V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v2" /></svg>,
    Sparkle: () => <svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor"><path d="m12 3 1.912 5.885L20 10.8l-5.088 1.912L13 18.6l-1.912-5.888L6 10.8l5.088-1.915Z" /></svg>,
    Heart: () => <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" /></svg>,
    HeartFill: () => <svg width="17" height="17" viewBox="0 0 24 24" fill="currentColor"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" /></svg>,
    Filter: () => <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3" /></svg>,
    Close: () => <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18M6 6l12 12" /></svg>,
    ChevDown: () => <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="6 9 12 15 18 9" /></svg>,
    Clock: () => <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10" /><polyline points="12 6 12 12 16 14" /></svg>,
    ArrowR: () => <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14m-7-7 7 7-7 7" /></svg>,
};

const CATEGORY_CHIPS = ['All', 'Engineering', 'Design', 'Marketing', 'Product', 'Finance', 'HR'];
const POPULAR_TAGS = ['Remote Engineer', 'Product Designer', 'Marketing AI', 'Finance Lead', 'Data Scientist', 'UX Lead'];
const JOB_TYPES = ['Full-Time', 'Part-Time', 'Remote', 'Internship', 'Contract'];
const INDUSTRIES = ['Engineering', 'Finance', 'Marketing', 'Design', 'HR', 'Product', 'Operations', 'Customer Service'];
const EXP_LEVELS = ['Entry', 'Mid', 'Senior', 'Lead'];
const COUNTRIES = ['India', 'USA'];
const DATE_OPTS = ['Last 24hrs', 'Last 7 days', 'Last 30 days'];
const JOBS_PER_PAGE = 6;

export default function BrowseJobsPage() {
    const [jobs, setJobs] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState('');
    const [locSearch, setLocSearch] = useState('');
    const [jobType, setJobType] = useState('');
    const [filterOpen, setFilterOpen] = useState(false);
    const [category, setCategory] = useState('All');
    const [activeTypes, setActiveTypes] = useState<string[]>([]);
    const [activeInds, setActiveInds] = useState<string[]>([]);
    const [activeExps, setActiveExps] = useState<string[]>([]);
    const [activeCountries, setActiveCountries] = useState<string[]>([]);
    const [dateFilter, setDateFilter] = useState('');
    const [savedJobs, setSavedJobs] = useState<Set<string>>(new Set());
    const [page, setPage] = useState(1);

    useEffect(() => {
        async function fetchJobs() {
            try {
                const { data } = await insforge.database
                    .from('jobs')
                    .select('*, company_profiles(*)');
                setJobs(data || []);
            } catch (err) {
                console.error('Error fetching jobs:', err);
            } finally {
                setLoading(false);
            }
        }
        fetchJobs();
    }, []);

    const toggleArr = (arr: string[], setArr: (v: string[]) => void, val: string) =>
        setArr(arr.includes(val) ? arr.filter(x => x !== val) : [...arr, val]);

    const filtered = useMemo(() => {
        return jobs.filter(j => {
            if (search && !j.title.toLowerCase().includes(search.toLowerCase()) && !j.company_profiles?.company_name.toLowerCase().includes(search.toLowerCase())) return false;
            if (locSearch && !j.location.toLowerCase().includes(locSearch.toLowerCase())) return false;
            if (jobType && j.type !== jobType) return false;
            if (category !== 'All' && !j.department?.toLowerCase().includes(category.toLowerCase()) && !j.title.toLowerCase().includes(category.toLowerCase())) return false;
            if (activeTypes.length && !activeTypes.includes(j.type)) return false;
            // Industry filter (mapping department to industry for now)
            if (activeInds.length && !activeInds.includes(j.department)) return false;
            return true;
        });
    }, [jobs, search, locSearch, jobType, category, activeTypes, activeInds, activeExps, activeCountries, dateFilter]);

    const pages = Math.ceil(filtered.length / JOBS_PER_PAGE);
    const paginated = filtered.slice((page - 1) * JOBS_PER_PAGE, page * JOBS_PER_PAGE);

    const toggleSave = useCallback((id: string) => {
        setSavedJobs(prev => { const n = new Set(prev); n.has(id) ? n.delete(id) : n.add(id); return n; });
    }, []);

    const matchColor = (s: number) => s >= 90 ? '#059669' : s >= 80 ? '#1E88E5' : '#475569';

    if (loading) return <div className={styles.page}><p style={{ color: 'white', padding: '5rem', textAlign: 'center' }}>Loading Jobs...</p></div>;

    return (
        <main className={styles.page}>
            {/* ── HERO ── */}
            <section className={styles.hero}>
                <div className="premium-container">
                    <div className={styles.heroContent}>
                        <h1 className={styles.heroTitle}>Find Your Next Opportunity</h1>
                        <p className={styles.heroSub}>Browse thousands of roles matched to your skills by our AI engine.</p>

                        {/* Search Bar */}
                        <div className={styles.searchCard}>
                            <div className={styles.searchField}>
                                <Ico.Search />
                                <input value={search} onChange={e => { setSearch(e.target.value); setPage(1); }}
                                    placeholder="Job title, role, or keyword" className={styles.searchInput} />
                            </div>
                            <div className={styles.searchDivider} />
                            <div className={styles.searchField}>
                                <Ico.Location />
                                <input value={locSearch} onChange={e => { setLocSearch(e.target.value); setPage(1); }}
                                    placeholder="City or Remote" className={styles.searchInput} />
                            </div>
                            <div className={styles.searchDivider} />
                            <div className={styles.searchField}>
                                <Ico.Briefcase />
                                <select value={jobType} onChange={e => { setJobType(e.target.value); setPage(1); }} className={styles.searchSelect}>
                                    <option value="">Job Type</option>
                                    {JOB_TYPES.map(t => <option key={t}>{t}</option>)}
                                </select>
                            </div>
                            <button className={styles.searchBtn}><Ico.Search /> Search</button>
                        </div>

                        {/* Popular Tags */}
                        <div className={styles.popularTags}>
                            <span className={styles.popularLabel}>Popular:</span>
                            {POPULAR_TAGS.map(tag => (
                                <button key={tag} className={styles.popularTag} onClick={() => { setSearch(tag); setPage(1); }}>{tag}</button>
                            ))}
                        </div>
                    </div>
                </div>
            </section>

            {/* ── BODY ── */}
            <div className="premium-container">
                <div className={styles.body}>

                    {/* ── Sidebar ── */}
                    <>
                        {/* Mobile overlay */}
                        {filterOpen && <div className={styles.overlay} onClick={() => setFilterOpen(false)} />}
                        <aside className={`${styles.sidebar} ${filterOpen ? styles.sidebarOpen : ''}`}>
                            <div className={styles.sidebarHead}>
                                <span className={styles.sidebarTitle}><Ico.Filter /> Filters</span>
                                <button className={styles.sidebarClose} onClick={() => setFilterOpen(false)} aria-label="Close filters"><Ico.Close /></button>
                            </div>

                            <FilterGroup label="Job Type">
                                {JOB_TYPES.map(t => (
                                    <label key={t} className={styles.filterCheck}>
                                        <input type="checkbox" checked={activeTypes.includes(t)} onChange={() => { toggleArr(activeTypes, setActiveTypes, t); setPage(1); }} />
                                        <span>{t}</span>
                                    </label>
                                ))}
                            </FilterGroup>
                            <FilterGroup label="Industry">
                                {INDUSTRIES.map(i => (
                                    <label key={i} className={styles.filterCheck}>
                                        <input type="checkbox" checked={activeInds.includes(i)} onChange={() => { toggleArr(activeInds, setActiveInds, i); setPage(1); }} />
                                        <span>{i}</span>
                                    </label>
                                ))}
                            </FilterGroup>
                        </aside>
                    </>

                    {/* ── Main Content ── */}
                    <div className={styles.main}>
                        {/* Mobile filter toggle */}
                        <button className={styles.mobileFilterBtn} onClick={() => setFilterOpen(true)}><Ico.Filter /> Filters {(activeTypes.length + activeInds.length) > 0 && <span className={styles.filterCount}>{activeTypes.length + activeInds.length}</span>}</button>

                        {/* Category chips */}
                        <div className={styles.categoryRow}>
                            {CATEGORY_CHIPS.map(c => (
                                <button key={c} className={`${styles.categoryChip} ${category === c ? styles.categoryChipActive : ''}`}
                                    onClick={() => { setCategory(c); setPage(1); }}>{c}</button>
                            ))}
                        </div>

                        {/* Results header */}
                        <div className={styles.resultsHdr}>
                            <span className={styles.resultsCount}><strong>{filtered.length}</strong> jobs found</span>
                            <span className={styles.aiPill}><Ico.Sparkle /> AI Match Enabled</span>
                        </div>

                        {/* Job Cards */}
                        {paginated.length > 0 ? (
                            <div className={styles.jobGrid}>
                                {paginated.map(job => (
                                    <Link key={job.id} href={`/browse-jobs/${job.id}`} className={`${styles.jobCard} glass-card`} style={{ textDecoration: 'none', color: 'inherit' }}>
                                        <div className={styles.cardTop}>
                                            <div className={styles.jobLogo} style={{ background: job.company_profiles?.color || '#0D47A1' }}>{job.company_profiles?.initials || job.company_profiles?.company_name?.[0]}</div>
                                            <div className={styles.jobInfo}>
                                                <div className={styles.jobTitle}>{job.title}</div>
                                                <div className={styles.jobMeta}>
                                                    <span>{job.company_profiles?.company_name}</span>
                                                    <span className={styles.metaDot}>·</span>
                                                    <Ico.Location /><span>{job.location}</span>
                                                </div>
                                            </div>
                                            <button
                                                className={`${styles.saveBtn} ${savedJobs.has(job.id) ? styles.saveBtnActive : ''}`}
                                                onClick={(e) => { e.preventDefault(); toggleSave(job.id); }}
                                                aria-label={savedJobs.has(job.id) ? 'Unsave' : 'Save job'}>
                                                {savedJobs.has(job.id) ? <Ico.HeartFill /> : <Ico.Heart />}
                                            </button>
                                        </div>

                                        <div className={styles.badgeRow}>
                                            <span className={`${styles.typeBadge} ${styles[`type_${job.type?.replace('-', '').replace(' ', '')}`]}`}>{job.type}</span>
                                            <span className={styles.salaryBadge}>{job.salary}</span>
                                            {job.ai_match_rate >= 80 && (
                                                <span className={styles.matchBadge} style={{ color: matchColor(job.ai_match_rate) }}>
                                                    <Ico.Sparkle /> {job.ai_match_rate}% Match
                                                </span>
                                            )}
                                        </div>

                                        <div className={styles.cardFooter}>
                                            <span className={styles.postedMeta}><Ico.Clock />{job.posted_days} days ago</span>
                                            <div className={styles.cardActions}>
                                                <span className={styles.applyBtn} onClick={(e) => { e.preventDefault(); window.location.href = '/signup'; }}>Quick Apply</span>
                                                <span className={styles.viewBtn}>View <Ico.ArrowR /></span>
                                            </div>
                                        </div>
                                    </Link>
                                ))}
                            </div>
                        ) : (
                            <div className={styles.emptyState}>
                                <h3 className={styles.emptyTitle}>No exact matches found</h3>
                                <p className={styles.emptyDesc}>Try adjusting your filters or search terms.</p>
                            </div>
                        )}

                        {/* Pagination */}
                        {pages > 1 && (
                            <div className={styles.pagination}>
                                {Array.from({ length: pages }, (_, i) => i + 1).map(p => (
                                    <button key={p} className={`${styles.pageBtn} ${p === page ? styles.pageBtnActive : ''}`}
                                        onClick={() => setPage(p)}>{p}</button>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            </div>
            <BlogFeed />
        </main>
    );
}

function FilterGroup({ label, children }: { label: string; children: React.ReactNode }) {
    const [open, setOpen] = useState(true);
    return (
        <div className={styles.filterGroup}>
            <button className={styles.filterGroupHdr} onClick={() => setOpen(o => !o)}>
                <span>{label}</span>
                <span style={{ transform: open ? 'rotate(180deg)' : 'none', transition: 'transform 0.2s' }}><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="6 9 12 15 18 9" /></svg></span>
            </button>
            {open && <div className={styles.filterGroupBody}>{children}</div>}
        </div>
    );
}

// Shared job listings data used by browse-jobs and job detail pages

export interface Job {
    id: number;
    title: string;
    company: string;
    location: string;
    salary: string;
    type: string;
    industry: string;
    exp: string;
    logo: string;
    color: string;
    match: number;
    posted: string;
    country: string;
    description: string;
    responsibilities: string[];
    requirements: string[];
    benefits: string[];
    about: string;
}

export const JOBS: Job[] = [
    {
        id: 1, title: 'Senior AI Researcher', company: 'Quantum Leap', location: 'Palo Alto', salary: '$190k–$260k', type: 'Full-Time', industry: 'Engineering', exp: 'Senior', logo: 'QL', color: '#0D47A1', match: 96, posted: '1 day ago', country: 'USA',
        description: 'We are looking for a Senior AI Researcher to push the boundaries of machine learning and artificial intelligence. You will work on cutting-edge research in deep learning, NLP, and computer vision, publishing papers and building production-ready models.',
        responsibilities: ['Lead research initiatives in deep learning and generative AI', 'Design and implement novel ML architectures', 'Publish findings in top-tier conferences (NeurIPS, ICML, CVPR)', 'Mentor junior researchers and engineers', 'Collaborate with product teams to deploy models at scale'],
        requirements: ['PhD in Computer Science, ML, or related field', '5+ years of research experience in AI/ML', 'Strong publication record in top venues', 'Proficiency in PyTorch or TensorFlow', 'Experience with large-scale distributed training'],
        benefits: ['Competitive equity package', 'Unlimited PTO', 'Annual conference budget', '$5,000 learning stipend', 'Premium health & dental'],
        about: 'Quantum Leap is a Series C AI startup building the next generation of intelligent systems. Backed by Sequoia and a16z, we are redefining how enterprises leverage AI.'
