export function getJobById(id: number): Job | undefined {
    return JOBS.find(j => j.id === id);
}

/* ─── Page Layout ────────────────────────────────────────────────────────────── */
.page {
    padding-top: 68px;
    /* navbar height */
    min-height: 100vh;
    background: var(--light-ice-blue, #F0F7FF);
}

/* ─── Hero ───────────────────────────────────────────────────────────────────── */
.hero {
    background: radial-gradient(ellipse 80% 60% at 50% 0%, var(--alice-blue, #E3F2FD), var(--light-ice-blue, #F0F7FF));
    padding: 56px 0 48px;
    border-bottom: 1px solid var(--sky-blue, #90CAF9);
}

.heroContent {
    text-align: center;
}

.heroTitle {
    font-size: clamp(2rem, 5vw, 3.25rem);
    font-weight: 800;
    color: var(--cobalt-blue, #0D47A1);
    margin: 0 0 12px;
    letter-spacing: -0.02em;
    line-height: 1.15;
}

.heroSub {
    font-size: 1.1rem;
    color: var(--medium-grey, #475569);
    margin: 0 auto 32px;
    max-width: 540px;
}

/* Search bar */
.searchCard {
    display: flex;
    align-items: center;
    background: white;
    border-radius: 16px;
    box-shadow: 0 8px 32px -4px rgba(0, 0, 0, 0.12);
    overflow: hidden;
    max-width: 780px;
    margin: 0 auto;
    border: 1px solid rgba(144, 202, 249, 0.4);
}

.searchField {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 0 16px;
    flex: 1;
    color: var(--medium-grey);
    min-width: 0;
}

.searchInput,
.searchSelect {
    border: none;
    outline: none;
    background: transparent;
    font-size: 0.93rem;
    color: var(--deep-navy, #0d2137);
    width: 100%;
    padding: 18px 0;
    font-family: inherit;
    appearance: none;
}

.searchInput::placeholder {
    color: rgba(71, 85, 105, 0.55);
}

.searchSelect {
    cursor: pointer;
}

.searchDivider {
    width: 1px;
    height: 32px;
    background: var(--sky-blue, #90CAF9);
    flex-shrink: 0;
}

.searchBtn {
    display: flex;
    align-items: center;
    gap: 8px;
    background: var(--primary-blue, #007BFF);
    color: white;
    border: none;
    padding: 0 28px;
    height: 58px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
    white-space: nowrap;
    flex-shrink: 0;
}

.searchBtn:hover {
    background: #0069d9;
    box-shadow: 0 4px 16px rgba(0, 123, 255, 0.4);
}

/* Popular Tags */
.popularTags {
    display: flex;
    align-items: center;
    gap: 8px;
    justify-content: center;
    flex-wrap: wrap;
    margin-top: 20px;
}

.popularLabel {
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--medium-grey);
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

.popularTag {
    padding: 6px 14px;
    border-radius: 999px;
    border: 1px solid var(--sky-blue, #90CAF9);
    background: var(--alice-blue, #E3F2FD);
    color: var(--ocean-deep, #1565C0);
    font-size: 0.82rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;
}

.popularTag:hover {
    background: var(--dodger-blue, #2196F3);
    color: white;
    border-color: var(--dodger-blue);
}

/* ─── Body Layout ────────────────────────────────────────────────────────────── */
.body {
    display: flex;
    gap: 28px;
    padding: 32px 0 60px;
    align-items: flex-start;
}

/* ─── Sidebar ────────────────────────────────────────────────────────────────── */
.sidebar {
    width: 256px;
    min-width: 256px;
    background: white;
    border-radius: 14px;
    border: 1px solid var(--sky-blue, #90CAF9);
    border-left: 3px solid var(--sky-blue, #90CAF9);
    overflow: hidden;
    position: sticky;
    top: 88px;
}

.sidebarHead {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 16px 12px;
    border-bottom: 1px solid var(--sky-blue, #90CAF9);
}

.sidebarTitle {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 0.9rem;
    font-weight: 700;
    color: var(--cobalt-blue);
}

.sidebarClose {
    background: none;
    border: none;
    cursor: pointer;
    color: var(--medium-grey);
    padding: 4px;
    display: none;
    line-height: 0;
}

/* Active filter chips */
.activeFilters {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    padding: 10px 14px;
    border-bottom: 1px solid var(--sky-blue, #90CAF9);
}

.activeChip {
    display: flex;
    align-items: center;
    gap: 4px;
    background: var(--cool-sky-2, #42A5F5);
    color: white;
    font-size: 0.75rem;
    font-weight: 600;
    padding: 3px 8px;
    border-radius: 999px;
}

.activeChip button {
    background: none;
    border: none;
    color: white;
    cursor: pointer;
    font-size: 0.85rem;
    padding: 0;
    line-height: 1;
}

.clearAll {
    font-size: 0.75rem;
    color: var(--primary-blue);
    background: none;
    border: none;
    cursor: pointer;
    text-decoration: underline;
    padding: 2px 0;
}

/* Filter groups */
.filterGroup {
    border-bottom: 1px solid var(--sky-blue, #90CAF9);
}

.filterGroup:last-child {
    border-bottom: none;
}

.filterGroupHdr {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 12px 16px;
    background: none;
    border: none;
    cursor: pointer;
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--cobalt-blue, #0D47A1);
    text-transform: uppercase;
    letter-spacing: 0.07em;
    text-align: left;
}

.filterGroupBody {
    padding: 4px 16px 12px;
}

.filterCheck {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.87rem;
    color: var(--medium-grey, #475569);
    cursor: pointer;
    padding: 5px 0;
    transition: color 0.15s;
}

.filterCheck:hover {
    color: var(--primary-blue);
}

.filterCheck input {
    accent-color: var(--primary-blue, #007BFF);
    width: 15px;
    height: 15px;
    cursor: pointer;
}

/* ─── Main Content ────────────────────────────────────────────────────────────── */
.main {
    flex: 1;
    min-width: 0;
}

.overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
    z-index: 900;
}

/* Mobile filter btn */
.mobileFilterBtn {
    display: none;
    align-items: center;
    gap: 8px;
    background: white;
    border: 1px solid var(--sky-blue);
    border-radius: 8px;
    padding: 10px 18px;
    font-size: 0.9rem;
    font-weight: 600;
    color: var(--cobalt-blue);
    cursor: pointer;
    margin-bottom: 16px;
}

.filterCount {
    background: var(--primary-blue);
    color: white;
    font-size: 0.7rem;
    font-weight: 700;
    border-radius: 999px;
    padding: 1px 7px;
}

/* Category chips */
.categoryRow {
    display: flex;
    gap: 8px;
    overflow-x: auto;
    scrollbar-width: none;
    margin-bottom: 20px;
    padding-bottom: 2px;
}

.categoryRow::-webkit-scrollbar {
    display: none;
}

.categoryChip {
    display: flex;
    align-items: center;
    white-space: nowrap;
    padding: 7px 16px;
    border-radius: 999px;
    background: var(--alice-blue, #E3F2FD);
    color: var(--ocean-deep, #1565C0);
    border: 1px solid transparent;
    font-size: 0.83rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;
    flex-shrink: 0;
}

.categoryChip:hover {
    background: var(--light-ice-blue);
    border-color: var(--sky-blue);
}

.categoryChipActive {
    background: var(--dodger-blue, #2196F3) !important;
    color: white !important;
    box-shadow: 0 2px 8px rgba(33, 150, 243, 0.35);
}

/* Results header */
.resultsHdr {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 16px;
}

.resultsCount {
    font-size: 0.9rem;
    color: var(--medium-grey);
}

.resultsCount strong {
    color: var(--cobalt-blue);
}

.aiPill {
    display: flex;
    align-items: center;
    gap: 5px;
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--primary-blue);
    background: var(--alice-blue);
    border: 1px solid rgba(0, 123, 255, 0.2);
    padding: 4px 12px;
    border-radius: 999px;
}

/* ─── Job Cards ────────────────────────────────────────────────────────────────── */
.jobGrid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 20px;
}

.jobCard {
    background: white;
    border-radius: 14px;
    border: 1px solid var(--sky-blue, #90CAF9);
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 14px;
    transition: transform 0.22s ease, box-shadow 0.22s ease;
    cursor: pointer;
}

.jobCard:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 40px rgba(0, 0, 0, 0.10);
    border-color: rgba(255, 255, 255, 0.8);
}

.cardTop {
    display: flex;
    align-items: flex-start;
    gap: 12px;
}

.jobLogo {
    width: 44px;
    height: 44px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-weight: 700;
    font-size: 0.85rem;
    flex-shrink: 0;
}

.jobInfo {
    flex: 1;
    min-width: 0;
}

.jobTitle {
    font-size: 1rem;
    font-weight: 700;
    color: var(--cobalt-blue, #0D47A1);
    margin-bottom: 4px;
    transition: text-decoration 0.15s;
}

.jobCard:hover .jobTitle {
    text-decoration: underline;
}

.jobMeta {
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 0.82rem;
    color: var(--medium-grey, #475569);
    flex-wrap: wrap;
}

.metaDot {
    opacity: 0.4;
}

/* Save button */
.saveBtn {
    background: none;
    border: none;
    cursor: pointer;
    color: var(--sky-blue, #90CAF9);
    padding: 6px;
    border-radius: 8px;
    line-height: 0;
    transition: all 0.2s ease;
    flex-shrink: 0;
}

.saveBtn:hover {
    color: var(--primary-blue);
    background: var(--alice-blue);
}

.saveBtnActive {
    color: var(--primary-blue) !important;
    animation: pulse 0.35s ease;
}

@keyframes pulse {
    0% {
        transform: scale(1);
    }

    50% {
        transform: scale(1.3);
    }

    100% {
        transform: scale(1);
    }
}

/* Badge row */
.badgeRow {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

.typeBadge {
    font-size: 0.72rem;
    font-weight: 700;
    padding: 3px 10px;
    border-radius: 999px;
    color: white;
    background: var(--dodger-blue, #2196F3);
}

.type_Remote {
    background: var(--cool-sky-2, #42A5F5);
}

.type_PartTime {
    background: var(--brilliant-azure, #1E88E5);
}

.type_Contract {
    background: #7C3AED;
}

.type_Internship {
    background: #059669;
}

.salaryBadge {
    font-size: 0.72rem;
    font-weight: 700;
    padding: 3px 10px;
    border-radius: 999px;
    background: var(--alice-blue, #E3F2FD);
    color: var(--ocean-deep, #1565C0);
}

.countryBadge {
    font-size: 0.72rem;
    font-weight: 700;
    padding: 3px 10px;
    border-radius: 999px;
    background: linear-gradient(135deg, #f0fdf4, #ecfdf5);
    color: #065f46;
    border: 1px solid rgba(16, 185, 129, 0.15);
    display: flex;
    align-items: center;
    gap: 3px;
}

.matchBadge {
    font-size: 0.72rem;
    font-weight: 700;
    padding: 3px 10px;
    border-radius: 999px;
    background: rgba(0, 123, 255, 0.08);
    display: flex;
    align-items: center;
    gap: 4px;
}

/* Card footer */
.cardFooter {
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-top: 1px solid var(--sky-blue, #90CAF9);
    padding-top: 12px;
    margin-top: auto;
}

.postedMeta {
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 0.78rem;
    color: var(--medium-grey);
}

.cardActions {
    display: flex;
    gap: 8px;
    align-items: center;
}

.applyBtn {
    background: var(--primary-blue, #007BFF);
    color: white;
    border: none;
    padding: 7px 16px;
    border-radius: 8px;
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
}

.applyBtn:hover {
    background: #0069d9;
    box-shadow: 0 4px 12px rgba(0, 123, 255, 0.35);
}

.viewBtn {
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 0.82rem;
    font-weight: 600;
    color: var(--ocean-deep, #1565C0);
    text-decoration: none;
    transition: color 0.15s;
}

.viewBtn:hover {
    color: var(--primary-blue);
}

/* ─── Empty State ─────────────────────────────────────────────────────────────── */
.emptyState {
    text-align: center;
    padding: 64px 24px;
    background: white;
    border-radius: 16px;
    border: 1px solid var(--sky-blue);
}

.emptyIco {
    margin-bottom: 16px;
}

.emptyTitle {
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--cobalt-blue);
    margin: 0 0 6px;
}

.emptyDesc {
    font-size: 0.95rem;
    color: var(--medium-grey);
    margin: 0 0 16px;
}

.emptyLink {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: var(--primary-blue);
    font-weight: 600;
    text-decoration: underline;
    font-size: 0.95rem;
}

/* ─── Pagination ───────────────────────────────────────────────────────────────── */
.pagination {
    display: flex;
    justify-content: center;
    gap: 8px;
    margin-top: 40px;
}

.pageBtn {
    width: 38px;
    height: 38px;
    border-radius: 8px;
    border: 1px solid var(--sky-blue);
    background: var(--alice-blue);
    color: var(--ocean-deep);
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s ease;
}

.pageBtn:hover {
    background: var(--light-ice-blue);
    border-color: var(--primary-blue);
}

.pageBtnActive {
    background: var(--primary-blue) !important;
    color: white !important;
    border-color: var(--primary-blue) !important;
    box-shadow: 0 2px 8px rgba(0, 123, 255, 0.3);
}

/* ─── Responsive ────────────────────────────────────────────────────────────────── */
@media (max-width: 1024px) {
    .sidebar {
        position: fixed;
        left: 0;
        top: 0;
        bottom: 0;
        z-index: 910;
        transform: translateX(-100%);
        transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
        border-radius: 0 16px 16px 0;
        overflow-y: auto;
        width: 280px;
        min-width: 280px;
    }

    .sidebarOpen {
        transform: translateX(0);
    }

    .sidebarClose {
        display: flex;
    }

    .mobileFilterBtn {
        display: flex;
    }
}

@media (max-width: 640px) {
    .hero {
        padding: 40px 0 32px;
    }

    .searchCard {
        flex-direction: column;
        border-radius: 12px;
    }

    .searchField {
        width: 100%;
    }

    .searchDivider {
        width: 100%;
        height: 1px;
    }

    .searchBtn {
        width: 100%;
        justify-content: center;
    }

    .jobGrid {
        grid-template-columns: 1fr;
    }
}

"use client";
// UNIQUE_TAG: REAL_BLOG_PAGE_FIX_V1
import React, { useState, useEffect } from 'react';
import Image from 'next/image';
import Link from 'next/link';
import styles from './blog.module.css';
import { insforge } from '@/lib/insforge';
import AnimateOnScroll from '@/components/AnimateOnScroll';

const IconSparkle = () => (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor" stroke="none">
        <path d="m12 3 1.912 5.885L20 10.8l-5.088 1.912L13 18.6l-1.912-5.888L6 10.8l5.088-1.915L12 3Z" />
    </svg>
);
const IconArrowRight = () => (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
        <path d="M5 12h14m-7-7 7 7-7 7" />
    </svg>
);

const CATEGORIES = ["All", "Technology", "Culture", "Career Advice", "Engineering", "Product"];

export default function BlogPage() {
    const [posts, setPosts] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [activeCategory, setActiveCategory] = useState("All");
    const [search, setSearch] = useState("");

    useEffect(() => {
        async function fetchPosts() {
            try {
                const { data } = await insforge.database
                    .from('blog')
                    .select('*')
                    .eq('status', 'published')
                    .order('created_at', { ascending: false });
                setPosts(data || []);
            } catch (err) {
                console.error('Fetch posts error:', err);
            } finally {
                setLoading(false);
            }
        }
        fetchPosts();
    }, []);

    const filtered = posts.filter(p => {
        const matchesCat = activeCategory === "All" || p.category === activeCategory;
        const matchesSearch = p.title.toLowerCase().includes(search.toLowerCase()) ||
            p.excerpt?.toLowerCase().includes(search.toLowerCase());
        return matchesCat && matchesSearch;
    });

    const featuredPost = filtered[0];
    const displayPosts = filtered.slice(1);

    if (loading) return (
        <div style={{ height: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#fff' }}>
            <div style={{ width: 40, height: 40, border: '4px solid #f3f3f3', borderTopColor: '#007BFF', borderRadius: '50%', animation: 'spin 1s linear infinite' }} />
            <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
        </div>
    );

    return (
        <main style={{ background: '#fff' }}>
            {/* 1. Hero */}
            <section className={styles.hero}>
                <div className="premium-container">
                    <div className={styles.heroContent}>
                        <div className={styles.badge}>
                            <IconSparkle /> Updated Daily • 12.4k Readers
                        </div>
                        <h1 className={styles.title}>
                            Insights &{' '}
                            <span className={styles.highlight}>perspectives.</span>
                        </h1>
                        <p className={styles.description}>
                            The latest thinking on AI, hiring, and the future of work — from the TalentMesh team and industry leaders.
                        </p>
                        <div className={styles.searchBar}>
                            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,0.5)" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                <circle cx="11" cy="11" r="8" /><path d="m21 21-4.3-4.3" />
                            </svg>
                            <input
                                type="text"
                                placeholder="Search articles..."
                                value={search}
                                onChange={e => setSearch(e.target.value)}
                            />
                            <button className={styles.searchBtn}>Search</button>
                        </div>
                    </div>
                </div>
            </section>

            {/* 2. Featured Post */}
            {featuredPost && (
                <AnimateOnScroll animation="fadeUp">
                    <section className={styles.featuredSection}>
                        <div className="premium-container">
                            <div className={styles.featuredCard}>
                                <div className={styles.featuredBanner}>
                                    <Image
                                        src={featuredPost.cover_image || "/images/tech-office.jpg"}
                                        alt={featuredPost.title}
                                        fill
                                        className={styles.featuredImg}
                                        style={{ objectFit: 'cover' }}
                                    />
                                </div>
                                <div className={styles.featuredBody}>
                                    <span className={styles.featuredCategory}>⭐ Featured • {featuredPost.category}</span>
                                    <div className={styles.featuredDate}>{new Date(featuredPost.created_at).toLocaleDateString()}</div>
                                    <h2 className={styles.featuredTitle}>{featuredPost.title}</h2>
                                    <p className={styles.featuredDesc}>{featuredPost.excerpt}</p>
                                    <Link href={`/blog/${featuredPost.slug}`} className={styles.readMoreBtn}>
                                        Read Article <IconArrowRight />
                                    </Link>
                                </div>
                            </div>
                        </div>
                    </section>
                </AnimateOnScroll>
            )}

            {/* 3. Articles Grid */}
            <AnimateOnScroll animation="fadeUp" delay={100}>
                <section className={styles.articlesSection}>
                    <div className="premium-container">
                        <div className={styles.categoryRow}>
                            {CATEGORIES.map(cat => (
                                <button
                                    key={cat}
                                    className={`${styles.chip} ${activeCategory === cat ? styles.chipActive : ''}`}
                                    onClick={() => setActiveCategory(cat)}
                                >
                                    {cat}
                                </button>
                            ))}
                        </div>

                        {displayPosts.length > 0 ? (
                            <div className={styles.articlesGrid}>
                                {displayPosts.map((post, i) => (
                                    <div key={post.id} className={styles.articleCard}>
                                        <div className={styles.cardBanner}>
                                            <Image
                                                src={post.cover_image || "/images/tech-office.jpg"}
                                                alt={post.title}
                                                fill
                                                className={styles.cardImg}
                                                style={{ objectFit: 'cover' }}
                                            />
                                            <span className={styles.catTag}>{post.category}</span>
                                        </div>
                                        <div className={styles.cardBody}>
                                            <div className={styles.cardDate}>{new Date(post.created_at).toLocaleDateString()}</div>
                                            <h3 className={styles.cardTitle}>{post.title}</h3>
                                            <p className={styles.cardDesc}>{post.excerpt}</p>
                                            <Link href={`/blog/${post.slug}`} className={styles.readLink}>
                                                Read Article <IconArrowRight />
                                            </Link>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : !featuredPost && (
                            <div style={{ textAlign: 'center', padding: '4rem 0', color: 'var(--medium-grey)' }}>
                                <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>🔍</div>
                                <p style={{ fontSize: '1.1rem' }}>No articles found. Try a different search or category.</p>
                            </div>
                        )}
                    </div>
                </section>
            </AnimateOnScroll>

            {/* 4. Newsletter */}
            <AnimateOnScroll animation="scaleUp">
                <section className={styles.newsletterSection}>
                    <div className="premium-container">
                        <div className={styles.newsletterCard}>
                            <h2>Never miss an update.</h2>
                            <p>
                                Get the latest insights on AI recruitment and talent strategy delivered straight to your inbox every week.
                            </p>
                            <div className={styles.emailForm}>
                                <input
                                    type="email"
                                    placeholder="Enter your email address"
                                    className={styles.emailInput}
                                />
                                <button className={styles.subscribeBtn}>Subscribe</button>
                            </div>
                        </div>
                    </div>
                </section>
            </AnimateOnScroll>
        </main>
    );
}

/* ── Blog Page ── */

/* Hero */
.hero {
    background: var(--deep-navy);
    padding: 10rem 0 8rem;
    position: relative;
    overflow: hidden;
}

.hero::before {
    content: '';
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse 70% 60% at 70% -10%, rgba(0, 123, 255, 0.2) 0%, transparent 65%);
}

.heroContent {
    position: relative;
    max-width: 720px;
}

.badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: rgba(0, 123, 255, 0.15);
    border: 1px solid rgba(0, 123, 255, 0.3);
    color: #60a5fa;
    padding: 8px 18px;
    border-radius: 50px;
    font-size: 0.82rem;
    font-weight: 700;
    letter-spacing: 0.02em;
    margin-bottom: 2.5rem;
}

.title {
    font-size: clamp(2.8rem, 5.5vw, 5rem);
    font-weight: 900;
    color: #fff;
    letter-spacing: -0.04em;
    line-height: 1.05;
    margin-bottom: 1.5rem;
}

.highlight {
    background: linear-gradient(135deg, #007BFF, #60a5fa);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.description {
    font-size: 1.2rem;
    color: rgba(255, 255, 255, 0.6);
    line-height: 1.75;
    max-width: 560px;
    margin-bottom: 3rem;
}

/* Search */
.searchBar {
    display: flex;
    align-items: center;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 16px;
    padding: 0.5rem 0.5rem 0.5rem 1.5rem;
    max-width: 520px;
    gap: 1rem;
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    backdrop-filter: blur(12px);
}

.searchBar:focus-within {
    border-color: rgba(0, 123, 255, 0.5);
    box-shadow: 0 0 0 4px rgba(0, 123, 255, 0.15), 0 8px 24px rgba(0, 0, 0, 0.2);
    background: rgba(255, 255, 255, 0.1);
}

.searchBar input {
    flex: 1;
    background: transparent;
    border: none;
    outline: none;
    color: #fff;
    font-size: 1rem;
}

.searchBar input::placeholder {
    color: rgba(255, 255, 255, 0.4);
}

.searchBtn {
    background: #007BFF;
    color: #fff;
    border: none;
    padding: 0.75rem 1.75rem;
    border-radius: 12px;
    font-weight: 800;
    font-size: 0.9rem;
    cursor: pointer;
    transition: all 0.3s ease;
    white-space: nowrap;
}

.searchBtn:hover {
    background: #0066d6;
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(0, 123, 255, 0.4);
}

/* Category chips */
.categoryRow {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
    margin-bottom: 3.5rem;
}

.chip {
    padding: 0.5rem 1.25rem;
    border-radius: 50px;
    border: 1px solid #e2e8f0;
    background: #fff;
    color: var(--deep-navy);
    font-weight: 700;
    font-size: 0.85rem;
    cursor: pointer;
    transition: all 0.2s;
}

.chip:hover {
    border-color: var(--primary-blue);
    color: var(--primary-blue);
}

.chipActive {
    background: var(--primary-blue);
    color: #fff;
    border-color: var(--primary-blue);
}

/* Featured Post */
.featuredSection {
    padding: 8rem 0 0;
}

.featuredCard {
    display: grid;
    grid-template-columns: 1fr 1fr;
    border-radius: var(--radius-lg);
    overflow: hidden;
    border: 1px solid #e2e8f0;
    margin-bottom: 1.5rem;
    transition: all 0.4s ease;
}

.featuredCard:hover {
    box-shadow: 0 24px 60px rgba(0, 0, 0, 0.08);
    border-color: rgba(0, 123, 255, 0.15);
}

.featuredBanner {
    min-height: 340px;
    background: #0f172a;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
}

.featuredImg {
    object-fit: cover;
    opacity: 0.6;
    transition: transform 0.8s ease;
}

.featuredCard:hover .featuredImg {
    transform: scale(1.05);
}

.featuredBanner::after {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: linear-gradient(45deg, transparent 30%, rgba(255, 255, 255, 0.05) 50%, transparent 70%);
    animation: shimmer 6s ease-in-out infinite;
}

@keyframes shimmer {
    0% {
        transform: translateX(-100%) translateY(-100%);
    }

    100% {
        transform: translateX(100%) translateY(100%);
    }
}

.featuredBody {
    padding: 3.5rem;
    display: flex;
    flex-direction: column;
    justify-content: center;
    background: #f8fafc;
}

.featuredCategory {
    display: inline-block;
    background: rgba(0, 123, 255, 0.1);
    color: var(--primary-blue);
    font-size: 0.75rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    padding: 4px 12px;
    border-radius: 50px;
    margin-bottom: 1.25rem;
    width: fit-content;
}

.featuredTitle {
    font-size: 1.85rem;
    font-weight: 900;
    color: var(--deep-navy);
    letter-spacing: -0.03em;
    line-height: 1.25;
    margin-bottom: 1rem;
}

.featuredDesc {
    font-size: 1rem;
    color: var(--medium-grey);
    line-height: 1.7;
    margin-bottom: 2rem;
}

.featuredDate {
    font-size: 0.8rem;
    color: var(--medium-grey);
    margin-bottom: 1.5rem;
}

.readMoreBtn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: var(--primary-blue);
    font-weight: 800;
    font-size: 0.9rem;
    text-decoration: none;
    transition: gap 0.2s;
}

.readMoreBtn:hover {
    gap: 12px;
}

/* Articles Grid */
.articlesSection {
    padding: 5rem 0 4rem;
}

.articlesGrid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
}

.articleCard {
    background: #fff;
    border: 1px solid #e2e8f0;
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    position: relative;
}

.articleCard::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: linear-gradient(90deg, #007BFF, #60a5fa, #818cf8);
    transform: scaleX(0);
    transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    transform-origin: left;
}

.articleCard:hover {
    transform: translateY(-8px);
    box-shadow: 0 24px 60px rgba(0, 0, 0, 0.1);
    border-color: rgba(0, 123, 255, 0.15);
}

.articleCard:hover::after {
    transform: scaleX(1);
}

.cardBanner {
    height: 180px;
    position: relative;
    display: flex;
    align-items: flex-end;
    padding: 1.25rem;
    background: #0f172a;
    overflow: hidden;
}

.cardImg {
    object-fit: cover;
    opacity: 0.5;
    transition: transform 0.6s ease;
}

.articleCard:hover .cardImg {
    transform: scale(1.1);
}

.cardBannerEmoji {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3.5rem;
    opacity: 0.5;
}

.catTag {
    position: relative;
    z-index: 1;
    background: rgba(255, 255, 255, 0.18);
    backdrop-filter: blur(8px);
    color: #fff;
    font-size: 0.72rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    padding: 4px 12px;
    border-radius: 50px;
    border: 1px solid rgba(255, 255, 255, 0.3);
}

.cardBody {
    padding: 1.75rem;
}

.cardDate {
    font-size: 0.78rem;
    color: var(--medium-grey);
    margin-bottom: 0.75rem;
}

.cardTitle {
    font-size: 1.1rem;
    font-weight: 800;
    color: var(--deep-navy);
    line-height: 1.35;
    margin-bottom: 0.75rem;
}

.cardDesc {
    font-size: 0.875rem;
    color: var(--medium-grey);
    line-height: 1.65;
    margin-bottom: 1.5rem;
}

.readLink {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: var(--primary-blue);
    font-weight: 800;
    font-size: 0.85rem;
    text-decoration: none;
    transition: gap 0.2s;
}

.readLink:hover {
    gap: 10px;
}

/* Newsletter */
.newsletterSection {
    padding: 4rem 0 8rem;
}

.newsletterCard {
    background: var(--gradient-premium);
    border-radius: 40px;
    padding: 6rem 4rem;
    text-align: center;
    color: #fff;
}

.newsletterCard h2 {
    font-size: clamp(2rem, 3.5vw, 3rem);
    font-weight: 900;
    margin-bottom: 1rem;
}

.newsletterCard p {
    opacity: 0.75;
    font-size: 1.1rem;
    max-width: 500px;
    margin: 0 auto 3rem;
    line-height: 1.7;
}

.emailForm {
    display: flex;
    gap: 0.75rem;
    max-width: 500px;
    margin: 0 auto;
}

.emailInput {
    flex: 1;
    padding: 1rem 1.5rem;
    border-radius: 14px;
    border: none;
    background: rgba(255, 255, 255, 0.15);
    color: #fff;
    font-size: 0.95rem;
    outline: none;
    backdrop-filter: blur(10px);
}

.emailInput::placeholder {
    color: rgba(255, 255, 255, 0.5);
}

.subscribeBtn {
    background: #fff;
    color: var(--primary-blue);
    border: none;
    padding: 1rem 2rem;
    border-radius: 14px;
    font-weight: 800;
    font-size: 0.95rem;
    cursor: pointer;
    white-space: nowrap;
    transition: transform 0.2s;
}

.subscribeBtn:hover {
    transform: translateY(-2px);
}

/* Responsive */
@media (max-width: 1024px) {
    .articlesGrid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 768px) {
    .hero {
        padding: 7rem 0 5rem;
    }

    .featuredCard {
        grid-template-columns: 1fr;
    }

    .featuredBanner {
        min-height: 200px;
    }

    .articlesGrid {
        grid-template-columns: 1fr;
    }

    .newsletterCard {
        padding: 4rem 2rem;
        border-radius: 24px;
    }

    .emailForm {
        flex-direction: column;
    }
}

/* ============================
   ABOUT PAGE — TalentMesh
   Premium Architectural Edition
   ============================ */

.page {
    min-height: 100vh;
    background: #ffffff;
    font-family: var(--font-inter, 'Inter', sans-serif);
    color: #0f172a;
}

/* ── Stats Strip ── */
.statsStrip {
    background: linear-gradient(135deg, #0a0f1e 0%, #0d1b3e 50%, #081428 100%);
    padding: 5rem 2rem;
    color: #ffffff;
    position: relative;
    overflow: hidden;
}

.statsStrip::before {
    content: '';
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse 60% 100% at 50% 50%, rgba(0, 123, 255, 0.08) 0%, transparent 70%);
}

.statsGrid {
    max-width: 1200px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 2rem;
    position: relative;
}

.statItem {
    text-align: center;
    padding: 2rem 1rem;
    border-radius: 20px;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.06);
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.statItem:hover {
    background: rgba(255, 255, 255, 0.08);
    border-color: rgba(0, 123, 255, 0.3);
    transform: translateY(-4px);
    box-shadow: 0 8px 30px rgba(0, 123, 255, 0.15);
}

.statNum {
    font-size: 3rem;
    font-weight: 900;
    display: block;
    margin-bottom: 0.75rem;
    font-variant-numeric: tabular-nums;
    background: linear-gradient(135deg, #60a5fa, #3b82f6);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    text-shadow: none;
}

.statLabel {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: rgba(255, 255, 255, 0.45);
    font-weight: 700;
}

/* ── Our Story (Split Layout) ── */
.storySection {
    padding: 8rem 2rem;
    max-width: 1200px;
    margin: 0 auto;
}

.storyGrid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 6rem;
    align-items: center;
}

.storyTag {
    color: #3b82f6;
    font-weight: 800;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 1.25rem;
    padding: 0.4rem 1rem;
    background: rgba(59, 130, 246, 0.08);
    border-radius: 50px;
    border: 1px solid rgba(59, 130, 246, 0.15);
}

.storyTitle {
    font-size: 2.5rem;
    font-weight: 900;
    margin-bottom: 1.5rem;
    letter-spacing: -0.03em;
    line-height: 1.1;
}

.storyText {
    font-size: 1.05rem;
    line-height: 1.8;
    color: #475569;
    margin-bottom: 1.5rem;
}

/* ── Mission Cards ── */
.missionVisual {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.missionImageWrapper {
    position: relative;
    width: 100%;
    aspect-ratio: 16/9;
    border-radius: 24px;
    overflow: hidden;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.1);
    margin-top: 2rem;
}

.missionImg {
    object-fit: cover;
    transition: transform 0.6s ease;
}

.missionImageWrapper:hover .missionImg {
    transform: scale(1.03);
}

.missionCard {
    padding: 2rem;
    border-radius: 20px;
    border: 1px solid rgba(0, 0, 0, 0.06);
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    position: relative;
    overflow: hidden;
}

.missionCard::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 4px;
    height: 100%;
    border-radius: 0 4px 4px 0;
    transition: all 0.4s ease;
}

.missionCardProblem {
    background: linear-gradient(135deg, #fef2f2 0%, #fff1f2 100%);
    box-shadow: 0 4px 20px rgba(239, 68, 68, 0.06);
}

.missionCardProblem::before {
    background: linear-gradient(to bottom, #ef4444, #f97316);
}

.missionCardProblem:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 30px rgba(239, 68, 68, 0.12);
}

.missionCardSolution {
    background: linear-gradient(135deg, #f0fdf4 0%, #ecfdf5 100%);
    box-shadow: 0 4px 20px rgba(16, 185, 129, 0.06);
}

.missionCardSolution::before {
    background: linear-gradient(to bottom, #10b981, #059669);
}

.missionCardSolution:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 30px rgba(16, 185, 129, 0.12);
}

.missionCardTitle {
    font-size: 1rem;
    font-weight: 800;
    margin-bottom: 0.5rem;
    display: flex;
    align-items: center;
    gap: 8px;
}

.missionCardTitleProblem {
    color: #dc2626;
}

.missionCardTitleSolution {
    color: #059669;
}

.missionCardText {
    font-size: 0.92rem;
    color: #475569;
    line-height: 1.6;
}

.missionCardTextSolution {
    color: #0f172a;
    font-weight: 600;
}

/* ── Innovation Labs Visual ── */
.labsVisual {
    background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
    border-radius: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 4rem;
    min-height: 300px;
    position: relative;
    overflow: hidden;
}

.labsVisual::before {
    content: '';
    position: absolute;
    width: 200px;
    height: 200px;
    background: radial-gradient(circle, rgba(59, 130, 246, 0.3) 0%, transparent 70%);
    border-radius: 50%;
    animation: labsPulse 4s ease-in-out infinite;
}

.labsVisual::after {
    content: '';
    position: absolute;
    width: 300px;
    height: 300px;
    background: radial-gradient(circle, rgba(129, 140, 248, 0.15) 0%, transparent 70%);
    border-radius: 50%;
    animation: labsPulse 4s ease-in-out infinite reverse;
}

.labsIcon {
    position: relative;
    z-index: 2;
    color: #60a5fa;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1rem;
}

.labsIconSvg {
    width: 64px;
    height: 64px;
    color: #60a5fa;
    filter: drop-shadow(0 0 20px rgba(96, 165, 250, 0.4));
}

.labsIconLabel {
    font-size: 0.82rem;
    font-weight: 800;
    color: rgba(255, 255, 255, 0.5);
    text-transform: uppercase;
    letter-spacing: 0.15em;
}

@keyframes labsPulse {

    0%,
    100% {
        transform: scale(1);
        opacity: 0.6;
    }

    50% {
        transform: scale(1.3);
        opacity: 1;
    }
}

/* ── Innovation bullet list ── */
.innovationList {
    list-style: none;
    padding: 0;
    margin-top: 2rem;
}

.innovationItem {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 1.25rem;
    font-weight: 600;
    color: #0f172a;
    padding: 0.6rem 0;
    transition: transform 0.2s ease;
}

.innovationItem:hover {
    transform: translateX(4px);
}

.innovationDot {
    width: 10px;
    height: 10px;
    background: linear-gradient(135deg, #3b82f6, #60a5fa);
    border-radius: 50%;
    flex-shrink: 0;
    box-shadow: 0 0 8px rgba(59, 130, 246, 0.4);
}

/* ── Global section stats ── */
.globalStatValue {
    font-size: 2.75rem;
    font-weight: 900;
    margin-bottom: 0.5rem;
    background: linear-gradient(135deg, #60a5fa, #818cf8);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
}

.globalStatLabel {
    font-weight: 600;
    opacity: 0.5;
    font-size: 0.88rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

/* ── Responsive ── */
@media (max-width: 1024px) {
    .storyGrid {
        grid-template-columns: 1fr;
        gap: 4rem;
    }

    .statsGrid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 640px) {
    .statsGrid {
        grid-template-columns: 1fr;
    }

    .storyTitle {
        font-size: 2rem;
    }

    .statNum {
        font-size: 2.5rem;
    }
}

import type { Metadata } from "next";
