}

.cardTitle {
    font-size: 1.25rem;
    font-weight: 800;
    color: var(--deep-navy);
    margin-bottom: 1rem;
}

.cardDesc {
    font-size: 1rem;
    color: var(--medium-grey);
    line-height: 1.6;
}

@media (max-width: 1024px) {
    .grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 640px) {
    .grid {
        grid-template-columns: 1fr;
    }
}

"use client";
import React from 'react';
import LayersOutlinedIcon from '@mui/icons-material/LayersOutlined';
import RocketLaunchOutlinedIcon from '@mui/icons-material/RocketLaunchOutlined';
import VerifiedUserOutlinedIcon from '@mui/icons-material/VerifiedUserOutlined';
import BoltOutlinedIcon from '@mui/icons-material/BoltOutlined';
import styles from './PremiumCardGrid.module.css';

interface CardProps {
    icon: React.ReactNode;
    title: string;
    desc: string;
}

const PremiumCardGrid = ({ items }: { items?: CardProps[] }) => {
    const defaultItems = [
        { icon: <BoltOutlinedIcon sx={{ fontSize: 28 }} />, title: "Instant Sourcing", desc: "Our AI agents source candidates in real-time as you type your requirements." },
        { icon: <VerifiedUserOutlinedIcon sx={{ fontSize: 28 }} />, title: "Verified Skills", desc: "Every portfolio and resume is cross-verified for technical accuracy." },
        { icon: <LayersOutlinedIcon sx={{ fontSize: 28 }} />, title: "Built-in ATS", desc: "A full-featured tracking system that works as fast as your team does." },
        { icon: <RocketLaunchOutlinedIcon sx={{ fontSize: 28 }} />, title: "Scalable Infrastructure", desc: "Handle 1 or 1,000 openings without any loss in performance." }
    ];

    const displayItems = items || defaultItems;

    return (
        <section className={styles.section}>
            <div className="premium-container">
                <div className={styles.grid}>
                    {displayItems.map((item, i) => (
                        <div key={i} className={styles.card}>
                            <div className={styles.iconWrap}>{item.icon}</div>
                            <h3 className={styles.title}>{item.title}</h3>
                            <p className={styles.desc}>{item.desc}</p>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    );
};

export default PremiumCardGrid;

.section {
    padding: 4rem 0;
}

.grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 2rem;
}

.card {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    padding: 3rem;
    border-radius: var(--radius-lg);
    transition: var(--transition-smooth);
    position: relative;
    overflow: hidden;
}

.card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 4px;
    background: var(--gradient-primary);
    transform: scaleX(0);
    transform-origin: left;
    transition: transform 0.4s ease;
}

.card:hover {
    transform: translateY(-8px);
    box-shadow: var(--shadow-xl);
    border-color: var(--primary-blue);
}

.card:hover::before {
    transform: scaleX(1);
}

.iconWrap {
    width: 64px;
    height: 64px;
    background: var(--light-ice-blue);
    color: var(--primary-blue);
    border-radius: 16px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    transition: var(--transition-smooth);
}

.card:hover .iconWrap {
    transform: rotateY(180deg);
}

.title {
    font-size: 1.5rem;
    font-weight: 800;
    color: var(--deep-navy);
    margin-bottom: 1rem;
}

.desc {
    font-size: 1rem;
    color: var(--medium-grey);
    line-height: 1.6;
}

"use client";
import React from 'react';
import styles from './PageHeader.module.css';

interface PageHeaderProps {
    title: string;
    description: string;
    breadcrumb?: string;
    highlight?: string;
}

const PageHeader: React.FC<PageHeaderProps> = ({ title, description, breadcrumb, highlight }) => {
    return (
        <section className={styles.header}>
            <div className={styles.container}>
                {breadcrumb && <span className={styles.breadcrumb}>{breadcrumb}</span>}
                <h1 className={styles.title}>
                    {title} {highlight && <span className={styles.highlight}>{highlight}</span>}
                </h1>
                <p className={styles.description}>{description}</p>
            </div>
            <div className={styles.decor1}></div>
            <div className={styles.decor2}></div>
        </section>
    );
};

export default PageHeader;

.header {
    background: linear-gradient(135deg, #0a0f1e 0%, #0d1b3e 40%, #0f2044 70%, #081428 100%);
    padding: 11rem 2rem 7rem;
    position: relative;
    overflow: hidden;
    text-align: center;
}

/* Animated grid-line overlay */
.header::before {
    content: '';
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
    background-size: 60px 60px;
    z-index: 1;
}

/* Gradient glow overlay */
.header::after {
    content: '';
    position: absolute;
    inset: 0;
    background:
        radial-gradient(ellipse 50% 80% at 20% 100%, rgba(0, 123, 255, 0.15) 0%, transparent 50%),
        radial-gradient(ellipse 50% 60% at 80% 0%, rgba(96, 165, 250, 0.12) 0%, transparent 50%);
    z-index: 2;
}

.container {
    max-width: 900px;
    margin: 0 auto;
    position: relative;
    z-index: 10;
}

.breadcrumb {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 0.5rem 1.5rem;
    background: rgba(255, 255, 255, 0.06);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    color: #60a5fa;
    border-radius: 9999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-bottom: 2.5rem;
    border: 1px solid rgba(255, 255, 255, 0.1);
    text-transform: uppercase;
    letter-spacing: 0.08em;
}

.title {
    font-size: clamp(2.5rem, 8vw, 4.5rem);
    font-weight: 900;
    color: #ffffff;
    line-height: 1.1;
    margin-bottom: 2rem;
    letter-spacing: -0.03em;
}

.highlight {
    background: linear-gradient(135deg, #60a5fa, #3b82f6, #818cf8);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
}

.description {
    font-size: clamp(1.125rem, 2vw, 1.35rem);
    color: rgba(255, 255, 255, 0.55);
    line-height: 1.65;
    max-width: 700px;
    margin: 0 auto;
}

/* Floating orb 1 */
.decor1 {
    position: absolute;
    top: -15%;
    right: -8%;
    width: 500px;
    height: 500px;
    background: radial-gradient(circle, rgba(0, 123, 255, 0.18) 0%, rgba(0, 123, 255, 0.05) 40%, transparent 70%);
    border-radius: 50%;
    z-index: 3;
    animation: floatOrb1 8s ease-in-out infinite;
    filter: blur(20px);
}

/* Floating orb 2 */
.decor2 {
    position: absolute;
    bottom: -20%;
    left: -8%;
    width: 400px;
    height: 400px;
    background: radial-gradient(circle, rgba(129, 140, 248, 0.15) 0%, rgba(129, 140, 248, 0.04) 40%, transparent 70%);
    border-radius: 50%;
    z-index: 3;
    animation: floatOrb2 10s ease-in-out infinite;
    filter: blur(20px);
}

@keyframes floatOrb1 {

    0%,
    100% {
        transform: translate(0, 0) scale(1);
    }

    50% {
        transform: translate(-30px, 20px) scale(1.05);
    }
}

@keyframes floatOrb2 {

    0%,
    100% {
        transform: translate(0, 0) scale(1);
    }

    50% {
        transform: translate(20px, -30px) scale(1.08);
    }
}

@media (max-width: 768px) {
    .header {
        padding: 8rem 1.5rem 5rem;
    }

    .decor1,
    .decor2 {
        width: 250px;
        height: 250px;
    }
}

"use client";
import React from 'react';
import styles from './Marquee.module.css';

const LOGOS = [
    "Google", "Microsoft", "Meta", "Amazon", "Netflix", "Tesla", "SpaceX", "Airbnb", "Stripe", "Uber"
];

const Marquee = () => {
    return (
        <div className={styles.wrapper}>
            <div className={styles.scroll}>
                {[...LOGOS, ...LOGOS].map((logo, i) => (
                    <div key={i} className={styles.logoItem}>
                        {logo}
                    </div>
                ))}
            </div>
        </div>
    );
};

export default Marquee;

.wrapper {
    overflow: hidden;
    padding: 3rem 0;
    background: #ffffff;
    user-select: none;
    position: relative;
    mask-image: linear-gradient(to right, transparent, black 15%, black 85%, transparent);
}

.scroll {
    display: flex;
    white-space: nowrap;
    width: fit-content;
    animation: scroll 30s linear infinite;
}

.logoItem {
    font-size: 2rem;
    font-weight: 800;
    color: #e2e8f0;
    margin: 0 4rem;
    letter-spacing: -0.05em;
    transition: color 0.3s ease;
    cursor: default;
}

.logoItem:hover {
    color: var(--primary-blue);
