const DEFAULTS = {
    name: "",
    company: "",
    email: "",
    phone: "",
    hiringVolume: "",
    timeline: "",
    notes: "",
};

export default function RPOPage() {
    const [form, setForm] = useState(DEFAULTS);
    const [errors, setErrors] = useState<Record<string, string>>({});
    const [submitted, setSubmitted] = useState(false);

    const set = (k: keyof typeof DEFAULTS, v: string) => {
        setForm(p => ({ ...p, [k]: v }));
        setErrors(p => ({ ...p, [k]: "" }));
    };

    const validate = () => {
        const e: Record<string, string> = {};
        if (!form.name.trim()) e.name = "Your name is required.";
        if (!form.company.trim()) e.company = "Company name is required.";
        if (!form.email.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) e.email = "A valid email is required.";
        return e;
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const errs = validate();
        if (Object.keys(errs).length > 0) { setErrors(errs); return; }
        setSubmitted(true);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    if (submitted) {
        return (
            <main className={styles.page}>
                <div className={styles.successScreen}>
                    <div className={styles.successIcon}><IconCheck /></div>
                    <h1 className={styles.successTitle}>Strategy Call Booked!</h1>
                    <p className={styles.successDesc}>
                        Thanks, <strong>{form.name}</strong>. An RPO specialist from TalentMesh will reach out to <strong>{form.email}</strong> within <strong>24 hours</strong> to schedule your strategy call.
                    </p>
                    <div className={styles.successDetails}>
                        <p><strong>Company:</strong> {form.company}</p>
                        {form.hiringVolume && <p><strong>Hiring volume:</strong> {form.hiringVolume}</p>}
                        {form.timeline && <p><strong>Timeline:</strong> {form.timeline}</p>}
                    </div>
                    <button className={styles.backBtn} onClick={() => { setSubmitted(false); setForm(DEFAULTS); }}>
                        Submit Another Enquiry
                    </button>
                </div>
            </main>
        );
    }

    return (
        <main className={styles.page}>

            {/* ─── HERO ───────────────────────────────────────────────────── */}
            <section className={styles.hero}>
                <div className={styles.heroGrid} aria-hidden="true" />
                <div className={styles.heroOrb1} aria-hidden="true" />
                <div className={styles.heroOrb2} aria-hidden="true" />
                <div className={`premium-container ${styles.heroInner}`}>
                    <div className={styles.heroBadge}><IconSparkle /> Enterprise RPO</div>
                    <h1 className={styles.heroTitle}>
                        Outsource Your Entire{" "}
                        <span className={styles.heroHighlight}>Hiring Function to Us.</span>
                    </h1>
                    <p className={styles.heroSub}>
                        TalentMesh RPO embeds seamlessly with your business to manage end-to-end recruitment — so your team can focus on building, not hiring.
                    </p>
                    <div className={styles.heroCtas}>
                        <button
                            className={styles.primaryCta}
                            onClick={() => document.getElementById('rpo-contact')?.scrollIntoView({ behavior: 'smooth' })}>
                            Talk to an RPO Specialist <IconArrow />
                        </button>
                        <div className={styles.ctaTrust}><IconCheck /> Specialist assigned within 24 hours</div>
                    </div>
                </div>
            </section>

            {/* ─── STATS STRIP ────────────────────────────────────────────── */}
            <div className={styles.statsStrip}>
                <div className="premium-container">
                    <div className={styles.statsRow}>
                        {STATS.map((s, i) => (
                            <div key={i} className={styles.statItem}>
                                <span className={styles.statValue}>{s.value}</span>
                                <span className={styles.statLabel}>{s.label}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* ─── WHAT IS RPO ─────────────────────────────────────────────── */}
            <section className={styles.explainerSection}>
                <div className="premium-container">
                    <div className={styles.explainerGrid}>
                        <div className={styles.explainerText}>
                            <div className={styles.sectionBadge}><IconSparkle /> What is RPO?</div>
                            <h2 className={styles.sectionTitle}>Your hiring function, fully managed.</h2>
                            <p className={styles.explainerBody}>
                                RPO (Recruitment Process Outsourcing) means handing over your recruiting to a specialist partner — not just a recruiter, but a whole function. We manage strategy, sourcing, screening, offers, and analytics.
                            </p>
                            <p className={styles.explainerBody}>
                                Unlike a staffing agency that sends you CVs, TalentMesh RPO works inside your business, uses your voice, and is accountable for outcomes — not just activity.
                            </p>
                            <ul className={styles.explainerPoints}>
                                <li><span className={styles.pointDot}><IconCheck /></span> No long-term lock-in — engagement models to suit your stage</li>
                                <li><span className={styles.pointDot}><IconCheck /></span> Cheaper than in-house when you need surge capacity</li>
                                <li><span className={styles.pointDot}><IconCheck /></span> All the expertise, none of the overhead</li>
                            </ul>
                        </div>
                        <div className={styles.explainerVisual}>
                            <div className={styles.flowDiagram}>
                                {["Hiring brief", "Sourcing strategy", "Screening & shortlist", "Interviews managed", "Offer & close", "Analytics report"].map((step, i) => (
                                    <React.Fragment key={step}>
                                        <div className={styles.flowStep}>
                                            <span className={styles.flowNum}>{String(i + 1).padStart(2, '0')}</span>
                                            <span className={styles.flowLabel}>{step}</span>
                                        </div>
                                        {i < 5 && <div className={styles.flowArrow}>↓</div>}
                                    </React.Fragment>
                                ))}
                            </div>
                            <div className={styles.flowOwner}>
                                <span className={styles.flowOwnerLabel}>All managed by TalentMesh RPO team</span>
                            </div>
                        </div>
                    </div>
                </div>
            </section>

            {/* ─── WHEN DOES RPO MAKE SENSE ────────────────────────────────── */}
            <section className={styles.whenSection}>
                <div className="premium-container">
                    <div className={styles.sectionHeader}>
                        <div className={styles.sectionBadge}><IconSparkle /> When Does RPO Make Sense?</div>
                        <h2 className={styles.sectionTitle}>Built for businesses that can't afford hiring bottlenecks</h2>
                    </div>
                    <div className={styles.whenGrid}>
                        {WHEN_IT_MAKES_SENSE.map((item, i) => (
                            <div key={i} className={styles.whenCard}>
                                <div className={styles.whenIcon} style={{ background: `${item.color}15`, color: item.color }}>{item.icon}</div>
                                <h3 className={styles.whenTitle}>{item.title}</h3>
                                <p className={styles.whenDesc}>{item.desc}</p>
                            </div>
                        ))}
                    </div>
                </div>
            </section>

            {/* ─── RPO INCLUDES ────────────────────────────────────────────── */}
            <section className={styles.includesSection}>
                <div className="premium-container">
                    <div className={styles.sectionHeader}>
                        <div className={styles.sectionBadge}><IconSparkle /> What's Included</div>
                        <h2 className={styles.sectionTitle}>Everything your hiring function needs, built in.</h2>
                    </div>
                    <div className={styles.includesGrid}>
                        {RPO_INCLUDES.map((item, i) => (
                            <div key={i} className={styles.includesCard}>
                                <div className={styles.includesIcon} style={{ background: `${item.color}12`, color: item.color, border: `1px solid ${item.color}25` }}>
                                    {item.icon}
                                </div>
                                <div>
                                    <h3 className={styles.includesTitle}>{item.title}</h3>
                                    <p className={styles.includesDesc}>{item.desc}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </section>

            {/* ─── ENGAGEMENT MODELS ───────────────────────────────────────── */}
            <section className={styles.modelsSection}>
                <div className="premium-container">
                    <div className={styles.sectionHeader}>
                        <div className={styles.sectionBadge}><IconSparkle /> Engagement Models</div>
                        <h2 className={styles.sectionTitle}>Pick the level of support that fits your stage.</h2>
                        <p className={styles.sectionSub}>Each model can be scaled up or down as your needs change.</p>
                    </div>
                    <div className={styles.modelsGrid}>
                        {ENGAGEMENT_MODELS.map((model, i) => (
                            <div key={i} className={`${styles.modelCard} ${model.highlight ? styles.modelHighlight : ''}`}>
                                {model.highlight && <div className={styles.modelBadge}>Most Popular</div>}
                                <div className={styles.modelAccent} style={{ background: model.color }} />
                                <h3 className={styles.modelName} style={{ color: model.highlight ? '#fff' : '#0f172a' }}>{model.name}</h3>
                                <p className={styles.modelTagline} style={{ color: model.highlight ? 'rgba(255,255,255,0.7)' : '#64748b' }}>{model.tagline}</p>
                                <p className={styles.modelDesc} style={{ color: model.highlight ? 'rgba(255,255,255,0.75)' : '#475569' }}>{model.desc}</p>
                                <ul className={styles.modelFeatures}>
                                    {model.features.map((f, j) => (
                                        <li key={j} className={styles.modelFeature} style={{ color: model.highlight ? 'rgba(255,255,255,0.85)' : '#334155' }}>
                                            <span className={styles.modelCheck} style={{ background: `${model.color}20`, color: model.color }}><IconCheck /></span>
                                            {f}
                                        </li>
                                    ))}
                                </ul>
                                <button
                                    className={`${styles.modelCta} ${model.highlight ? styles.modelCtaLight : ''}`}
                                    style={!model.highlight ? { borderColor: model.color, color: model.color } : undefined}
                                    onClick={() => document.getElementById('rpo-contact')?.scrollIntoView({ behavior: 'smooth' })}>
                                    Get started <IconArrow />
                                </button>
                            </div>
                        ))}
                    </div>
                </div>
            </section>

            {/* ─── INDUSTRIES ──────────────────────────────────────────────── */}
            <section className={styles.industriesSection}>
                <div className="premium-container">
                    <div className={styles.industriesInner}>
                        <div className={styles.sectionBadge}><IconSparkle /> Industries We Serve</div>
                        <h2 className={styles.industriesTitle}>Deep expertise where it counts.</h2>
                        <div className={styles.industryPills}>
                            {INDUSTRIES.map((ind, i) => (
                                <div key={i} className={styles.industryPill}>
                                    <span>{ind.emoji}</span>
                                    <span>{ind.label}</span>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </section>

            {/* ─── CONTACT / BOOK CALL ─────────────────────────────────────── */}
            <section className={styles.contactSection} id="rpo-contact">
                <div className="premium-container">
                    <div className={styles.contactGrid}>

                        {/* Left */}
                        <div className={styles.contactCopy}>
                            <div className={styles.sectionBadge}><IconSparkle /> Book a Strategy Call</div>
                            <h2 className={styles.contactTitle}>Let's design your RPO engagement.</h2>
                            <p className={styles.contactDesc}>
                                Tell us about your hiring goals and team size. An RPO specialist will reach out within 24 hours to walk you through options and build a custom proposal.
                            </p>
                            <ul className={styles.contactTrustList}>
                                <li><IconCheck /> No commitment required on your first call</li>
                                <li><IconCheck /> Custom proposal delivered within 48 hours</li>
                                <li><IconCheck /> Strict NDA and confidentiality from day one</li>
                                <li><IconCheck /> Dedicated specialist — not a call centre</li>
                            </ul>
                        </div>

                        {/* Form */}
                        <form className={styles.contactForm} onSubmit={handleSubmit} noValidate>
                            <div className={styles.fieldRow}>
                                <div className={styles.field}>
                                    <label className={styles.label}>Your Name *</label>
                                    <div className={`${styles.inputWrap} ${errors.name ? styles.hasError : ''}`}>
                                        <IconUser />
                                        <input type="text" placeholder="Full name" value={form.name} onChange={e => set('name', e.target.value)} />
                                    </div>
                                    {errors.name && <span className={styles.err}>{errors.name}</span>}
                                </div>
                                <div className={styles.field}>
                                    <label className={styles.label}>Company *</label>
                                    <div className={`${styles.inputWrap} ${errors.company ? styles.hasError : ''}`}>
                                        <IconBuilding />
                                        <input type="text" placeholder="Company name" value={form.company} onChange={e => set('company', e.target.value)} />
                                    </div>
                                    {errors.company && <span className={styles.err}>{errors.company}</span>}
                                </div>
                            </div>

                            <div className={styles.fieldRow}>
                                <div className={styles.field}>
                                    <label className={styles.label}>Work Email *</label>
                                    <div className={`${styles.inputWrap} ${errors.email ? styles.hasError : ''}`}>
                                        <IconMail />
                                        <input type="email" placeholder="you@company.com" value={form.email} onChange={e => set('email', e.target.value)} />
                                    </div>
                                    {errors.email && <span className={styles.err}>{errors.email}</span>}
                                </div>
                                <div className={styles.field}>
                                    <label className={styles.label}>Phone <span className={styles.opt}>(Optional)</span></label>
                                    <div className={styles.inputWrap}>
                                        <IconPhone />
                                        <input type="tel" placeholder="+1 (555) 000-0000" value={form.phone} onChange={e => set('phone', e.target.value)} />
                                    </div>
                                </div>
                            </div>

                            <div className={styles.fieldRow}>
                                <div className={styles.field}>
                                    <label className={styles.label}>Hiring volume</label>
                                    <select className={styles.select} value={form.hiringVolume} onChange={e => set('hiringVolume', e.target.value)}>
                                        <option value="">Select range…</option>
                                        <option>1–5 hires</option>
                                        <option>6–20 hires</option>
                                        <option>21–50 hires</option>
                                        <option>50–100 hires</option>
                                        <option>100+ hires</option>
                                    </select>
                                </div>
                                <div className={styles.field}>
                                    <label className={styles.label}>Timeline</label>
                                    <select className={styles.select} value={form.timeline} onChange={e => set('timeline', e.target.value)}>
                                        <option value="">Select timeline…</option>
                                        <option>ASAP (within 1 month)</option>
                                        <option>1–3 months</option>
                                        <option>3–6 months</option>
                                        <option>Ongoing / no fixed timeline</option>
                                    </select>
                                </div>
                            </div>

                            <div className={styles.field}>
                                <label className={styles.label}>Anything else we should know? <span className={styles.opt}>(Optional)</span></label>
                                <textarea className={styles.textarea} rows={4}
                                    placeholder="Roles you need to fill, team size, challenges you're facing…"
                                    value={form.notes} onChange={e => set('notes', e.target.value)} />
                            </div>

                            <button type="submit" className={styles.submitBtn}>
                                <IconSparkle /> Book My Strategy Call
                            </button>
                            <p className={styles.submitNote}>Our team will be in touch within <strong>24 hours.</strong></p>
                        </form>
                    </div>
                </div>
            </section>

        </main>
    );
}

.page {
    padding-top: 68px;
    min-height: 100vh;
    background: var(--light-ice-blue, #F0F7FF);
}

/* ─── Hero ── */
.hero {
    background: white;
    padding: 60px 0 48px;
    text-align: center;
    border-bottom: 1px solid var(--sky-blue);
}

.heroTitle {
    font-size: clamp(2rem, 4.5vw, 2.8rem);
    font-weight: 800;
    color: var(--cobalt-blue);
    margin: 0 0 14px;
}

.heroSub {
    font-size: 1.05rem;
    color: var(--medium-grey);
    margin: 0 0 32px;
}

/* Toggle */
.toggleWrap {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
}

.toggleLabel {
    font-size: 0.92rem;
    font-weight: 600;
    color: var(--medium-grey);
    display: flex;
    align-items: center;
    gap: 8px;
    transition: color 0.2s;
}

.toggleLabelActive {
    color: var(--cobalt-blue);
}

.togglePill {
    width: 48px;
    height: 26px;
    border-radius: 999px;
    background: var(--alice-blue);
    border: 1px solid var(--sky-blue);
    cursor: pointer;
    position: relative;
    transition: background 0.25s ease;
}

.togglePillOn {
    background: var(--primary-blue);
    border-color: var(--primary-blue);
}

.toggleThumb {
    position: absolute;
    top: 3px;
    left: 3px;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: white;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.25);
    transition: left 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

.togglePillOn .toggleThumb {
    left: 25px;
}

.saveBadge {
    background: var(--dodger-blue);
    color: white;
    font-size: 0.68rem;
    font-weight: 800;
    padding: 2px 8px;
    border-radius: 999px;
    letter-spacing: 0.04em;
}

/* ─── Pricing Section ── */
.pricingSection {
    padding: 52px 0 64px;
}

.pricingGrid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
    align-items: stretch;
}

.planCard {
    background: white;
    border-radius: 18px;
    padding: 32px 28px;
    border: 1px solid var(--sky-blue);
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.06);
    display: flex;
    flex-direction: column;
    position: relative;
    overflow: hidden;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.planCard:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.1);
}

.planCardFeatured {
    background: var(--alice-blue, #E3F2FD);
    border-color: var(--primary-blue);
    border-top: 4px solid var(--primary-blue);
}

.popularRibbon {
    position: absolute;
    top: 16px;
    right: 16px;
    background: var(--dodger-blue, #2196F3);
    color: white;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 3px 12px;
    border-radius: 999px;
}

.planName {
    font-size: 1rem;
    font-weight: 700;
    color: var(--medium-grey, #475569);
    text-transform: uppercase;
    letter-spacing: 0.07em;
    margin-bottom: 16px;
}

.planPrice {
    display: flex;
    align-items: baseline;
    gap: 4px;
    margin-bottom: 2px;
}

.priceNum {
    font-size: 2.8rem;
    font-weight: 800;
    color: var(--cobalt-blue);
    line-height: 1;
    transition: all 0.3s ease;
}

.pricePer {
    font-size: 0.82rem;
    color: var(--medium-grey);
}

.planPeriod {
    font-size: 0.8rem;
    color: var(--medium-grey);
    margin-bottom: 12px;
}

.planDesc {
    font-size: 0.88rem;
    color: var(--medium-grey);
    margin: 0 0 24px;
    line-height: 1.55;
    border-bottom: 1px solid var(--sky-blue);
    padding-bottom: 20px;
}

.featureList {
    list-style: none;
    margin: 0 0 28px;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 10px;
    flex: 1;
}

.featureItem {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    font-size: 0.88rem;
    color: var(--medium-grey);
}

.featureCheck {
    color: var(--primary-blue);
    flex-shrink: 0;
    margin-top: 1px;
}

.planCta {
    width: 100%;
    padding: 13px 20px;
    border-radius: 10px;
    font-size: 0.95rem;
    font-weight: 700;
    cursor: pointer;
    font-family: inherit;
    transition: all 0.2s ease;
    border: none;
    margin-top: auto;
}

.cta_outline {
    background: white;
    color: var(--primary-blue);
    border: 2px solid var(--primary-blue);
}

.cta_outline:hover {
    background: var(--alice-blue);
}

.cta_filled {
    background: linear-gradient(135deg, var(--primary-blue), var(--dodger-blue));
    color: white;
}

.cta_filled:hover {
    box-shadow: 0 6px 20px rgba(0, 123, 255, 0.4);
    transform: translateY(-1px);
}

.cta_dark {
    background: var(--ocean-deep, #1565C0);
    color: white;
}

.cta_dark:hover {
    background: var(--cobalt-blue);
}

/* ─── Table Section ── */
.tableSection {
    background: white;
    padding: 64px 0;
}

.sectionTitle {
    font-size: clamp(1.5rem, 3vw, 2rem);
    font-weight: 700;
    color: var(--cobalt-blue);
    text-align: center;
    margin: 0 0 36px;
}

.tableWrap {
    overflow-x: auto;
    border-radius: 14px;
    border: 1px solid var(--sky-blue);
}

.table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.88rem;
}

.tableHead {
    background: var(--cobalt-blue, #0D47A1);
    color: white;
}

.tableHead th {
    padding: 14px 20px;
    text-align: center;
    font-weight: 700;
    font-size: 0.9rem;
}

.thFeature {
    text-align: left !important;
    width: 35%;
}

.thGrowth {
    background: rgba(30, 136, 229, 0.3);
    color: var(--cool-sky-2, #42A5F5);
}

.rowEven {
    background: white;
}

.rowOdd {
    background: var(--light-ice-blue, #F0F7FF);
}

.tdFeature {
    padding: 13px 20px;
    font-weight: 600;
    color: var(--medium-grey);
}

.tdVal {
    text-align: center;
    padding: 13px 20px;
    color: var(--medium-grey);
}

.tdGrowth {
    background: rgba(227, 242, 253, 0.5);
}

.check {
    color: var(--dodger-blue);
    font-size: 1rem;
    font-weight: 700;
}

.dash {
    color: rgba(71, 85, 105, 0.45);
    font-size: 1rem;
}

/* ─── FAQ Section ── */
.faqSection {
    background: var(--light-ice-blue);
    padding: 64px 0;
}

.faqList {
    max-width: 720px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
}

.faqItem {
    border-bottom: 1px solid #BBDEFB;
}

.faqItem:last-child {
    border-bottom: none;
}

.faqQ {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 20px 0;
    background: none;
    border: none;
    cursor: pointer;
    font-size: 0.97rem;
    font-weight: 700;
    color: var(--cobalt-blue);
    text-align: left;
    font-family: inherit;
    gap: 12px;
}

.faqChev {
    color: var(--primary-blue);
    flex-shrink: 0;
    transition: transform 0.25s ease;
    line-height: 0;
}

.faqChevOpen {
    transform: rotate(180deg);
}

.faqA {
    padding: 0 0 20px 0;
    font-size: 0.9rem;
    color: var(--medium-grey);
    line-height: 1.65;
    background: var(--light-ice-blue);
    border-radius: 8px;
    padding: 14px 16px;
    margin-bottom: 4px;
}

/* ─── Responsive ── */
@media (max-width: 1024px) {
    .pricingGrid {
        grid-template-columns: 1fr;
        max-width: 480px;
        margin: 0 auto;
    }
}

@media (max-width: 640px) {
    .tableSection {
        padding: 40px 0;
    }

    .pricingSection {
        padding: 32px 0 40px;
    }
}

'use client';
import React, { useState } from 'react';
import styles from './products.module.css';

const CheckIco = () => <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12" /></svg>;
const ChevIco = () => <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="6 9 12 15 18 9" /></svg>;

const PLANS = [
    {
        name: 'Starter', tag: null, price: { monthly: 0, annual: 0 }, period: 'Free forever',
        desc: 'Perfect for small businesses hiring their first role.',
        features: ['1 active job post', 'Basic candidate matching', 'Email support', 'Candidate profile views', 'Standard listing'],
        ctaLabel: 'Get Started Free', ctaStyle: 'outline',
    },
    {
        name: 'Growth', tag: 'Most Popular ★', price: { monthly: 99, annual: 79 }, period: 'per month',
        desc: 'For growing teams that hire regularly.',
        features: ['Up to 5 active job posts', 'AI-powered screening', 'Applicant dashboard', 'Direct messaging', 'Calendar integration', 'Priority support', 'Analytics'],
        ctaLabel: 'Start Free Trial', ctaStyle: 'filled',
    },
    {
        name: 'Enterprise', tag: null, price: { monthly: null, annual: null }, period: 'Custom pricing',
        desc: 'For large teams, agencies, and high-volume hiring.',
        features: ['Unlimited posts + RPO options', 'Dedicated account manager', 'Custom integrations', 'Advanced analytics', 'SLA-backed support', 'Onboarding support'],
        ctaLabel: 'Book a Demo', ctaStyle: 'dark',
    },
];

const TABLE_ROWS = [
    { feature: 'Active Job Posts', starter: '1', growth: 'Up to 5', enterprise: 'Unlimited' },
    { feature: 'AI Candidate Matching', starter: 'Basic', growth: 'Advanced', enterprise: 'Custom' },
    { feature: 'Applicant Dashboard', starter: false, growth: true, enterprise: true },
    { feature: 'Direct Messaging', starter: false, growth: true, enterprise: true },
    { feature: 'Calendar Scheduling', starter: false, growth: true, enterprise: true },
    { feature: 'Analytics & Reporting', starter: false, growth: 'Standard', enterprise: 'Advanced' },
    { feature: 'Support Level', starter: 'Email', growth: 'Priority', enterprise: 'Dedicated SLA' },
    { feature: 'Custom Integrations', starter: false, growth: false, enterprise: true },
];

const FAQS = [
    { q: 'Can I cancel my plan anytime?', a: 'Yes. You can cancel at any time from your account settings with no lock-in period.' },
    { q: 'Do you charge per hire or per post?', a: 'We charge per job post, not per hire. The Growth plan allows up to 5 concurrent posts.' },
    { q: 'Is there a free trial available?', a: 'Yes — the Growth plan comes with a 14-day free trial, no credit card required.' },
    { q: 'What payment methods do you accept?', a: 'We accept all major credit cards (Visa, Mastercard, Amex) and bank transfers for Enterprise plans.' },
    { q: 'How do I upgrade or downgrade my plan?', a: 'You can change plans at any time from your billing settings. Changes take effect at the next billing cycle.' },
    { q: 'Can I try before I buy?', a: 'Absolutely — start with our free Starter plan or activate the Growth free trial to explore all features.' },
];

export default function ProductsPage() {
    const [annual, setAnnual] = useState(false);
    const [openFaq, setOpenFaq] = useState<number | null>(null);

    const displayPrice = (plan: typeof PLANS[0]) => {
        if (plan.price.monthly === null) return 'Custom';
        const p = annual ? plan.price.annual : plan.price.monthly;
        return p === 0 ? 'Free' : `$${p}`;
    };

    return (
        <main className={styles.page}>
            {/* ── HERO ── */}
            <section className={styles.hero}>
                <div className="premium-container">
                    <h1 className={styles.heroTitle}>Simple Pricing. Powerful Hiring.</h1>
                    <p className={styles.heroSub}>Whether you're hiring one person or scaling a team, we have a plan that fits.</p>

                    {/* Billing toggle */}
                    <div className={styles.toggleWrap}>
                        <span className={`${styles.toggleLabel} ${!annual ? styles.toggleLabelActive : ''}`}>Monthly</span>
                        <button
                            className={`${styles.togglePill} ${annual ? styles.togglePillOn : ''}`}
                            onClick={() => setAnnual(a => !a)} aria-label="Switch billing period"
                        >
                            <span className={styles.toggleThumb} />
                        </button>
                        <span className={`${styles.toggleLabel} ${annual ? styles.toggleLabelActive : ''}`}>
                            Annual {annual && <span className={styles.saveBadge}>Save 20%</span>}
                        </span>
                    </div>
                </div>
            </section>

            {/* ── PRICING CARDS ── */}
            <section className={styles.pricingSection}>
                <div className="premium-container">
                    <div className={styles.pricingGrid}>
                        {PLANS.map(plan => (
                            <div key={plan.name} className={`${styles.planCard} ${plan.tag ? styles.planCardFeatured : ''}`}>
                                {plan.tag && <div className={styles.popularRibbon}>{plan.tag}</div>}
                                <div className={styles.planName}>{plan.name}</div>
                                <div className={styles.planPrice}>
                                    <span className={styles.priceNum}>{displayPrice(plan)}</span>
                                    {plan.price.monthly !== null && plan.price.monthly > 0 && (
                                        <span className={styles.pricePer}>/{annual ? 'mo (billed annually)' : 'month'}</span>
                                    )}
                                </div>
                                <div className={styles.planPeriod}>{plan.period}</div>
                                <p className={styles.planDesc}>{plan.desc}</p>
                                <ul className={styles.featureList}>
                                    {plan.features.map(f => (
                                        <li key={f} className={styles.featureItem}><span className={styles.featureCheck}><CheckIco /></span>{f}</li>
                                    ))}
                                </ul>
                                <button className={`${styles.planCta} ${styles[`cta_${plan.ctaStyle}`]}`}>{plan.ctaLabel}</button>
                            </div>
                        ))}
                    </div>
                </div>
            </section>

            {/* ── COMPARISON TABLE ── */}
            <section className={styles.tableSection}>
                <div className="premium-container">
                    <h2 className={styles.sectionTitle}>Feature Comparison</h2>
                    <div className={styles.tableWrap}>
                        <table className={styles.table}>
                            <thead>
                                <tr className={styles.tableHead}>
                                    <th className={styles.thFeature}>Feature</th>
                                    <th>Starter</th>
                                    <th className={styles.thGrowth}>Growth ★</th>
                                    <th>Enterprise</th>
                                </tr>
                            </thead>
                            <tbody>
                                {TABLE_ROWS.map((row, i) => (
                                    <tr key={row.feature} className={i % 2 === 0 ? styles.rowEven : styles.rowOdd}>
                                        <td className={styles.tdFeature}>{row.feature}</td>
                                        {([row.starter, row.growth, row.enterprise] as (boolean | string)[]).map((val, ci) => (
                                            <td key={ci} className={`${styles.tdVal} ${ci === 1 ? styles.tdGrowth : ''}`}>
                                                {val === true ? <span className={styles.check}>✓</span> :
                                                    val === false ? <span className={styles.dash}>—</span> : val}
                                            </td>
                                        ))}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </section>

            {/* ── FAQ ── */}
            <section className={styles.faqSection}>
                <div className="premium-container">
                    <h2 className={styles.sectionTitle}>Frequently Asked Questions</h2>
                    <div className={styles.faqList}>
                        {FAQS.map((faq, i) => (
                            <div key={i} className={styles.faqItem}>
                                <button className={styles.faqQ} onClick={() => setOpenFaq(openFaq === i ? null : i)}>
                                    <span>{faq.q}</span>
                                    <span className={`${styles.faqChev} ${openFaq === i ? styles.faqChevOpen : ''}`}><ChevIco /></span>
                                </button>
                                {openFaq === i && <div className={styles.faqA}>{faq.a}</div>}
                            </div>
                        ))}
                    </div>
                </div>
            </section>
        </main>
    );
}

/* ─── Page ──────────────────────────────────────────────────────────────────── */
.page {
    padding-top: 68px;
    min-height: 100vh;
    background: var(--light-ice-blue, #F0F7FF);
}

/* ─── Hero ──────────────────────────────────────────────────────────────────── */
.hero {
    background: linear-gradient(135deg, #0d1b3e 0%, #1e293b 100%);
    padding: 64px 0;
    overflow: hidden;
}

.heroLayout {
    display: grid;
    grid-template-columns: 1fr 360px;
    gap: 48px;
    align-items: center;
}

.heroLeft {
    color: white;
}

.heroBadge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: rgba(33, 150, 243, 0.18);
    border: 1px solid rgba(33, 150, 243, 0.35);
    color: var(--cool-sky-2, #42A5F5);
    font-size: 0.78rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    padding: 5px 14px;
    border-radius: 999px;
    margin-bottom: 18px;
    text-transform: uppercase;
}

.heroTitle {
    font-size: clamp(1.9rem, 4vw, 3rem);
    font-weight: 800;
    color: white;
    margin: 0 0 16px;
    line-height: 1.15;
    letter-spacing: -0.02em;
}

.heroSub {
    font-size: 1.05rem;
    color: #BBDEFB;
    margin: 0 0 32px;
    line-height: 1.65;
}

.heroCta {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background: var(--primary-blue, #007BFF);
    color: white;
    border: none;
    padding: 14px 28px;
    border-radius: 12px;
    font-size: 1rem;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.2s ease;
    font-family: inherit;
}

.heroCta:hover {
    background: #0069d9;
    box-shadow: 0 8px 24px rgba(0, 123, 255, 0.5);
    transform: translateY(-2px);
}

.freeBadge {
    background: var(--cool-sky-2, #42A5F5);
    color: white;
    font-size: 0.68rem;
    font-weight: 800;
    padding: 2px 8px;
    border-radius: 999px;
    letter-spacing: 0.04em;
}

/* Live preview card */
.previewCard {
    background: rgba(255, 255, 255, 0.07);
