/* ─── Form Section ──────────────────────────────────────────────────────────── */
.formSection {
    padding: 52px 0;
}

.formWrap {
    max-width: 720px;
    margin: 0 auto;
    background: white;
    border-radius: 24px;
    box-shadow: 0 8px 40px rgba(0, 0, 0, 0.10);
    overflow: hidden;
}

/* Progress */
.progressBar {
    display: flex;
    align-items: center;
    padding: 24px 32px;
    background: var(--light-ice-blue);
    border-bottom: 1px solid var(--sky-blue);
}

.progressStep {
    display: flex;
    align-items: center;
    gap: 8px;
}

.progressStep:not(:last-child) {
    flex: 1;
}

.progressDot {
    width: 30px;
    height: 30px;
    border-radius: 50%;
    background: var(--alice-blue);
    border: 2px solid var(--sky-blue);
    color: var(--medium-grey);
    font-size: 0.8rem;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    transition: all 0.25s ease;
}

.progressStepActive .progressDot {
    background: var(--primary-blue);
    border-color: var(--primary-blue);
    color: white;
}

.progressLabel {
    font-size: 0.82rem;
    font-weight: 600;
    color: var(--medium-grey);
    white-space: nowrap;
}

.progressStepActive .progressLabel {
    color: var(--cobalt-blue);
}

.progressLine {
    flex: 1;
    height: 2px;
    background: var(--sky-blue);
    margin: 0 8px;
    border-radius: 2px;
}

.progressLineFill {
    background: var(--primary-blue);
}

/* Form steps */
.formStep {
    padding: 36px;
}

.stepHdr {
    font-size: 1.2rem;
    font-weight: 700;
    color: var(--cobalt-blue);
    margin: 0 0 24px;
}

.fieldRow {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 16px;
}

.field {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-bottom: 16px;
}

.lbl {
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--cobalt-blue);
}

.opt {
    font-style: italic;
    font-weight: 400;
    color: var(--medium-grey);
