}

.input,
.select {
    border: 1px solid var(--sky-blue);
    border-radius: 8px;
    padding: 11px 14px;
    font-size: 0.9rem;
    font-family: inherit;
    color: var(--deep-navy, #0d2137);
    background: white;
    outline: none;
    appearance: none;
    transition: border-color 0.2s, box-shadow 0.2s;
}

.input:focus,
.select:focus {
    border-color: var(--primary-blue);
    box-shadow: 0 0 0 3px rgba(0, 123, 255, 0.12);
}

.input::placeholder {
