}

/* ─── Value Props ────────────────────────────────────────────────────────────── */
.valueSection {
    background: var(--light-ice-blue);
    padding: 64px 0;
}

.valueSectionTitle {
    font-size: 1.7rem;
    font-weight: 700;
    color: var(--cobalt-blue);
    text-align: center;
    margin: 0 0 40px;
}

.valueGrid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 24px;
}

.valueProp {
    text-align: center;
    padding: 24px 16px;
}

.valuePropIcoBg {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    background: var(--alice-blue);
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 14px;
}

.valuePropIco {
    font-size: 1.5rem;
}

.valueStat {
    font-size: 1.3rem;
    font-weight: 800;
    color: var(--cobalt-blue);
}

.valueLabel {
    font-size: 0.88rem;
    font-weight: 700;
    color: var(--ocean-deep);
    margin: 2px 0 4px;
}

.valueDesc {
    font-size: 0.8rem;
    color: var(--medium-grey);
}

/* ─── Responsive ─────────────────────────────────────────────────────────────── */
@media (max-width: 1024px) {
    .heroLayout {
        grid-template-columns: 1fr;
    }

    .previewCard {
        display: none;
    }

    .valueGrid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 640px) {
    .formStep {
        padding: 24px 20px;
    }

    .fieldRow {
        grid-template-columns: 1fr;
    }

    .progressLabel {
        display: none;
    }

    .valueGrid {
        grid-template-columns: 1fr 1fr;
    }

    .stepBtns {
        flex-direction: column-reverse;
    }
}

'use client';
import React, { useState } from 'react';
import styles from './post-job.module.css';

const SparkleIco = () => <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><path d="m12 3 1.912 5.885L20 10.8l-5.088 1.912L13 18.6l-1.912-5.888L6 10.8l5.088-1.915Z" /></svg>;
const CheckIco = () => <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12" /></svg>;

const JOB_TYPES = ['Full-Time', 'Part-Time', 'Remote', 'Hybrid', 'Contract'];
const INDUSTRIES = ['Technology', 'Product', 'Design', 'Finance', 'Sales & Marketing', 'HR & People', 'Operations', 'Customer Success'];
const EXP_LEVELS = ['Entry Level', 'Mid Level', 'Senior', 'Lead / Manager', 'Director+'];
const VALUE_PROPS = [
    { icon: '🎯', stat: '10,000+', label: 'Active Candidates', desc: 'Reach pre-qualified talent instantly' },
    { icon: '🤖', stat: 'AI', label: 'Smart Matching', desc: 'AI matches jobs to the most relevant talent' },
    { icon: '✅', stat: 'Free', label: 'Free to Post', desc: 'Premium boosting available when needed' },
    { icon: '📋', stat: 'All-in-1', label: 'Application Dashboard', desc: 'Manage all applicants in one place' },
];

const PREVIEW_DEFAULTS = {
    title: 'Your Job Title', company: 'Your Company', location: 'Remote', type: 'Full-Time',
    salary: '$80k–$120k', skills: [] as string[], exp: 'Mid Level',
};

export default function PostJobPage() {
    const [step, setStep] = useState(0);
    const [remote, setRemote] = useState(true);
    const [skills, setSkills] = useState<string[]>([]);
    const [skillInput, setSkillInput] = useState('');
    const [aiLoading, setAiLoading] = useState(false);
    const [aiGenerated, setAiGenerated] = useState(false);
    const [submitted, setSubmitted] = useState(false);
    const [form, setForm] = useState({
        title: '', company: '', industry: '', location: '', salary: '', exp: '', description: '', deadline: ''
    });

    const set = (k: string, v: string) => setForm(p => ({ ...p, [k]: v }));

    const addSkill = () => {
        const s = skillInput.trim();
        if (s && !skills.includes(s)) setSkills(p => [...p, s]);
        setSkillInput('');
    };

    const handleAiGenerate = () => {
        setAiLoading(true);
        setTimeout(() => {
            setForm(p => ({
                ...p, description:
                    `We are looking for a talented ${form.title || 'professional'} to join our growing team at ${form.company || 'our company'}.\n\nResponsibilities:\n• Design, develop and maintain robust solutions\n• Collaborate cross-functionally with product and design teams\n• Champion best practices and mentor junior team members\n• Drive outcomes through data-informed decision making\n\nRequirements:\n${skills.length ? skills.map(s => `• ${s}`).join('\n') : '• Relevant skills and experience'}\n• Strong communication and problem-solving skills\n• Passion for building impactful products\n\nWhat we offer:\n• Competitive compensation ${form.salary ? `(${form.salary})` : ''}\n• Flexible remote-first culture\n• Professional growth budget\n• Collaborative and inclusive team`
            }));
            setAiLoading(false); setAiGenerated(true);
        }, 1800);
    };

    const preview = {
        title: form.title || PREVIEW_DEFAULTS.title,
        company: form.company || PREVIEW_DEFAULTS.company,
        location: remote ? 'Remote' : form.location || PREVIEW_DEFAULTS.location,
        type: form.exp || JOB_TYPES[0],
        salary: form.salary || PREVIEW_DEFAULTS.salary,
        skills,
        exp: form.exp || PREVIEW_DEFAULTS.exp,
    };

    const STEPS = ['Details', 'Description', 'Preview'];

    return (
        <main className={styles.page}>
            {/* ── HERO ── */}
            <section className={styles.hero}>
                <div className="premium-container">
                    <div className={styles.heroLayout}>
                        <div className={styles.heroLeft}>
                            <div className={styles.heroBadge}><SparkleIco /> AI-Powered</div>
                            <h1 className={styles.heroTitle}>Post a Job.<br />Let AI Find Your Perfect Hire.</h1>
                            <p className={styles.heroSub}>Create a high-quality job listing in under 2 minutes. Our AI generates the description — you just fill in the basics.</p>
                            <button className={styles.heroCta} onClick={() => document.getElementById('post-form')?.scrollIntoView({ behavior: 'smooth' })}>
                                Post a Job for Free <span className={styles.freeBadge}>FREE</span>
                            </button>
                        </div>
                        {/* Live preview card */}
                        <div className={`${styles.previewCard} glass-card`}>
                            <div className={styles.previewHead}>
                                <div className={styles.previewLogo}>{preview.company.slice(0, 2).toUpperCase()}</div>
                                <div>
                                    <div className={styles.previewTitle}>{preview.title}</div>
                                    <div className={styles.previewCompany}>{preview.company}</div>
                                </div>
                            </div>
                            <div className={styles.previewMeta}>
                                <span>📍 {preview.location}</span>
                                <span>💼 {preview.exp}</span>
                            </div>
                            <div className={styles.previewTags}>
                                <span className={styles.previewTag}>{preview.salary}</span>
                                {skills.slice(0, 3).map(s => <span key={s} className={styles.previewSkill}>{s}</span>)}
                            </div>
                            <div className={styles.previewLabel}>Live Preview</div>
                        </div>
                    </div>
                </div>
            </section>

            {/* ── FORM ── */}
            <section className={styles.formSection} id="post-form">
                <div className="premium-container">
                    <div className={styles.formWrap}>

                        {/* Progress */}
                        <div className={styles.progressBar}>
                            {STEPS.map((s, i) => (
                                <React.Fragment key={s}>
                                    <div className={`${styles.progressStep} ${i <= step ? styles.progressStepActive : ''}`} onClick={() => i < step && setStep(i)}>
                                        <div className={styles.progressDot}>{i < step ? <CheckIco /> : i + 1}</div>
                                        <span className={styles.progressLabel}>{s}</span>
                                    </div>
                                    {i < STEPS.length - 1 && <div className={`${styles.progressLine} ${i < step ? styles.progressLineFill : ''}`} />}
                                </React.Fragment>
                            ))}
                        </div>

                        {submitted ? (
                            <div className={styles.success}>
                                <div className={styles.successIco}><CheckIco /></div>
                                <h2 className={styles.successTitle}>Job Posted Successfully!</h2>
                                <p className={styles.successDesc}>Your listing is now live. Our AI is already matching candidates to your role.</p>
                                <button className={styles.successBtn} onClick={() => { setSubmitted(false); setStep(0); }}>Post Another Job</button>
                            </div>
                        ) : (
                            <>
                                {/* STEP 0 — Details */}
                                {step === 0 && (
                                    <div className={styles.formStep}>
                                        <h2 className={styles.stepHdr}>Job Details</h2>
                                        <div className={styles.fieldRow}>
                                            <div className={styles.field}>
                                                <label className={styles.lbl}>Job Title *</label>
                                                <input className={styles.input} placeholder="e.g. Senior Product Designer" value={form.title} onChange={e => set('title', e.target.value)} />
                                            </div>
                                            <div className={styles.field}>
                                                <label className={styles.lbl}>Company Name *</label>
                                                <input className={styles.input} placeholder="Your Company" value={form.company} onChange={e => set('company', e.target.value)} />
                                            </div>
                                        </div>
                                        <div className={styles.fieldRow}>
                                            <div className={styles.field}>
                                                <label className={styles.lbl}>Industry / Department</label>
                                                <select className={styles.select} value={form.industry} onChange={e => set('industry', e.target.value)}>
                                                    <option value="">Select industry</option>
                                                    {INDUSTRIES.map(i => <option key={i}>{i}</option>)}
                                                </select>
                                            </div>
                                            <div className={styles.field}>
                                                <label className={styles.lbl}>Experience Level</label>
                                                <select className={styles.select} value={form.exp} onChange={e => set('exp', e.target.value)}>
                                                    <option value="">Select level</option>
                                                    {EXP_LEVELS.map(e => <option key={e}>{e}</option>)}
                                                </select>
                                            </div>
                                        </div>

                                        {/* Location toggle */}
                                        <div className={styles.field}>
                                            <label className={styles.lbl}>Location</label>
                                            <div className={styles.locationToggle}>
                                                <button className={`${styles.toggleBtn} ${remote ? styles.toggleActive : ''}`} onClick={() => setRemote(true)}>Remote</button>
                                                <button className={`${styles.toggleBtn} ${!remote ? styles.toggleActive : ''}`} onClick={() => setRemote(false)}>Specific City</button>
                                            </div>
                                            {!remote && <input className={`${styles.input} ${styles.mt8}`} placeholder="e.g. San Francisco, CA" value={form.location} onChange={e => set('location', e.target.value)} />}
                                        </div>

                                        <div className={styles.fieldRow}>
                                            <div className={styles.field}>
                                                <label className={styles.lbl}>Salary Range <em className={styles.opt}>(optional)</em></label>
                                                <input className={styles.input} placeholder="e.g. $80k–$120k" value={form.salary} onChange={e => set('salary', e.target.value)} />
                                            </div>
                                            <div className={styles.field}>
                                                <label className={styles.lbl}>Application Deadline</label>
                                                <input className={styles.input} type="date" value={form.deadline} onChange={e => set('deadline', e.target.value)} />
                                            </div>
                                        </div>

                                        {/* Skills tag input */}
                                        <div className={styles.field}>
                                            <label className={styles.lbl}>Required Skills</label>
                                            <div className={styles.skillsWrap}>
                                                {skills.map(s => (
                                                    <span key={s} className={styles.skillTag}>{s}<button onClick={() => setSkills(p => p.filter(x => x !== s))}>×</button></span>
                                                ))}
                                                <input className={styles.skillInput} placeholder="Type skill + Enter"
                                                    value={skillInput} onChange={e => setSkillInput(e.target.value)}
                                                    onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); addSkill(); } }} />
                                            </div>
                                        </div>

                                        <button className={styles.nextBtn} onClick={() => setStep(1)}>Continue to Description →</button>
                                    </div>
                                )}

                                {/* STEP 1 — Description */}
                                {step === 1 && (
                                    <div className={styles.formStep}>
                                        <h2 className={styles.stepHdr}>Job Description</h2>
                                        <div className={styles.aiRow}>
                                            <p className={styles.aiHint}>Let AI write your job description based on the details you filled in.</p>
                                            <button className={styles.aiBtn} onClick={handleAiGenerate} disabled={aiLoading}>
                                                {aiLoading ? <span className={styles.aiSpinner} /> : <SparkleIco />}
                                                {aiLoading ? 'Generating...' : '✦ AI Generate Description'}
                                            </button>
                                        </div>
                                        <textarea className={`${styles.textarea} ${aiGenerated ? styles.textareaAi : ''}`}
                                            rows={14} placeholder="Or write your job description here..."
                                            value={form.description} onChange={e => set('description', e.target.value)} />
                                        {aiGenerated && <div className={styles.aiNote}><SparkleIco /> AI-generated — review and edit before posting</div>}
                                        <div className={styles.stepBtns}>
                                            <button className={styles.backBtn} onClick={() => setStep(0)}>← Back</button>
                                            <button className={styles.nextBtn} onClick={() => setStep(2)}>Preview Job →</button>
                                        </div>
                                    </div>
                                )}

                                {/* STEP 2 — Preview */}
                                {step === 2 && (
                                    <div className={styles.formStep}>
                                        <h2 className={styles.stepHdr}>Preview Your Listing</h2>
                                        <div className={styles.finalPreview}>
                                            <div className={styles.fpHead}>
                                                <div className={styles.fpLogo}>{preview.company.slice(0, 2).toUpperCase()}</div>
                                                <div>
                                                    <div className={styles.fpTitle}>{preview.title}</div>
                                                    <div className={styles.fpMeta}>{preview.company} · {preview.location}</div>
                                                </div>
                                            </div>
                                            <div className={styles.fpBadges}>
                                                <span className={styles.fpBadge}>{preview.exp}</span>
                                                {preview.salary && <span className={styles.fpBadge}>{preview.salary}</span>}
                                                {skills.slice(0, 4).map(s => <span key={s} className={styles.fpSkill}>{s}</span>)}
                                            </div>
                                            <div className={styles.fpDesc}>{form.description || 'No description yet.'}</div>
                                        </div>
                                        <div className={styles.stepBtns}>
                                            <button className={styles.backBtn} onClick={() => setStep(1)}>← Edit</button>
                                            <button className={styles.postBtn} onClick={() => setSubmitted(true)}>🚀 Post This Job</button>
                                        </div>
                                    </div>
                                )}
                            </>
                        )}
                    </div>
                </div>
            </section>

            {/* ── VALUE PROPS ── */}
            <section className={styles.valueSection}>
                <div className="premium-container">
                    <h2 className={styles.valueSectionTitle}>Why Post on TalentMesh?</h2>
                    <div className={styles.valueGrid}>
                        {VALUE_PROPS.map(vp => (
                            <div key={vp.label} className={styles.valueProp}>
                                <div className={styles.valuePropIcoBg}><span className={styles.valuePropIco}>{vp.icon}</span></div>
                                <div className={styles.valueStat}>{vp.stat}</div>
                                <div className={styles.valueLabel}>{vp.label}</div>
                                <div className={styles.valueDesc}>{vp.desc}</div>
                            </div>
                        ))}
                    </div>
                </div>
            </section>
        </main>
    );
}

/* ============================
   RECRUITER DASHBOARD PAGES
   ============================ */

.dash {
    display: flex;
    flex-direction: column;
    gap: 1.15rem;
}

.greet {}

.greetTitle {
    font-size: 1.35rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.02em;
}

.greetSub {
    font-size: 0.8rem;
    color: #94a3b8;
    margin-top: 0.1rem;
}

/* Stats */
.stats {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 0.75rem;
}

.stat {
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 12px;
    padding: 1rem 1.1rem;
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
    transition: box-shadow 0.2s ease;
}

.stat:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}

.statTop {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.statLabel {
    font-size: 0.72rem;
    color: #94a3b8;
    font-weight: 500;
}

.statBox {
    width: 32px;
    height: 32px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.9rem;
}

.statVal {
    font-size: 1.5rem;
    font-weight: 800;
    color: #0f172a;
}

.statChange {
    font-size: 0.68rem;
    color: #10b981;
    font-weight: 600;
}

.statHint {
    font-size: 0.68rem;
    color: #94a3b8;
}

/* Grid */
.mainGrid {
    display: grid;
    grid-template-columns: 1fr 340px;
    gap: 0.75rem;
}

.leftCol {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.rightCol {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.card {
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 12px;
    padding: 1.1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.cardHead {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.cardTitle {
    font-size: 0.88rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0;
}

.viewAll {
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--primary-blue);
    background: none;
    border: none;
    cursor: pointer;
}

.viewAll:hover {
    text-decoration: underline;
}

/* Position cards */
.posCard {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.65rem 0.75rem;
    border: 1px solid #f1f5f9;
    border-radius: 9px;
    transition: all 0.15s ease;
}

.posCard:hover {
    background: #fafbfc;
}

.posBody {
    display: flex;
    flex-direction: column;
    gap: 0.05rem;
}

.posRow {
    display: flex;
    align-items: center;
    gap: 0.4rem;
}

.posTitle {
    font-size: 0.82rem;
    font-weight: 700;
    color: #0f172a;
}

.posMeta {
    font-size: 0.68rem;
    color: #94a3b8;
}

.urgentTag {
    font-size: 0.55rem;
    font-weight: 700;
    color: #ef4444;
    background: #fef2f2;
    padding: 0.1rem 0.35rem;
    border-radius: 4px;
}

.posStatus {
    font-size: 0.62rem;
    font-weight: 700;
    color: #10b981;
    background: #f0fdf4;
    padding: 0.15rem 0.5rem;
    border-radius: 10px;
}

/* Pipeline Bar */
.pipelineBar {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-top: 0.25rem;
}

.pipeSegment {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.pipeBar {
    height: 6px;
    border-radius: 3px;
}

.pipeMeta {
    display: flex;
    justify-content: space-between;
}

.pipeLabel {
    font-size: 0.68rem;
    color: #64748b;
}

.pipeCount {
    font-size: 0.68rem;
    font-weight: 700;
    color: #0f172a;
}

/* Candidate cards */
.candCard {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.55rem 0.65rem;
    border: 1px solid #f1f5f9;
    border-radius: 9px;
    transition: all 0.15s ease;
}

.candCard:hover {
    background: #fafbfc;
}

.candAvatar {
    width: 32px;
    height: 32px;
    border-radius: 8px;
    background: var(--primary-blue);
    color: white;
    font-size: 0.58rem;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.candBody {
    flex: 1;
    display: flex;
    flex-direction: column;
}

.candName {
    font-size: 0.78rem;
    font-weight: 700;
    color: #0f172a;
}

.candMeta {
    font-size: 0.68rem;
    color: #94a3b8;
}

.candMatch {
    font-size: 0.68rem;
    font-weight: 700;
    color: var(--primary-blue);
    background: #eff6ff;
    padding: 0.15rem 0.45rem;
    border-radius: 8px;
}

/* Interview cards */
.intCard {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.55rem 0.65rem;
    border: 1px solid #f1f5f9;
    border-radius: 9px;
}

.intTime {
    font-size: 0.68rem;
    font-weight: 700;
    color: var(--primary-blue);
    background: #eff6ff;
    padding: 0.2rem 0.45rem;
    border-radius: 6px;
    white-space: nowrap;
}

.intBody {
    flex: 1;
    display: flex;
    flex-direction: column;
}

.intName {
    font-size: 0.75rem;
    font-weight: 600;
    color: #0f172a;
}

.intType {
    font-size: 0.62rem;
    color: #94a3b8;
}

.intBtn {
    font-size: 0.68rem;
    font-weight: 600;
    background: #f5f7fa;
    border: 1px solid #eef0f2;
    border-radius: 6px;
    padding: 0.25rem 0.5rem;
    color: #374151;
    cursor: pointer;
    font-family: inherit;
    transition: all 0.15s ease;
}

.intBtn:hover {
    background: var(--primary-blue);
    color: white;
    border-color: var(--primary-blue);
}

/* Actions */
.primaryAction {
    width: 100%;
    padding: 0.55rem;
    background: var(--primary-blue);
    color: white;
    border: none;
    border-radius: 8px;
    font-size: 0.82rem;
    font-weight: 700;
    cursor: pointer;
    font-family: inherit;
    transition: all 0.2s ease;
}

.primaryAction:hover {
    background: #0056d6;
}

.secondaryAction {
    width: 100%;
    padding: 0.5rem;
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 8px;
    font-size: 0.78rem;
    font-weight: 500;
    color: #374151;
    cursor: pointer;
    font-family: inherit;
    transition: all 0.15s ease;
}

.secondaryAction:hover {
    background: #f5f7fa;
}

/* ── Job Postings Page ── */
.jobsPage {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.pageHead {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.5rem;
}

.pageTitle {
    font-size: 1.15rem;
    font-weight: 800;
    color: #0f172a;
}

.createBtn {
    padding: 0.45rem 0.85rem;
    background: var(--primary-blue);
    color: white;
    border: none;
    border-radius: 8px;
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    font-family: inherit;
}

.jobPostCard {
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 12px;
    padding: 1rem;
    display: flex;
    align-items: center;
    gap: 1rem;
    transition: all 0.15s ease;
}

.jobPostCard:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}

.jobPostBody {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.1rem;
}

.jobPostTitle {
    font-size: 0.88rem;
    font-weight: 700;
    color: #0f172a;
}

.jobPostMeta {
    font-size: 0.72rem;
    color: #94a3b8;
}

.jobPostStats {
    display: flex;
    gap: 0.75rem;
    margin-top: 0.15rem;
}

.jobPostStat {
    font-size: 0.68rem;
    color: #64748b;
    font-weight: 500;
}

.jobPostActions {
    display: flex;
    gap: 0.35rem;
}

.editBtn {
    font-size: 0.72rem;
    font-weight: 500;
    padding: 0.35rem 0.65rem;
    background: #f5f7fa;
    border: 1px solid #eef0f2;
    border-radius: 6px;
    color: #374151;
    cursor: pointer;
    font-family: inherit;
}

/* ── Candidates Page ── */
.candPage {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.candGrid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 0.75rem;
}

.candFullCard {
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 12px;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
    transition: all 0.15s ease;
    cursor: pointer;
}

.candFullCard:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
    border-color: #bfdbfe;
}

.candFullHead {
    display: flex;
    align-items: center;
    gap: 0.6rem;
}

.candFullAvatar {
    width: 44px;
    height: 44px;
    border-radius: 10px;
    background: linear-gradient(135deg, var(--primary-blue), #60a5fa);
    color: white;
    font-size: 0.75rem;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.candFullName {
    font-size: 0.88rem;
    font-weight: 700;
    color: #0f172a;
}

.candFullRole {
    font-size: 0.72rem;
    color: #64748b;
}

.candFullTags {
    display: flex;
    flex-wrap: wrap;
    gap: 0.25rem;
    margin-top: 0.1rem;
}

.candFullTag {
    font-size: 0.62rem;
    color: #475569;
    background: #f5f7fa;
    padding: 0.1rem 0.4rem;
    border-radius: 4px;
    border: 1px solid #eef0f2;
}

.candFullFoot {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-top: 0.2rem;
}

.candFullLoc {
    font-size: 0.68rem;
    color: #94a3b8;
}

.candFullMatch {
    font-size: 0.68rem;
    font-weight: 700;
    color: var(--primary-blue);
}

.candFullActions {
    display: flex;
    gap: 0.3rem;
}

.candViewBtn {
    font-size: 0.75rem;
    font-weight: 700;
    padding: 0.4rem 0.85rem;
    background: linear-gradient(135deg, var(--primary-blue), #2563eb);
    color: white;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    font-family: inherit;
    transition: all 0.2s ease;
    box-shadow: 0 2px 8px rgba(37, 99, 235, 0.25);
}

.candViewBtn:hover {
    background: linear-gradient(135deg, #2563eb, #1d4ed8);
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.35);
}

.candSaveBtn {
    font-size: 0.72rem;
    padding: 0.3rem 0.45rem;
    background: #f5f7fa;
    border: 1px solid #eef0f2;
    border-radius: 6px;
    cursor: pointer;
}

/* Responsive */
@media (max-width: 1024px) {
    .stats {
        grid-template-columns: repeat(2, 1fr);
    }

    .mainGrid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 768px) {
    .stats {
        grid-template-columns: 1fr;
    }
}

"use client";
import React, { useEffect, useState } from 'react';
import styles from './recruiter.module.css';
import AnimateOnScroll from '@/components/AnimateOnScroll';
import { insforge } from '@/lib/insforge';

/* ─── Icons ─── */
const IC = {
    clipboard: <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2" /><rect x="8" y="2" width="8" height="4" rx="1" /></svg>,
    users: <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" /><circle cx="9" cy="7" r="4" /><path d="M23 21v-2a4 4 0 0 0-3-3.87" /><path d="M16 3.13a4 4 0 0 1 0 7.75" /></svg>,
    calendar: <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><rect x="3" y="4" width="18" height="18" rx="2" /><line x1="16" y1="2" x2="16" y2="6" /><line x1="8" y1="2" x2="8" y2="6" /><line x1="3" y1="10" x2="21" y2="10" /></svg>,
    checkCircle: <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" /><polyline points="22 4 12 14.01 9 11.01" /></svg>,
    trending: <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><polyline points="23 6 13.5 15.5 8.5 10.5 1 18" /><polyline points="17 6 23 6 23 12" /></svg>,
    alertCircle: <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><circle cx="12" cy="12" r="10" /><line x1="12" y1="8" x2="12" y2="12" /><line x1="12" y1="16" x2="12.01" y2="16" /></svg>,
    barChart: <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><line x1="12" y1="20" x2="12" y2="10" /><line x1="18" y1="20" x2="18" y2="4" /><line x1="6" y1="20" x2="6" y2="16" /></svg>,
    plus: <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><line x1="12" y1="5" x2="12" y2="19" /><line x1="5" y1="12" x2="19" y2="12" /></svg>,
};

export default function RecruiterHome() {
    const [jobs, setJobs] = useState<any[]>([]);
    const [candidates, setCandidates] = useState<any[]>([]);
    const [interviews, setInterviews] = useState<any[]>([]);
    const [stats, setStats] = useState({ open: 0, applicants: 0, interviews: 0, hires: 15 });
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function fetchData() {
            try {
                // Fetch Jobs
                const { data: jobData } = await insforge.database
                    .from('jobs')
                    .select('*')
                    .order('created_at', { ascending: false });

                const openJobs = jobData || [];
                setJobs(openJobs);

                // Fetch Candidates (mocking top matches)
                const { data: candData } = await insforge.database
                    .from('candidate_profiles')
                    .select('*')
                    .order('ai_karma', { ascending: false })
                    .limit(3);
                setCandidates(candData || []);

                // Fetch Today's Interviews
                const { data: intData } = await insforge.database
                    .from('interviews')
                    .select('*')
                    .limit(2);
                setInterviews(intData || []);

                // Calculate Stats
                const totalApplicants = openJobs.reduce((acc, j) => acc + (j.applicants || 0), 0);
                setStats({
                    open: openJobs.length,
                    applicants: totalApplicants,
                    interviews: 6, // Hardcoded for now
                    hires: 15
                });

            } catch (error) {
                console.error('Error fetching data:', error);
            } finally {
                setLoading(false);
            }
        }
        fetchData();
    }, []);

    if (loading) return <div className={styles.dash}><p style={{ color: 'white', padding: '2rem' }}>Loading Dashboard...</p></div>;

    return (
        <div className={styles.dash}>
            <div className={styles.greet}>
                <h1 className={styles.greetTitle}>Welcome back, Harper!</h1>
                <p className={styles.greetSub}>Here's your hiring pipeline overview.</p>
            </div>

            <AnimateOnScroll animation="fadeUp" delay={100}>
                <div className={styles.stats}>
                    <div className={styles.stat}>
                        <div className={styles.statTop}>
                            <span className={styles.statLabel}>Open Positions</span>
                            <span className={styles.statBox} style={{ background: '#eff6ff', color: 'var(--primary-blue)' }}>{IC.clipboard}</span>
                        </div>
                        <span className={styles.statVal}>{stats.open}</span>
                        <span className={styles.statHint}>3 urgent roles</span>
                    </div>
                    <div className={styles.stat}>
                        <div className={styles.statTop}>
                            <span className={styles.statLabel}>Total Applicants</span>
                            <span className={styles.statBox} style={{ background: '#f0fdf4', color: '#10b981' }}>{IC.users}</span>
                        </div>
                        <span className={styles.statVal}>{stats.applicants}</span>
                        <span className={styles.statChange}>{IC.trending} +18 this week</span>
                    </div>
                    <div className={styles.stat}>
                        <div className={styles.statTop}>
                            <span className={styles.statLabel}>Interviews This Week</span>
                            <span className={styles.statBox} style={{ background: '#fef3c7', color: '#f59e0b' }}>{IC.calendar}</span>
                        </div>
                        <span className={styles.statVal}>{stats.interviews}</span>
                        <span className={styles.statHint}>Next: Today, 3:00 PM</span>
                    </div>
                    <div className={styles.stat}>
                        <div className={styles.statTop}>
                            <span className={styles.statLabel}>Hires This Quarter</span>
                            <span className={styles.statBox} style={{ background: '#f5f3ff', color: '#7c3aed' }}>{IC.checkCircle}</span>
                        </div>
                        <span className={styles.statVal}>{stats.hires}</span>
                        <span className={styles.statHint}>Target: 20</span>
                    </div>
                </div>
            </AnimateOnScroll>

            <AnimateOnScroll animation="fadeUp" delay={200}>

                <div className={styles.mainGrid}>
                    <div className={styles.leftCol}>
                        <div className={styles.card}>
                            <div className={styles.cardHead}>
                                <h2 className={styles.cardTitle}>Active Positions</h2>
                                <button className={styles.viewAll}>View all</button>
                            </div>
                            {jobs.map((j, i) => (
                                <div key={i} className={styles.posCard}>
                                    <div className={styles.posBody}>
                                        <div className={styles.posRow}>
                                            <span className={styles.posTitle}>{j.title}</span>
                                            {j.applicants > 50 && <span className={styles.urgentTag}>{IC.alertCircle} Hot</span>}
                                        </div>
                                        <span className={styles.posMeta}>{j.applicants} applicants · {j.new_applicants} new</span>
                                    </div>
                                    <span className={styles.posStatus}>{j.status}</span>
                                </div>
                            ))}
                        </div>

                        <div className={styles.card}>
                            <h2 className={styles.cardTitle}>Hiring Pipeline</h2>
                            <div className={styles.pipelineBar}>
                                {[
                                    { label: 'Screening', count: 48, width: '35%', color: '#3b82f6' },
                                    { label: 'Interview', count: 22, width: '25%', color: '#7c3aed' },
                                    { label: 'Assessment', count: 14, width: '20%', color: '#f59e0b' },
                                    { label: 'Offer', count: 8, width: '20%', color: '#10b981' },
                                ].map((s, i) => (
                                    <div key={i} className={styles.pipeSegment}>
                                        <div className={styles.pipeBar} style={{ width: s.width, background: s.color }} />
                                        <div className={styles.pipeMeta}>
                                            <span className={styles.pipeLabel}>{s.label}</span>
                                            <span className={styles.pipeCount}>{s.count}</span>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>

                    <div className={styles.rightCol}>
                        <div className={styles.card}>
                            <div className={styles.cardHead}>
                                <h2 className={styles.cardTitle}>Top Candidates</h2>
                                <button className={styles.viewAll}>View all</button>
                            </div>
                            {candidates.map((c, i) => (
                                <div key={i} className={styles.candCard}>
                                    <div className={styles.candAvatar}>{c.name.split(' ').map((n: string) => n[0]).join('')}</div>
                                    <div className={styles.candBody}>
                                        <span className={styles.candName}>{c.name}</span>
                                        <span className={styles.candMeta}>{c.role} · {c.skills?.slice(0, 2).join(', ')}</span>
                                    </div>
                                    <span className={styles.candMatch}>{Math.min(100, (c.ai_karma / 5) || 90).toFixed(0)}%</span>
                                </div>
                            ))}
                        </div>

                        <div className={styles.card}>
                            <h2 className={styles.cardTitle}>Today's Interviews</h2>
                            {interviews.length > 0 ? interviews.map((intr, i) => (
                                <div key={i} className={styles.intCard}>
                                    <div className={styles.intTime}>{intr.time}</div>
                                    <div className={styles.intBody}>
                                        <span className={styles.intName}>{intr.role}</span>
                                        <span className={styles.intType}>{intr.type} Round</span>
                                    </div>
                                    <button className={styles.intBtn}>Join</button>
                                </div>
                            )) : (
                                <p className={styles.emptyText}>No interviews scheduled for today.</p>
                            )}
                        </div>

                        <div className={styles.card}>
                            <h2 className={styles.cardTitle}>Quick Actions</h2>
                            <button className={styles.primaryAction}>{IC.plus} Post a New Job</button>
                            <button className={styles.secondaryAction}>{IC.barChart} View Reports</button>
                            <button className={styles.secondaryAction}>{IC.users} Browse Candidates</button>
                        </div>
                    </div>
                </div>
            </AnimateOnScroll>
        </div>
    );
}

"use client";
import React, { useEffect, useState } from 'react';
import styles from './candidate.module.css';
import AnimateOnScroll from '@/components/AnimateOnScroll';
import { insforge } from '@/lib/insforge';

/* ─── Inline SVG icons ─── */
