export default function CandidateInterests() {
    const [selected, setSelected] = useState<string[]>([]);
    const router = useRouter();

    const toggle = (id: string) => {
        setSelected(prev =>
            prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
        );
    };

    return (
        <div className={styles.card}>
            {/* Stepper */}
            <div className={styles.stepper}>
                <span className={`${styles.stepDot} ${styles.stepDotActive}`}>1</span>
                <span className={styles.stepLine} />
                <span className={styles.stepDot}>2</span>
                <span className={styles.stepLine} />
                <span className={styles.stepDot}>3</span>
            </div>

            <div className={styles.header}>
                <h1 className={styles.title}>What interests you?</h1>
                <p className={styles.subtitle}>Select the job categories you're interested in</p>
            </div>

            <div className={styles.chipGrid}>
                {CATEGORIES.map(cat => (
                    <button
                        key={cat.id}
                        type="button"
                        className={`${styles.chip} ${selected.includes(cat.id) ? styles.chipSelected : ''}`}
                        onClick={() => toggle(cat.id)}
                    >
                        <span className={styles.chipIcon}>{cat.icon}</span>
                        {cat.label}
                    </button>
                ))}
            </div>

            <p className={styles.counter}>{selected.length} selected</p>

            <div className={styles.actions}>
                <button className={styles.nextBtn} onClick={() => router.push('/onboarding/candidate/skills')} disabled={selected.length === 0}>
                    Continue
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="5" y1="12" x2="19" y2="12" /><polyline points="12 5 19 12 12 19" /></svg>
                </button>
            </div>
        </div>
    );
}

"use client";
import React, { useState, useRef } from 'react';
import { useRouter } from 'next/navigation';
import styles from '../../onboarding.module.css';

export default function CandidateDocuments() {
    const [resume, setResume] = useState<File | null>(null);
    const [portfolio, setPortfolio] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const fileRef = useRef<HTMLInputElement>(null);
    const router = useRouter();

    const handleFile = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            setResume(e.target.files[0]);
        }
    };

    const handleFinish = () => {
        setIsLoading(true);
        setTimeout(() => {
            setIsLoading(false);
            router.push('/dashboard/candidate');
        }, 1500);
    };

    return (
        <div className={styles.card}>
            <div className={styles.stepper}>
                <span className={`${styles.stepDot} ${styles.stepDotDone}`}>
                    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12" /></svg>
                </span>
                <span className={`${styles.stepLine} ${styles.stepLineDone}`} />
                <span className={`${styles.stepDot} ${styles.stepDotDone}`}>
                    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12" /></svg>
                </span>
                <span className={`${styles.stepLine} ${styles.stepLineActive}`} />
                <span className={`${styles.stepDot} ${styles.stepDotActive}`}>3</span>
            </div>

            <div className={styles.header}>
                <h1 className={styles.title}>Upload your resume</h1>
                <p className={styles.subtitle}>Help employers find you faster</p>
            </div>

            <input type="file" ref={fileRef} onChange={handleFile} accept=".pdf,.doc,.docx" hidden />

            <div
                className={`${styles.uploadArea} ${resume ? styles.uploadAreaActive : ''}`}
                onClick={() => fileRef.current?.click()}
            >
                {resume ? (
                    <>
                        <svg className={styles.uploadIcon} width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                            <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" /><polyline points="22 4 12 14.01 9 11.01" />
                        </svg>
                        <span className={styles.uploadText}>{resume.name}</span>
                        <span className={styles.uploadHint}>Click to replace</span>
                    </>
                ) : (
                    <>
                        <svg className={styles.uploadIcon} width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                            <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" /><polyline points="17 8 12 3 7 8" /><line x1="12" y1="3" x2="12" y2="15" />
                        </svg>
                        <span className={styles.uploadText}>Drop your resume here or click to browse</span>
                        <span className={styles.uploadHint}>PDF, DOC, DOCX — max 10MB</span>
                    </>
                )}
            </div>

            <div className={styles.optionalField}>
                <label className={styles.optionalLabel}>Portfolio URL (optional)</label>
                <input
                    type="url"
                    className={styles.optionalInput}
                    placeholder="https://yourportfolio.com"
                    value={portfolio}
                    onChange={e => setPortfolio(e.target.value)}
                />
            </div>

            <div className={styles.actions}>
                <button className={styles.backBtn} onClick={() => router.push('/onboarding/candidate/skills')}>
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="19" y1="12" x2="5" y2="12" /><polyline points="12 19 5 12 12 5" /></svg>
                    Back
                </button>
                <button className={styles.nextBtn} onClick={handleFinish} disabled={isLoading}>
                    {isLoading ? 'Setting up...' : 'Finish Setup'}
                    {!isLoading && <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="5" y1="12" x2="19" y2="12" /><polyline points="12 5 19 12 12 19" /></svg>}
                </button>
            </div>

            <p className={styles.skipLink}>
                <button className={styles.skipBtn} onClick={() => router.push('/dashboard/candidate')}>Skip for now</button>
            </p>
        </div>
    );
}

"use client";
import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import styles from '../recruiter.module.css';
import { insforge } from '@/lib/insforge';
import { useAuth } from '@/lib/auth/AuthContext';

const IC = {
    plus: <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><line x1="12" y1="5" x2="12" y2="19" /><line x1="5" y1="12" x2="19" y2="12" /></svg>,
    mapPin: <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z" /><circle cx="12" cy="10" r="3" /></svg>,
};

export default function RecruiterJobsPage() {
    const { user } = useAuth();
    const [jobs, setJobs] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function fetchJobs() {
            if (!user?.company_id) {
                setLoading(false);
                return;
            }
            try {
                const { data } = await insforge.database
                    .from('jobs')
                    .select('*, applications(count)')
                    .eq('company_id', user.company_id);

                setJobs(data || []);
            } catch (err) {
                console.error(err);
            } finally {
                setLoading(false);
            }
        }
        fetchJobs();
    }, [user]);

    if (loading) return <div className={styles.loading}>Loading your postings...</div>;

    return (
        <div className={styles.jobsPage}>
            <div className={styles.pageHead}>
                <h1 className={styles.pageTitle}>Job Postings</h1>
                <Link href="/dashboard/recruiter/jobs/post-job" className={styles.createBtn}>
                    {IC.plus} Post a New Job
                </Link>
            </div>
            {jobs.length === 0 ? (
                <div className={styles.emptyState}>
                    <p>You haven't posted any jobs yet.</p>
                </div>
            ) : (
                jobs.map((j, i) => (
                    <div key={i} className={styles.jobPostCard}>
                        <div className={styles.jobPostBody}>
                            <span className={styles.jobPostTitle}>{j.title}</span>
                            <span className={styles.jobPostMeta}>{IC.mapPin} {j.location || 'Remote'} · Posted {new Date(j.created_at).toLocaleDateString()}</span>
                            <div className={styles.jobPostStats}>
                                <span className={styles.jobPostStat}>{(j.applications?.[0]?.count || 0)} applicants</span>
                                <span className={styles.jobPostStat}>0 new</span>
                                <span className={styles.jobPostStat} style={{ color: j.status === 'active' ? '#10b981' : '#f59e0b' }}>● {j.status || 'Active'}</span>
                            </div>
                        </div>
                        <div className={styles.jobPostActions}>
                            <button className={styles.editBtn}>Edit</button>
                            <button className={styles.editBtn}>View Applicants</button>
                        </div>
                    </div>
                ))
            )}
        </div>
    );
}

