import { useRouter } from 'next/navigation';

const IC = {
    search: <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2"><circle cx="11" cy="11" r="8" /><path d="m21 21-4.3-4.3" /></svg>,
    mapPin: <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z" /><circle cx="12" cy="10" r="3" /></svg>,
};

export default function AdminJobsPage() {
    const { user, isLoading: authLoading } = useAuth();
    const router = useRouter();
    const [jobs, setJobs] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (!authLoading && (!user || user.role !== 'super_admin')) {
            router.push('/dashboard/candidate');
            return;
        }

        async function fetchJobs() {
            try {
                const { data } = await insforge.database
                    .from('jobs')
                    .select('*, company_profiles(company_name)')
                    .order('created_at', { ascending: false });
                setJobs(data || []);
            } catch (err) {
                console.error('Fetch jobs error:', err);
            } finally {
                setLoading(false);
            }
        }

        if (user?.role === 'super_admin') fetchJobs();
    }, [user, authLoading, router]);

    const handleStatusUpdate = async (jobId: string, newStatus: string) => {
        try {
            const { error } = await insforge.database
                .from('jobs')
                .update({ status: newStatus })
                .eq('id', jobId);
            if (error) throw error;
            setJobs(prev => prev.map(j => j.id === jobId ? { ...j, status: newStatus } : j));
            alert(`Job status updated to ${newStatus}`);
        } catch (err) {
            console.error(err);
            alert('Failed to update job status');
        }
    };

    const handleDelete = async (jobId: string) => {
        if (!confirm('Are you sure you want to delete this job?')) return;
        try {
            const { error } = await insforge.database
                .from('jobs')
                .delete()
                .eq('id', jobId);
            if (error) throw error;
            setJobs(prev => prev.filter(j => j.id !== jobId));
            alert('Job deleted');
        } catch (err) {
            console.error(err);
            alert('Failed to delete job');
        }
    };

    if (authLoading || loading) return <div className={styles.loading}>Loading jobs...</div>;

    const statusClass = (s: string) => {
        if (s === 'active') return styles.badgeActive;
        if (s === 'pending') return styles.badgePending;
        if (s === 'flagged') return styles.badgeClosed; // repurposed
        return styles.badgeClosed;
    };

    return (
        <div className={styles.dash}>
            <div className={styles.pageHead}>
                <h1 className={styles.pageTitle}>Manage Jobs</h1>
                <p className={styles.pageSub}>Oversee all job listings and maintain platform content quality.</p>
            </div>

            <div className={styles.card}>
                <table className={styles.table}>
                    <thead>
                        <tr>
                            <th>Job Title</th>
                            <th>Company</th>
                            <th>Location</th>
                            <th>Status</th>
                            <th>Posted</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {jobs.map(j => (
                            <tr key={j.id}>
                                <td style={{ fontWeight: 600 }}>{j.title}</td>
                                <td>{j.company_profiles?.company_name}</td>
                                <td style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}>{IC.mapPin} {j.location}</td>
                                <td><span className={`${styles.badge} ${statusClass(j.status)}`}>{j.status}</span></td>
                                <td style={{ fontSize: '0.78rem', color: '#64748b' }}>{new Date(j.created_at).toLocaleDateString()}</td>
                                <td>
                                    <div style={{ display: 'flex', gap: '0.3rem' }}>
                                        {j.status === 'pending' && <button className={styles.successBtn} onClick={() => handleStatusUpdate(j.id, 'active')}>Approve</button>}
                                        {j.status !== 'flagged' && <button className={styles.secondaryBtn} onClick={() => handleStatusUpdate(j.id, 'flagged')}>Flag</button>}
                                        <button className={styles.dangerBtn} onClick={() => handleDelete(j.id)}>Delete</button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}

"use client";
import React, { useState, useEffect } from 'react';
import styles from '../admin.module.css';
import { insforge } from '@/lib/insforge';
import { useAuth } from '@/lib/auth/AuthContext';
import { useRouter } from 'next/navigation';

const IC = {
    search: <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2"><circle cx="11" cy="11" r="8" /><path d="m21 21-4.3-4.3" /></svg>,
    check: <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><polyline points="20 6 9 17 4 12" /></svg>,
    x: <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><line x1="18" y1="6" x2="6" y2="18" /><line x1="6" y1="6" x2="18" y2="18" /></svg>,
    mail: <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z" /><polyline points="22,6 12,13 2,6" /></svg>,
};

export default function AdminCandidatesPage() {
    const { user, isLoading: authLoading } = useAuth();
    const router = useRouter();
    const [applications, setApplications] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [stats, setStats] = useState({ total: 0, pending: 0, accepted: 0, rejected: 0 });

    useEffect(() => {
        if (!authLoading && (!user || user.role !== 'super_admin')) {
            router.push('/dashboard/candidate');
            return;
        }

        async function fetchData() {
            try {
                const { data } = await insforge.database
                    .from('applications')
                    .select('*, jobs(title, company_profiles(company_name)), profiles(full_name, email)')
                    .order('created_at', { ascending: false });

                setApplications(data || []);

                // Calculate stats
                const s = (data || []).reduce((acc: any, app: any) => {
                    acc.total++;
                    if (app.status === 'applied' || app.status === 'pending') acc.pending++;
                    else if (app.status === 'accepted') acc.accepted++;
                    else if (app.status === 'rejected') acc.rejected++;
                    return acc;
                }, { total: 0, pending: 0, accepted: 0, rejected: 0 });
                setStats(s);

            } catch (err) {
                console.error('Fetch apps error:', err);
            } finally {
                setLoading(false);
            }
        }

        if (user?.role === 'super_admin') fetchData();
    }, [user, authLoading, router]);

    const handleStatusUpdate = async (appId: string, newStatus: string) => {
        try {
            const { error } = await insforge.database
                .from('applications')
                .update({ status: newStatus })
                .eq('id', appId);

            if (error) throw error;

            setApplications(prev => prev.map(a => a.id === appId ? { ...a, status: newStatus } : a));
            alert(`Application ${newStatus}`);
        } catch (err) {
            console.error(err);
            alert('Status update failed');
        }
    };

    if (authLoading || loading) return <div className={styles.loading}>Loading applications...</div>;

    const statusClass = (s: string) => {
        if (s === 'accepted') return styles.badgeActive;
        if (s === 'applied' || s === 'pending') return styles.badgePending;
        return styles.badgeClosed;
    };

    return (
        <div className={styles.dash}>
            <div className={styles.pageHead}>
                <h1 className={styles.pageTitle}>Manage Candidates</h1>
                <p className={styles.pageSub}>Review platform-wide applications and oversee candidate progress.</p>
            </div>

            <div className={styles.stats} style={{ gridTemplateColumns: 'repeat(4, 1fr)' }}>
                <div className={styles.stat}><span className={styles.statLabel}>Total</span><span className={styles.statVal}>{stats.total}</span></div>
                <div className={styles.stat}><span className={styles.statLabel}>Pending</span><span className={styles.statVal} style={{ color: '#d97706' }}>{stats.pending}</span></div>
                <div className={styles.stat}><span className={styles.statLabel}>Accepted</span><span className={styles.statVal} style={{ color: '#16a34a' }}>{stats.accepted}</span></div>
                <div className={styles.stat}><span className={styles.statLabel}>Rejected</span><span className={styles.statVal} style={{ color: '#dc2626' }}>{stats.rejected}</span></div>
            </div>

            <div className={styles.card}>
                <table className={styles.table}>
                    <thead>
                        <tr>
                            <th>Candidate</th>
                            <th>Applied For</th>
                            <th>Company</th>
                            <th>Status</th>
                            <th>Date</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {applications.map((app, i) => (
                            <tr key={i}>
                                <td>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
                                        <div className={styles.avatar} style={{ background: '#0D47A1' }}>
                                            {(app.profiles?.full_name || 'U')[0].toUpperCase()}
                                        </div>
                                        <div>
                                            <div style={{ fontWeight: 600 }}>{app.profiles?.full_name || 'Unknown Candidate'}</div>
                                            <div style={{ fontSize: '0.7rem', color: '#94a3b8', display: 'flex', alignItems: 'center', gap: '0.2rem' }}>
                                                {IC.mail} {app.profiles?.email}
                                            </div>
                                        </div>
                                    </div>
                                </td>
                                <td style={{ fontWeight: 500 }}>{app.job?.title}</td>
                                <td>{app.jobs?.company_profiles?.company_name}</td>
                                <td><span className={`${styles.badge} ${statusClass(app.status)}`}>{app.status}</span></td>
                                <td style={{ fontSize: '0.78rem', color: '#64748b' }}>{new Date(app.created_at).toLocaleDateString()}</td>
                                <td>
                                    {(app.status === 'applied' || app.status === 'pending') && (
                                        <div style={{ display: 'flex', gap: '0.3rem' }}>
                                            <button className={styles.successBtn} onClick={() => handleStatusUpdate(app.id, 'accepted')}>{IC.check} Accept</button>
                                            <button className={styles.dangerBtn} onClick={() => handleStatusUpdate(app.id, 'rejected')}>{IC.x} Reject</button>
                                        </div>
                                    )}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}

"use client";
import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import styles from '../admin.module.css';
import { insforge } from '@/lib/insforge';
import { useAuth } from '@/lib/auth/AuthContext';
import { useRouter } from 'next/navigation';

const IC = {
    search: <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2"><circle cx="11" cy="11" r="8" /><path d="m21 21-4.3-4.3" /></svg>,
    plus: <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><line x1="12" y1="5" x2="12" y2="19" /><line x1="5" y1="12" x2="19" y2="12" /></svg>,
    edit: <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7" /><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z" /></svg>,
};

export default function AdminBlogsPage() {
    const { user, isLoading: authLoading } = useAuth();
    const router = useRouter();
    const [blogs, setBlogs] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (!authLoading && (!user || user.role !== 'super_admin')) {
            router.push('/dashboard/candidate');
            return;
        }

        async function fetchBlogs() {
            try {
                const { data } = await insforge.database
                    .from('blog')
                    .select('*, author:profiles(full_name)')
                    .order('created_at', { ascending: false });
                setBlogs(data || []);
            } catch (err) {
                console.error('Fetch blogs error:', err);
            } finally {
                setLoading(false);
            }
        }

        if (user?.role === 'super_admin') fetchBlogs();
    }, [user, authLoading, router]);

    const handleStatusUpdate = async (blogId: string, newStatus: string) => {
        try {
            const { error } = await insforge.database
                .from('blog')
                .update({ status: newStatus })
                .eq('id', blogId);
            if (error) throw error;
            setBlogs(prev => prev.map(b => b.id === blogId ? { ...b, status: newStatus } : b));
        } catch (err) {
            console.error(err);
            alert('Failed to update blog status');
        }
    };

    const handleDelete = async (blogId: string) => {
        if (!confirm('Are you sure you want to delete this blog?')) return;
        try {
            const { error } = await insforge.database
                .from('blog')
                .delete()
                .eq('id', blogId);
            if (error) throw error;
            setBlogs(prev => prev.filter(b => b.id !== blogId));
        } catch (err) {
            console.error(err);
            alert('Failed to delete blog');
        }
    };

    if (authLoading || loading) return <div className={styles.loading}>Loading blogs...</div>;

    return (
        <div className={styles.dash}>
            <div className={styles.pageHead}>
                <div>
                    <h1 className={styles.pageTitle}>Manage Blogs</h1>
                    <p className={styles.pageSub}>Write, edit and publish articles for the Talentmesh community.</p>
                </div>
                <Link href="/dashboard/admin/blogs/new" className={styles.primaryBtn}>
                    {IC.plus} Write Post
                </Link>
            </div>

            <div className={styles.card}>
                <table className={styles.table}>
                    <thead>
                        <tr>
                            <th>Title</th>
                            <th>Author</th>
                            <th>Category</th>
                            <th>Status</th>
                            <th>Created</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {blogs.map(b => (
                            <tr key={b.id}>
                                <td style={{ fontWeight: 600 }}>{b.title}</td>
                                <td>{b.author?.full_name || 'Admin'}</td>
                                <td><span className={styles.chip}>{b.category}</span></td>
                                <td>
                                    <span className={`${styles.badge} ${b.status === 'published' ? styles.badgeActive : styles.badgePending}`}>
                                        {b.status}
                                    </span>
                                </td>
                                <td style={{ fontSize: '0.8rem', color: '#64748b' }}>{new Date(b.created_at).toLocaleDateString()}</td>
                                <td>
                                    <div style={{ display: 'flex', gap: '0.5rem' }}>
                                        <Link href={`/dashboard/admin/blogs/edit/${b.id}`} className={styles.secondaryBtn} style={{ padding: '0.4rem' }}>
                                            {IC.edit}
                                        </Link>
                                        {b.status === 'draft' ? (
                                            <button className={styles.successBtn} onClick={() => handleStatusUpdate(b.id, 'published')}>Publish</button>
                                        ) : (
                                            <button className={styles.secondaryBtn} onClick={() => handleStatusUpdate(b.id, 'draft')}>Unpublish</button>
                                        )}
                                        <button className={styles.dangerBtn} onClick={() => handleDelete(b.id)}>Delete</button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}

